tokens.css:
/* ============================================================
   Sparkle Suite — Amethyst Design Tokens
   Single source of truth. Theme-switching across kits will
   replace this file's values; structure stays identical.
   ============================================================ */

:root {
  /* ---------- Color: Amethyst palette ---------- */
  --bg:           #E8DFF5;   /* Page background, card surfaces */
  --fg:           #2A1F40;   /* Primary text, headings, icons (NEVER #000) */
  --fg-muted:     #5C576A;   /* Secondary text, placeholders */
  --primary:      #D209E3;   /* CTAs, links, active states */
  --accent:       #480DDF;   /* Hover/pressed, deep emphasis */
  --border:       #C4C1CE;   /* Dividers, input borders, card outlines */

  /* Tinted neutrals derived from palette (for surfaces, hovers) */
  --bg-elevated:  #F2EBFA;   /* Lighter card surface for layered cards */
  --bg-deep:      #DCD0EE;   /* Pressed / selected fill */
  --header-bg:    #1A1230;   /* Slightly deeper than fg for header chrome */

  /* ---------- Type ---------- */
  --font-sans: "Vend Sans", "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", system-ui, sans-serif;

  --fs-hero:    clamp(48px, 6vw, 64px);
  --fs-h1:      clamp(32px, 4vw, 36px);
  --fs-h2:      clamp(24px, 3vw, 28px);
  --fs-h3:      22px;
  --fs-body:    16px;
  --fs-small:   14px;
  --fs-caption: 13px;

  --lh-tight:  1.1;
  --lh-snug:   1.25;
  --lh-normal: 1.5;
  --lh-loose:  1.65;

  --tracking-display: -0.01em;
  --tracking-body:    0;
  --tracking-caps:    0.08em;

  --fw-regular: 400;
  --fw-medium:  500;
  --fw-semi:    600;

  /* ---------- Spacing (8px base) ---------- */
  --s-1:  4px;
  --s-2:  8px;
  --s-3:  12px;
  --s-4:  16px;
  --s-5:  24px;
  --s-6:  32px;
  --s-7:  48px;
  --s-8:  64px;
  --s-9:  96px;

  /* ---------- Radius ---------- */
  --r-sm:   6px;   /* small chips, inputs */
  --r-md:   8px;   /* buttons */
  --r-lg:   10px;  /* cards (lower bound) */
  --r-xl:   12px;  /* cards (upper bound), modals */
  --r-pill: 999px;

  /* ---------- Shadows (minimal — depth, not drama) ---------- */
  --shadow-1: 0 1px 2px rgba(42, 31, 64, 0.06);
  --shadow-2: 0 4px 12px rgba(42, 31, 64, 0.08);
  --shadow-3: 0 12px 32px rgba(42, 31, 64, 0.12);

  /* ---------- Motion ---------- */
  --ease: cubic-bezier(.4, 0, .2, 1);
  --dur-fast: 200ms;
  --dur-base: 300ms;
  --dur-slow: 400ms;
  --dur-card: 400ms; /* per spec: 0.4s ease-in-out for trade card stack */

  /* ---------- Layout ---------- */
  --container-max: 1200px;
  --container-pad: 24px;
}

/* ============================================================
   Base
   ============================================================ */
* { box-sizing: border-box; }

html {
  max-width: 100%;
  overflow-x: clip;
}

html, body {
  margin: 0;
  padding: 0;
  max-width: 100%;
  overflow-x: clip;
  background: var(--bg);
  color: var(--fg);
  font-family: var(--font-sans);
  font-size: var(--fs-body);
  line-height: var(--lh-normal);
  letter-spacing: var(--tracking-body);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

#root {
  max-width: 100%;
  overflow-x: hidden;
}

h1, h2, h3, h4 {
  font-family: var(--font-sans);
  font-weight: var(--fw-semi);
  letter-spacing: var(--tracking-display);
  line-height: var(--lh-tight);
  margin: 0;
}

h1 { font-size: var(--fs-h1); }
h2 { font-size: var(--fs-h2); }
h3 { font-size: var(--fs-h3); }

p { margin: 0; }

a {
  color: var(--primary);
  text-decoration: none;
  transition: color var(--dur-fast) var(--ease);
}
a:hover { color: var(--accent); }

button {
  font-family: inherit;
  cursor: pointer;
  border: 0;
  background: transparent;
  color: inherit;
}

img { display: block; max-width: 100%; }

/* ============================================================
   Page chrome for design system reference
   ============================================================ */
.page {
  min-height: 100vh;
  background: var(--bg);
}

.container {
  max-width: var(--container-max);
  margin: 0 auto;
  padding: 0 var(--container-pad);
}

.system-header {
  position: sticky;
  top: 0;
  z-index: 50;
  background: rgba(232, 223, 245, 0.85);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border);
}

.system-header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px 24px;
  max-width: var(--container-max);
  margin: 0 auto;
}

.system-mark {
  display: flex;
  align-items: center;
  gap: 12px;
  font-size: 14px;
  font-weight: var(--fw-medium);
  letter-spacing: var(--tracking-caps);
  text-transform: uppercase;
  color: var(--fg);
}

.system-mark-glyph {
  width: 22px;
  height: 22px;
  background: linear-gradient(135deg, var(--primary), var(--accent));
  transform: rotate(45deg);
  border-radius: 2px;
}

.system-nav {
  display: flex;
  gap: 24px;
  font-size: 13px;
  letter-spacing: var(--tracking-caps);
  text-transform: uppercase;
}
.system-nav a { color: var(--fg-muted); font-weight: var(--fw-medium); }
.system-nav a:hover { color: var(--fg); }

/* Section scaffolding for the design system doc */
.ds-section {
  padding: 96px 0 64px;
  border-bottom: 1px solid var(--border);
}
.ds-section:last-child { border-bottom: 0; }

.ds-section-header {
  margin-bottom: 48px;
  display: grid;
  grid-template-columns: 200px 1fr;
  gap: 32px;
  align-items: baseline;
}
.ds-section-num {
  font-family: ui-monospace, "SF Mono", Menlo, monospace;
  font-size: 13px;
  letter-spacing: var(--tracking-caps);
  color: var(--fg-muted);
  text-transform: uppercase;
}
.ds-section-title { font-size: 36px; }
.ds-section-desc {
  margin-top: 12px;
  max-width: 680px;
  color: var(--fg-muted);
  font-size: 16px;
  line-height: var(--lh-loose);
}

@media (max-width: 720px) {
  .ds-section-header { grid-template-columns: 1fr; gap: 8px; }
  .ds-section { padding: 64px 0 48px; }
}

/* Variation tile — a labeled box for showing options side-by-side */
.variant-grid {
  display: grid;
  gap: 24px;
  grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
}
.variant {
  background: var(--bg-elevated);
  border: 1px solid var(--border);
  border-radius: var(--r-xl);
  padding: 24px;
  position: relative;
  overflow: hidden;
}
.variant-label {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 20px;
  font-size: 11px;
  letter-spacing: var(--tracking-caps);
  text-transform: uppercase;
  color: var(--fg-muted);
}
.variant-tag {
  font-family: ui-monospace, "SF Mono", Menlo, monospace;
  background: var(--bg-deep);
  color: var(--fg);
  padding: 3px 8px;
  border-radius: var(--r-sm);
  font-size: 10px;
}
.variant-title {
  font-size: 18px;
  font-weight: var(--fw-semi);
  margin-bottom: 8px;
  color: var(--fg);
}
.variant-desc {
  font-size: 13px;
  color: var(--fg-muted);
  margin-bottom: 24px;
  line-height: var(--lh-loose);
}
.variant-stage {
  background: var(--bg);
  border-radius: var(--r-lg);
  padding: 32px 24px;
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 140px;
  border: 1px dashed var(--border);
}

/* Slot indicator — marks rep-customizable elements */
.slot {
  position: relative;
  outline: 1px dashed transparent;
  transition: outline-color var(--dur-fast) var(--ease);
}
.slots-on .slot {
  outline-color: var(--primary);
  outline-offset: 4px;
}
.slot::before {
  content: attr(data-slot);
  position: absolute;
  top: -10px;
  left: 0;
  background: var(--primary);
  color: white;
  font-size: 9px;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  padding: 2px 6px;
  border-radius: 3px;
  font-family: ui-monospace, "SF Mono", Menlo, monospace;
  opacity: 0;
  transition: opacity var(--dur-fast) var(--ease);
  pointer-events: none;
  z-index: 5;
}
.slots-on .slot::before { opacity: 1; }

/* Toggle for slot overlay */
.slot-toggle {
  position: fixed;
  bottom: 24px;
  left: 24px;
  z-index: 100;
  background: var(--fg);
  color: var(--bg);
  border-radius: var(--r-pill);
  padding: 10px 16px;
  font-size: 12px;
  letter-spacing: var(--tracking-caps);
  text-transform: uppercase;
  font-weight: var(--fw-medium);
  display: flex;
  align-items: center;
  gap: 8px;
  border: 1px solid var(--fg);
  transition: all var(--dur-fast) var(--ease);
}
.slot-toggle:hover { background: var(--accent); border-color: var(--accent); }
.slot-toggle .dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--fg-muted);
  transition: background var(--dur-fast) var(--ease);
}
.slots-on .slot-toggle .dot { background: var(--primary); box-shadow: 0 0 0 4px rgba(210, 9, 227, 0.2); }

components.css:
/* ============================================================
   Component-specific styles for the Amethyst design system
   ============================================================ */

/* ---------- Color swatches ---------- */
.swatch-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 16px;
}
.swatch {
  background: var(--bg-elevated);
  border: 1px solid var(--border);
  border-radius: var(--r-lg);
  overflow: hidden;
}
.swatch-color { height: 120px; }
.swatch-meta { padding: 16px; }
.swatch-role {
  font-size: 11px;
  letter-spacing: var(--tracking-caps);
  text-transform: uppercase;
  color: var(--fg-muted);
  margin-bottom: 4px;
}
.swatch-name {
  font-size: 16px;
  font-weight: var(--fw-medium);
  margin-bottom: 8px;
}
.swatch-hex {
  font-family: ui-monospace, "SF Mono", Menlo, monospace;
  font-size: 12px;
  color: var(--fg-muted);
}

/* ---------- Type specimen ---------- */
.type-row {
  display: grid;
  grid-template-columns: 140px 1fr;
  gap: 32px;
  padding: 24px 0;
  border-bottom: 1px solid var(--border);
  align-items: baseline;
}
.type-row:last-child { border-bottom: 0; }
.type-meta {
  font-family: ui-monospace, "SF Mono", Menlo, monospace;
  font-size: 12px;
  color: var(--fg-muted);
  letter-spacing: var(--tracking-caps);
  text-transform: uppercase;
}

/* ============================================================
   BUTTONS — 6 variations
   ============================================================ */

/* base reset for all amethyst buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  font-family: inherit;
  font-size: 14px;
  font-weight: var(--fw-medium);
  letter-spacing: 0.02em;
  cursor: pointer;
  border: 0;
  background: transparent;
  color: inherit;
  padding: 14px 28px;
  border-radius: var(--r-md);
  position: relative;
  overflow: hidden;
  transition: all var(--dur-base) var(--ease);
  text-transform: none;
  white-space: nowrap;
}
.btn:focus-visible {
  outline: 2px solid var(--primary);
  outline-offset: 3px;
}

/* B1: Gradient Glow */
.btn-gradient {
  background: linear-gradient(135deg, var(--primary), var(--accent));
  color: white;
  box-shadow: 0 4px 16px rgba(210, 9, 227, 0.25);
}
.btn-gradient:hover {
  transform: translateY(-1px);
  box-shadow: 0 8px 24px rgba(72, 13, 223, 0.4), 0 0 0 1px rgba(255,255,255,0.1) inset;
}
.btn-gradient:active { transform: translateY(0); }

/* B2: Sharp Edge — flat, hairline animates */
.btn-sharp {
  background: var(--fg);
  color: var(--bg);
  border-radius: 4px;
  position: relative;
}
.btn-sharp::after {
  content: "";
  position: absolute;
  inset: -1px;
  border: 1px solid var(--primary);
  border-radius: 4px;
  opacity: 0;
  transform: scale(1.02);
  transition: all var(--dur-base) var(--ease);
}
.btn-sharp:hover { background: var(--accent); }
.btn-sharp:hover::after { opacity: 1; transform: scale(1.06); }

/* B3: Outline-to-fill — editorial */
.btn-outline {
  background: transparent;
  color: var(--fg);
  border: 1px solid var(--fg);
  position: relative;
  z-index: 1;
}
.btn-outline::before {
  content: "";
  position: absolute;
  inset: 0;
  background: var(--fg);
  transform: scaleX(0);
  transform-origin: left;
  transition: transform var(--dur-slow) var(--ease);
  z-index: -1;
}
.btn-outline:hover { color: var(--bg); border-color: var(--fg); }
.btn-outline:hover::before { transform: scaleX(1); }

/* B4: Dual-layer — stacked rectangles align */
.btn-dual {
  background: transparent;
  color: var(--fg);
  position: relative;
  border: 1px solid var(--fg);
  border-radius: 4px;
}
.btn-dual::before {
  content: "";
  position: absolute;
  inset: 0;
  border: 1px solid var(--primary);
  border-radius: 4px;
  transform: translate(5px, 5px);
  transition: transform var(--dur-base) var(--ease);
  pointer-events: none;
}
.btn-dual:hover::before { transform: translate(0, 0); }
.btn-dual:hover { background: var(--primary); color: white; border-color: var(--primary); }

/* B5: Magnetic underline — text + animated bar */
.btn-underline {
  background: transparent;
  color: var(--fg);
  padding: 8px 0;
  border-radius: 0;
  font-weight: var(--fw-semi);
  position: relative;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  font-size: 13px;
}
.btn-underline::after {
  content: "";
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 2px;
  background: var(--fg);
  transform-origin: right;
  transition: transform var(--dur-base) var(--ease), background var(--dur-fast) var(--ease);
}
.btn-underline:hover::after {
  background: var(--primary);
  animation: underlineSweep 600ms var(--ease);
}
@keyframes underlineSweep {
  0%   { transform: scaleX(1); transform-origin: right; }
  49%  { transform: scaleX(0); transform-origin: right; }
  50%  { transform: scaleX(0); transform-origin: left; }
  100% { transform: scaleX(1); transform-origin: left; }
}

/* B6: Sparkle Burst — clean fill, sparkle on press */
.btn-sparkle {
  background: var(--primary);
  color: white;
  position: relative;
  overflow: visible;
}
.btn-sparkle:hover { background: var(--accent); }
.btn-sparkle .spark {
  position: absolute;
  width: 4px;
  height: 4px;
  background: white;
  border-radius: 50%;
  pointer-events: none;
  opacity: 0;
}
.btn-sparkle:hover .spark { animation: sparkPop 700ms var(--ease) forwards; }
.btn-sparkle .spark:nth-child(1) { top: -4px; left: 20%; animation-delay: 0ms; }
.btn-sparkle .spark:nth-child(2) { top: 50%; right: -6px; animation-delay: 80ms; }
.btn-sparkle .spark:nth-child(3) { bottom: -4px; left: 60%; animation-delay: 160ms; }
.btn-sparkle .spark:nth-child(4) { top: 20%; left: -6px; animation-delay: 240ms; }
@keyframes sparkPop {
  0%   { opacity: 0; transform: scale(0.5); }
  40%  { opacity: 1; transform: scale(1.4); }
  100% { opacity: 0; transform: scale(0.5); }
}

/* Secondary / size mods (shared) */
.btn-sm { padding: 10px 18px; font-size: 13px; }
.btn-lg { padding: 18px 36px; font-size: 16px; }

/* ============================================================
   Header bar (locked dark)
   ============================================================ */
.site-header {
  background: var(--header-bg);
  color: white;
}
.site-header-inner {
  max-width: var(--container-max);
  margin: 0 auto;
  padding: 18px 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.site-brand {
  display: flex;
  align-items: center;
  gap: 12px;
  font-size: 16px;
  font-weight: var(--fw-semi);
  letter-spacing: var(--tracking-display);
}
.site-brand-glyph {
  width: 24px;
  height: 24px;
  background: linear-gradient(135deg, var(--primary), var(--accent));
  transform: rotate(45deg);
  border-radius: 3px;
}
.site-nav {
  display: flex;
  gap: 32px;
  font-size: 13px;
  letter-spacing: var(--tracking-caps);
  text-transform: uppercase;
  font-weight: var(--fw-medium);
}
.site-nav a { color: rgba(255,255,255,0.75); }
.site-nav a:hover { color: white; }
.site-nav a.active { color: white; }
.site-nav .external::after {
  content: "↗";
  margin-left: 6px;
  opacity: 0.6;
}

/* ============================================================
   Announcement banner (bold strip per user pick)
   ============================================================ */
.announce {
  background: var(--primary);
  color: white;
  padding: 10px 24px;
  text-align: center;
  font-size: 13px;
  font-weight: var(--fw-medium);
  letter-spacing: 0.02em;
  position: relative;
}
.announce strong { font-weight: var(--fw-semi); margin-right: 6px; }
.announce-close {
  position: absolute;
  right: 16px;
  top: 50%;
  transform: translateY(-50%);
  color: rgba(255,255,255,0.7);
  font-size: 18px;
  line-height: 1;
  padding: 4px 8px;
}
.announce-close:hover { color: white; }

/* ============================================================
   Tickers (3 variations)
   ============================================================ */
.ticker {
  --ticker-duration: 72s;
  --trade-ticker-duration: 60s;
  --ticker-speed-pps: 46;
  --trade-ticker-speed-pps: 55.2;
  background: var(--fg);
  color: var(--bg);
  padding: 14px 0;
  overflow: hidden;
  position: relative;
  white-space: nowrap;
  border-top: 1px solid rgba(255,255,255,0.08);
  border-bottom: 1px solid rgba(255,255,255,0.08);
}
.ticker-track {
  display: inline-flex;
  gap: 48px;
  animation: tickerScroll 72s linear infinite;
  padding-left: 48px;
}
.ticker-item {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  font-size: 13px;
  letter-spacing: var(--tracking-caps);
  text-transform: uppercase;
  font-weight: var(--fw-medium);
}
.ticker-item .dot {
  width: 5px;
  height: 5px;
  background: var(--primary);
  border-radius: 50%;
}
@keyframes tickerScroll {
  to { transform: translateX(-50%); }
}

/* T2: skewed/diagonal */
.ticker-skew {
  background: var(--bg-deep);
  color: var(--fg);
  transform: rotate(-2deg);
  margin: 24px -8px;
  border-top: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
}
.ticker-skew .ticker-item .dot { background: var(--accent); }

/* T3: dual-row counter-scroll */
.ticker-dual { padding: 0; }
.ticker-row {
  padding: 12px 0;
  overflow: hidden;
  white-space: nowrap;
  border-bottom: 1px solid rgba(255,255,255,0.08);
}
.ticker-row:last-child { border-bottom: 0; }
.ticker-row .ticker-track { animation-duration: var(--ticker-dynamic-duration, var(--ticker-duration, 72s)); }
.ticker-row.reverse .ticker-track { animation-direction: reverse; animation-duration: var(--ticker-dynamic-duration, var(--trade-ticker-duration, 60s)); }

/* T4: vertical rotator */
.ticker-rotator {
  background: var(--fg);
  color: var(--bg);
  padding: 14px 24px;
  overflow: hidden;
  position: relative;
  height: 44px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 13px;
  letter-spacing: var(--tracking-caps);
  text-transform: uppercase;
  font-weight: var(--fw-medium);
}
.rotator-stack {
  display: flex;
  flex-direction: column;
  gap: 0;
  animation: rotatorScroll 12s steps(4) infinite;
}
.rotator-stack > span { height: 16px; line-height: 16px; padding: 0; }
@keyframes rotatorScroll {
  0%, 22%   { transform: translateY(0); }
  25%, 47%  { transform: translateY(-16px); }
  50%, 72%  { transform: translateY(-32px); }
  75%, 97%  { transform: translateY(-48px); }
  100%      { transform: translateY(-64px); }
}

/* ============================================================
   Hero variations (5)
   ============================================================ */
.hero-mini {
  position: relative;
  border-radius: var(--r-xl);
  overflow: hidden;
  background: var(--bg-elevated);
  border: 1px solid var(--border);
  min-height: 280px;
  display: flex;
}

/* H1: Split */
.hero-split {
  display: grid;
  grid-template-columns: 1fr 1fr;
  align-items: center;
}
.hero-split .hero-copy { padding: 32px; }
.hero-split .hero-image { height: 100%; }

/* H2: Full bleed */
.hero-full {
  position: relative;
}
.hero-full .hero-image {
  position: absolute;
  inset: 0;
}
.hero-full .hero-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, rgba(42,31,64,0.1) 0%, rgba(42,31,64,0.65) 100%);
}
.hero-full .hero-copy {
  position: relative;
  z-index: 2;
  padding: 32px;
  color: white;
  align-self: end;
  width: 100%;
}
.hero-full .hero-copy .eyebrow,
.hero-full .hero-copy .hero-tagline { color: rgba(255,255,255,0.85); }

/* H3: Asymmetric — large photo, copy floats */
.hero-asym {
  display: grid;
  grid-template-columns: 1.4fr 1fr;
  gap: 0;
  position: relative;
}
.hero-asym .hero-image {
  height: 100%;
  border-right: 1px solid var(--border);
}
.hero-asym .hero-copy {
  padding: 32px 24px;
  align-self: center;
}
.hero-asym .hero-marker {
  position: absolute;
  bottom: 16px;
  left: 32px;
  font-family: ui-monospace, "SF Mono", Menlo, monospace;
  font-size: 10px;
  letter-spacing: var(--tracking-caps);
  color: var(--fg-muted);
  text-transform: uppercase;
}

/* H4: Magazine cover — oversized type with photo as backdrop */
.hero-mag {
  position: relative;
  background: var(--fg);
  color: white;
  display: flex;
  align-items: center;
  justify-content: center;
}
.hero-mag .hero-image {
  position: absolute;
  inset: 0;
  opacity: 0.55;
  filter: saturate(1.2);
}
.hero-mag .mag-title {
  position: relative;
  z-index: 2;
  font-size: clamp(44px, 8vw, 88px);
  font-weight: var(--fw-semi);
  letter-spacing: -0.03em;
  line-height: 0.9;
  text-align: center;
  padding: 32px;
  mix-blend-mode: screen;
  color: var(--bg);
}
.hero-mag .mag-meta {
  position: absolute;
  bottom: 16px;
  left: 24px;
  right: 24px;
  display: flex;
  justify-content: space-between;
  font-family: ui-monospace, "SF Mono", Menlo, monospace;
  font-size: 11px;
  letter-spacing: var(--tracking-caps);
  text-transform: uppercase;
  color: rgba(255,255,255,0.8);
  z-index: 3;
}

/* H5: Geometric collage — photo + secondary shapes */
.hero-collage {
  position: relative;
  background: var(--bg-elevated);
  display: grid;
  grid-template-columns: 1fr 1fr;
  align-items: center;
}
.hero-collage .hero-copy { padding: 32px; position: relative; z-index: 2; }
.hero-collage .collage-stack {
  position: relative;
  height: 100%;
  min-height: 280px;
}
.hero-collage .collage-image {
  position: absolute;
  top: 24px;
  right: 24px;
  bottom: 24px;
  left: 0;
  border-radius: var(--r-md);
  overflow: hidden;
  border: 1px solid var(--border);
}
.hero-collage .collage-shape-1 {
  position: absolute;
  width: 80px;
  height: 80px;
  border: 1px solid var(--accent);
  top: -8px;
  left: -8px;
  z-index: 3;
}
.hero-collage .collage-shape-2 {
  position: absolute;
  width: 40px;
  height: 40px;
  background: var(--primary);
  bottom: 8px;
  right: 8px;
  transform: rotate(45deg);
  z-index: 3;
}

.hero-eyebrow {
  font-family: ui-monospace, "SF Mono", Menlo, monospace;
  font-size: 11px;
  letter-spacing: var(--tracking-caps);
  text-transform: uppercase;
  color: var(--fg-muted);
  margin-bottom: 12px;
}
.hero-name {
  font-size: clamp(28px, 4vw, 44px);
  font-weight: var(--fw-semi);
  line-height: 1;
  letter-spacing: -0.02em;
  margin-bottom: 12px;
}
.hero-tagline {
  font-size: 15px;
  color: var(--fg-muted);
  margin-bottom: 20px;
  max-width: 32ch;
  line-height: var(--lh-loose);
}
.hero-ctas {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
}

/* Image placeholder */
.img-placeholder {
  background:
    repeating-linear-gradient(
      45deg,
      var(--bg-deep) 0 8px,
      var(--bg-elevated) 8px 16px
    );
  border: 1px solid var(--border);
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: ui-monospace, "SF Mono", Menlo, monospace;
  font-size: 11px;
  letter-spacing: var(--tracking-caps);
  text-transform: uppercase;
  color: var(--fg-muted);
  text-align: center;
  padding: 16px;
  min-height: 100%;
}
.img-placeholder.tall { min-height: 320px; }

/* ============================================================
   Trade card variations (4)
   ============================================================ */
.trade-stage {
  position: relative;
  perspective: 1000px;
  height: 360px;
  width: 100%;
}

/* TC1: Slide-down stack (per spec) */
.tc-slide {
  position: relative;
  width: 100%;
  max-width: 260px;
  margin: 0 auto;
}
.tc-slide-top {
  background: var(--bg-elevated);
  border: 1px solid var(--border);
  border-radius: var(--r-lg);
  height: 130px;
  position: relative;
  z-index: 2;
  overflow: hidden;
  transition: all var(--dur-card) var(--ease);
  cursor: pointer;
  display: flex;
}
.tc-slide-bottom {
  position: absolute;
  top: 130px;
  left: 0;
  right: 0;
  background: var(--bg-elevated);
  border: 1px solid var(--border);
  border-top: 0;
  border-radius: 0 0 var(--r-lg) var(--r-lg);
  height: 0;
  overflow: hidden;
  transition: height var(--dur-card) var(--ease);
  padding: 0 16px;
}
.tc-slide:hover .tc-slide-bottom { height: 170px; padding: 16px; }
.tc-slide:hover .tc-slide-top { border-radius: var(--r-lg) var(--r-lg) 0 0; }

/* TC2: Lift-and-reveal — top card lifts, detail fades in */
.tc-lift {
  position: relative;
  width: 100%;
  max-width: 260px;
  margin: 0 auto;
}
.tc-lift-top {
  background: var(--bg-elevated);
  border: 1px solid var(--border);
  border-radius: var(--r-lg);
  height: 200px;
  position: relative;
  z-index: 2;
  overflow: hidden;
  transition: transform var(--dur-card) var(--ease), box-shadow var(--dur-card) var(--ease);
  cursor: pointer;
  display: flex;
}
.tc-lift-bottom {
  position: absolute;
  top: 24px;
  left: 0;
  right: 0;
  background: var(--bg-elevated);
  border: 1px solid var(--border);
  border-radius: var(--r-lg);
  padding: 16px;
  opacity: 0;
  transform: translateY(8px);
  transition: opacity var(--dur-card) var(--ease), transform var(--dur-card) var(--ease);
  z-index: 1;
  height: 200px;
}
.tc-lift:hover .tc-lift-top {
  transform: translateY(-160px);
  box-shadow: var(--shadow-3);
}
.tc-lift:hover .tc-lift-bottom {
  opacity: 1;
  transform: translateY(40px);
}

/* TC3: Flip */
.tc-flip {
  width: 100%;
  max-width: 260px;
  height: 320px;
  margin: 0 auto;
  perspective: 1200px;
  cursor: pointer;
}
.tc-flip-inner {
  position: relative;
  width: 100%;
  height: 100%;
  transition: transform 700ms var(--ease);
  transform-style: preserve-3d;
}
.tc-flip:hover .tc-flip-inner { transform: rotateY(180deg); }
.tc-flip-face {
  position: absolute;
  inset: 0;
  backface-visibility: hidden;
  border-radius: var(--r-lg);
  border: 1px solid var(--border);
  background: var(--bg-elevated);
  overflow: hidden;
}
.tc-flip-back {
  transform: rotateY(180deg);
  padding: 20px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
}

/* TC4: Side peel — detail slides right */
.tc-peel {
  position: relative;
  width: 100%;
  max-width: 260px;
  height: 320px;
  margin: 0 auto;
  cursor: pointer;
}
.tc-peel-front {
  position: absolute;
  inset: 0;
  background: var(--bg-elevated);
  border: 1px solid var(--border);
  border-radius: var(--r-lg);
  z-index: 2;
  overflow: hidden;
  transition: transform var(--dur-card) var(--ease);
}
.tc-peel-back {
  position: absolute;
  top: 0;
  right: -100%;
  bottom: 0;
  width: 100%;
  background: var(--bg-elevated);
  border: 1px solid var(--border);
  border-radius: var(--r-lg);
  padding: 20px;
  transition: right var(--dur-card) var(--ease);
  z-index: 1;
}
.tc-peel:hover .tc-peel-front { transform: translateX(-30%); }
.tc-peel:hover .tc-peel-back { right: -70%; }

/* Trade card inner content (shared) */
.tc-photo {
  width: 130px;
  flex: 0 0 130px;
  background: var(--bg-deep);
  position: relative;
  overflow: hidden;
}
.tc-photo .img-placeholder {
  background:
    repeating-linear-gradient(45deg, var(--accent) 0 6px, var(--primary) 6px 12px);
  opacity: 0.5;
  height: 100%;
  border: 0;
}
.tc-info {
  padding: 12px 14px;
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.tc-tier {
  font-family: ui-monospace, "SF Mono", Menlo, monospace;
  font-size: 9px;
  letter-spacing: var(--tracking-caps);
  text-transform: uppercase;
  color: var(--accent);
  font-weight: var(--fw-semi);
}
.tc-tier.unicorn { color: var(--primary); }
.tc-tier.everyday { color: var(--fg-muted); }
.tc-name {
  font-size: 13px;
  font-weight: var(--fw-semi);
  line-height: 1.2;
}
.tc-type {
  font-family: ui-monospace, "SF Mono", Menlo, monospace;
  font-size: 12px;
  color: var(--fg-muted);
  margin-top: auto;
}
.tc-status {
  font-size: 10px;
  letter-spacing: var(--tracking-caps);
  text-transform: uppercase;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: var(--fg-muted);
}
.tc-status .pip {
  width: 6px; height: 6px; border-radius: 50%;
  background: #22c55e;
}
.tc-status.reserved .pip { background: #f59e0b; }
.tc-status.traded .pip { background: var(--fg-muted); }
.tc-detail-title {
  font-size: 11px;
  letter-spacing: var(--tracking-caps);
  text-transform: uppercase;
  color: var(--fg-muted);
  margin-bottom: 4px;
}
.tc-detail-text {
  font-size: 12px;
  color: var(--fg);
  line-height: var(--lh-loose);
  margin-bottom: 12px;
}

/* ============================================================
   LRQ — Live Reveal Queue
   ============================================================ */
.lrq {
  background: var(--bg-elevated);
  border: 1px solid var(--border);
  border-radius: var(--r-xl);
  padding: 20px;
  width: 100%;
  max-width: 320px;
}
.lrq-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 16px;
}
.lrq-title {
  font-size: 11px;
  letter-spacing: var(--tracking-caps);
  text-transform: uppercase;
  color: var(--fg-muted);
  font-weight: var(--fw-semi);
}
.lrq-status {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 10px;
  letter-spacing: var(--tracking-caps);
  text-transform: uppercase;
  color: #ef4444;
  font-weight: var(--fw-semi);
}
.lrq-status::before {
  content: "";
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: #ef4444;
  box-shadow: 0 0 0 0 rgba(239, 68, 68, 0.5);
  animation: livePulse 1.6s var(--ease) infinite;
}
@keyframes livePulse {
  to { box-shadow: 0 0 0 8px rgba(239, 68, 68, 0); }
}
.lrq-list {
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.lrq-item {
  display: grid;
  grid-template-columns: 32px 1fr auto;
  align-items: center;
  gap: 12px;
  padding: 10px 12px;
  border-radius: var(--r-md);
  background: var(--bg);
  border: 1px solid var(--border);
}
.lrq-item.current {
  background: var(--fg);
  color: var(--bg);
  border-color: var(--fg);
}
.lrq-item.next {
  background: var(--bg-deep);
}
.lrq-num {
  font-family: ui-monospace, "SF Mono", Menlo, monospace;
  font-size: 12px;
  font-weight: var(--fw-semi);
  text-align: center;
  padding: 4px 0;
  background: var(--bg-elevated);
  border-radius: 4px;
  color: var(--fg);
}
.lrq-item.current .lrq-num { background: var(--primary); color: white; }
.lrq-item.next .lrq-num { background: var(--accent); color: white; }
.lrq-name {
  font-size: 14px;
  font-weight: var(--fw-medium);
}
.lrq-label {
  font-size: 9px;
  letter-spacing: var(--tracking-caps);
  text-transform: uppercase;
  font-weight: var(--fw-semi);
  opacity: 0.85;
}
.lrq-empty {
  text-align: center;
  padding: 32px 16px;
  color: var(--fg-muted);
}
.lrq-empty .ribbon {
  font-size: 20px;
  font-weight: var(--fw-semi);
  color: var(--fg);
  margin-bottom: 8px;
}
.lrq-loading {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 32px;
}
.lrq-spinner {
  width: 24px;
  height: 24px;
  border: 2px solid var(--border);
  border-top-color: var(--primary);
  border-radius: 50%;
  animation: spin 800ms linear infinite;
}
@keyframes spin { to { transform: rotate(360deg); } }

/* ============================================================
   Benefit cards (Join Team) — 6 in 3x2
   ============================================================ */
.benefit-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
}
@media (max-width: 880px) {
  .benefit-grid { grid-template-columns: 1fr; }
}
.benefit-card {
  background: var(--bg-elevated);
  border: 1px solid var(--border);
  border-radius: var(--r-xl);
  padding: 24px;
  transition: transform var(--dur-base) var(--ease), border-color var(--dur-base) var(--ease);
}
.benefit-card:hover {
  transform: translateY(-2px);
  border-color: var(--primary);
}
.benefit-icon {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--primary), var(--accent));
  margin-bottom: 16px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: white;
  font-weight: var(--fw-semi);
}
.benefit-title {
  font-size: 16px;
  font-weight: var(--fw-semi);
  margin-bottom: 6px;
}
.benefit-desc {
  font-size: 13px;
  color: var(--fg-muted);
  line-height: var(--lh-loose);
}

/* ============================================================
   FAQ accordion
   ============================================================ */
.faq-list { max-width: 720px; }
.faq-item {
  border-bottom: 1px solid var(--border);
  padding: 18px 0;
  cursor: pointer;
}
.faq-q {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 16px;
  font-weight: var(--fw-medium);
  list-style: none;
}
.faq-q::-webkit-details-marker { display: none; }
.faq-q::after {
  content: "+";
  font-size: 20px;
  color: var(--primary);
  transition: transform var(--dur-base) var(--ease);
  font-weight: var(--fw-regular);
}
.faq-item[open] .faq-q::after { content: "−"; }
.faq-a {
  color: var(--fg-muted);
  font-size: 14px;
  line-height: var(--lh-loose);
  padding-top: 12px;
  max-width: 640px;
}

/* ============================================================
   Team member card
   ============================================================ */
.team-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 16px;
}
.team-card {
  background: var(--bg-elevated);
  border: 1px solid var(--border);
  border-radius: var(--r-lg);
  overflow: hidden;
  text-align: center;
}
.team-photo {
  aspect-ratio: 1;
  background: var(--bg-deep);
}
.team-meta { padding: 14px; }
.team-name { font-size: 14px; font-weight: var(--fw-semi); }
.team-role {
  font-size: 11px;
  letter-spacing: var(--tracking-caps);
  text-transform: uppercase;
  color: var(--fg-muted);
  margin-top: 4px;
}

/* ============================================================
   Footer
   ============================================================ */
.site-footer {
  background: var(--header-bg);
  color: rgba(255,255,255,0.75);
  font-size: 14px;
}
.footer-cols {
  max-width: var(--container-max);
  margin: 0 auto;
  padding: 56px 24px 24px;
  display: grid;
  grid-template-columns: 1.4fr 1fr 1fr 1fr;
  gap: 40px;
}
@media (max-width: 720px) {
  .footer-cols { grid-template-columns: 1fr 1fr; }
}
.footer-col h4 {
  color: white;
  font-size: 12px;
  letter-spacing: var(--tracking-caps);
  text-transform: uppercase;
  margin-bottom: 16px;
  font-weight: var(--fw-semi);
}
.footer-col ul {
  list-style: none;
  padding: 0;
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: 10px;
  font-size: 13px;
}
.footer-col a { color: rgba(255,255,255,0.65); }
.footer-col a:hover { color: white; }
.footer-tagline { color: rgba(255,255,255,0.55); margin-top: 8px; font-size: 13px; line-height: var(--lh-loose); }
.footer-team-pill {
  display: inline-block;
  margin-top: 12px;
  padding: 4px 10px;
  border: 1px solid rgba(255,255,255,0.2);
  border-radius: var(--r-pill);
  font-size: 11px;
  letter-spacing: var(--tracking-caps);
  text-transform: uppercase;
  color: rgba(255,255,255,0.8);
}
.footer-bottom {
  border-top: 1px solid rgba(255,255,255,0.1);
  max-width: var(--container-max);
  margin: 0 auto;
  padding: 20px 24px 32px;
  font-size: 11px;
  color: rgba(255,255,255,0.45);
  line-height: var(--lh-loose);
  text-align: center;
}
.footer-bottom .seg { margin: 0 8px; opacity: 0.4; }

/* ============================================================
   Nic-Nac launcher variations
   ============================================================ */
.nic-nac-stage {
  position: relative;
  height: 200px;
  background: var(--bg);
  border: 1px dashed var(--border);
  border-radius: var(--r-lg);
}
.nic-nac-stage > * {
  position: absolute;
  bottom: 16px;
  right: 16px;
}

/* TH1: Pill with avatar + label */
.th-pill {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  background: var(--fg);
  color: var(--bg);
  padding: 10px 18px 10px 10px;
  border-radius: var(--r-pill);
  font-size: 13px;
  font-weight: var(--fw-medium);
  box-shadow: var(--shadow-2);
  cursor: pointer;
  transition: all var(--dur-base) var(--ease);
}
.th-pill:hover { background: var(--accent); transform: translateY(-2px); }
.th-pill .th-avatar {
  width: 28px; height: 28px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--primary), var(--accent));
  display: flex; align-items: center; justify-content: center;
  color: white; font-size: 12px; font-weight: var(--fw-semi);
}

/* TH2: Round icon-only with pulse */
.th-round {
  width: 56px; height: 56px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--primary), var(--accent));
  color: white;
  display: flex; align-items: center; justify-content: center;
  cursor: pointer;
  box-shadow: var(--shadow-2);
  transition: transform var(--dur-base) var(--ease);
  position: relative;
}
.th-round::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: 50%;
  border: 2px solid var(--primary);
  animation: thPulse 2s var(--ease) infinite;
  pointer-events: none;
}
@keyframes thPulse {
  0% { transform: scale(1); opacity: 0.8; }
  100% { transform: scale(1.4); opacity: 0; }
}
.th-round:hover { transform: scale(1.06); }
.th-round svg { width: 22px; height: 22px; }

/* TH3: Square geometric with sparkle */
.th-square {
  width: 56px; height: 56px;
  background: var(--fg);
  color: var(--bg);
  border-radius: var(--r-md);
  display: flex; align-items: center; justify-content: center;
  cursor: pointer;
  box-shadow: var(--shadow-2);
  position: relative;
  transition: all var(--dur-base) var(--ease);
}
.th-square:hover { background: var(--accent); transform: rotate(-4deg); }
.th-square::before {
  content: "✦";
  position: absolute;
  top: -6px;
  right: -6px;
  width: 18px; height: 18px;
  background: var(--primary);
  color: white;
  border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  font-size: 10px;
  animation: thSparkle 2s var(--ease) infinite;
}
@keyframes thSparkle {
  0%, 100% { transform: scale(1) rotate(0); }
  50%      { transform: scale(1.2) rotate(180deg); }
}

/* TH4: Bottom dock bar */
.th-dock {
  left: 16px;
  right: 16px;
  bottom: 16px;
  background: var(--fg);
  color: var(--bg);
  border-radius: var(--r-pill);
  padding: 12px 18px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  cursor: pointer;
  box-shadow: var(--shadow-2);
  transition: all var(--dur-base) var(--ease);
}
.th-dock:hover { background: var(--accent); }
.th-dock .th-dock-left {
  display: flex; align-items: center; gap: 10px;
  font-size: 13px; font-weight: var(--fw-medium);
}
.th-dock .th-avatar {
  width: 26px; height: 26px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--primary), var(--accent));
}
.th-dock .th-arrow { font-size: 16px; opacity: 0.7; }

/* TH5: Floating gem */
.th-gem {
  width: 56px; height: 56px;
  background: linear-gradient(135deg, var(--primary), var(--accent));
  transform: rotate(45deg);
  border-radius: 8px;
  cursor: pointer;
  box-shadow: var(--shadow-2);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all var(--dur-base) var(--ease);
  animation: thGemFloat 3s var(--ease) infinite;
}
@keyframes thGemFloat {
  0%, 100% { transform: rotate(45deg) translateY(0); }
  50%      { transform: rotate(45deg) translateY(-4px); }
}
.th-gem:hover { transform: rotate(45deg) scale(1.08); animation-play-state: paused; }
.th-gem .th-gem-inner {
  transform: rotate(-45deg);
  color: white;
  font-size: 14px;
  font-weight: var(--fw-semi);
}

/* ============================================================
   Media tile (rounded image OR embed) — locked I2 treatment
   Supports: still photo, TikTok/social embed, video URL embed.
   ============================================================ */
.media-tile {
  position: relative;
  aspect-ratio: 1;
  background: var(--bg-deep);
  border-radius: var(--r-lg);
  overflow: hidden;
  border: 1px solid var(--border);
}
.media-tile.portrait { aspect-ratio: 3 / 4; }
.media-tile.video-vertical { aspect-ratio: 9 / 16; }
.media-tile .img-placeholder { height: 100%; }

/* Embed badge */
.media-badge {
  position: absolute;
  top: 10px;
  left: 10px;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background: rgba(42, 31, 64, 0.85);
  color: white;
  padding: 4px 10px;
  border-radius: var(--r-pill);
  font-size: 10px;
  letter-spacing: var(--tracking-caps);
  text-transform: uppercase;
  font-weight: var(--fw-semi);
  backdrop-filter: blur(4px);
  z-index: 2;
}
.media-badge .pip {
  width: 6px; height: 6px; border-radius: 50%;
  background: var(--primary);
}
.media-badge.tiktok .pip { background: #25F4EE; }
.media-badge.video .pip { background: #ef4444; }

/* Video play overlay */
.media-play {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(42, 31, 64, 0.25);
  z-index: 1;
  transition: background var(--dur-base) var(--ease);
}
.media-tile:hover .media-play { background: rgba(42, 31, 64, 0.5); }
.media-play-btn {
  width: 48px; height: 48px;
  background: rgba(255, 255, 255, 0.95);
  color: var(--fg);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 18px;
  padding-left: 3px;
}

/* ============================================================
   Event calendar cards (Upcoming Shows)
   ============================================================ */
.event-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
}
@media (max-width: 720px) { .event-grid { grid-template-columns: 1fr; } }

.event-card {
  background: var(--bg-elevated);
  border: 1px solid var(--border);
  border-radius: var(--r-xl);
  padding: 24px;
  display: flex;
  flex-direction: column;
  gap: 16px;
  transition: transform var(--dur-base) var(--ease), border-color var(--dur-base) var(--ease);
}
.event-card:hover { transform: translateY(-2px); border-color: var(--primary); }

.event-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
}
.event-when {
  font-family: ui-monospace, "SF Mono", Menlo, monospace;
  font-size: 11px;
  letter-spacing: var(--tracking-caps);
  text-transform: uppercase;
  color: var(--fg-muted);
}
.event-when strong { color: var(--fg); display: block; font-size: 13px; margin-top: 2px; }
.event-tz {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font-size: 10px;
  color: var(--fg-muted);
  margin-top: 6px;
  font-family: ui-monospace, "SF Mono", Menlo, monospace;
  letter-spacing: 0.04em;
}
.event-name {
  font-size: 22px;
  font-weight: var(--fw-semi);
  line-height: 1.15;
  letter-spacing: -0.01em;
}
.event-msg {
  font-size: 13px;
  color: var(--fg-muted);
  line-height: var(--lh-loose);
}

.event-codes {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}
.event-code {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: var(--bg);
  border: 1px dashed var(--accent);
  border-radius: var(--r-pill);
  padding: 6px 14px;
  font-family: ui-monospace, "SF Mono", Menlo, monospace;
  font-size: 11px;
  letter-spacing: 0.06em;
  color: var(--accent);
  cursor: pointer;
  font-weight: var(--fw-semi);
  transition: all var(--dur-fast) var(--ease);
}
.event-code:hover { background: var(--accent); color: white; border-style: solid; }
.event-code .copy {
  font-size: 9px;
  opacity: 0.6;
  letter-spacing: 0.04em;
}

.event-collections {
  display: flex;
  flex-direction: column;
  gap: 4px;
  font-size: 13px;
}
.event-collection-label {
  font-size: 10px;
  letter-spacing: var(--tracking-caps);
  text-transform: uppercase;
  color: var(--fg-muted);
  font-weight: var(--fw-semi);
  margin-bottom: 4px;
}
.event-collection {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 6px 0;
  border-bottom: 1px solid var(--border);
  color: var(--fg);
}
.event-collection:last-child { border-bottom: 0; }
.event-collection:hover { color: var(--primary); }
.event-collection .arrow { opacity: 0.5; transition: transform var(--dur-fast) var(--ease); }
.event-collection:hover .arrow { transform: translateX(3px); opacity: 1; }

.event-actions {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  margin-top: auto;
}
.event-platform-btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: var(--fg);
  color: var(--bg);
  padding: 10px 14px;
  border-radius: var(--r-md);
  font-size: 12px;
  font-weight: var(--fw-medium);
  letter-spacing: 0.02em;
  border: 0;
  cursor: pointer;
  transition: background var(--dur-fast) var(--ease);
}
.event-platform-btn:hover { background: var(--accent); }
.event-platform-btn .glyph {
  width: 14px; height: 14px;
  border-radius: 3px;
  background: var(--primary);
  display: inline-block;
}
.event-platform-btn.tiktok .glyph { background: #25F4EE; }
.event-platform-btn.facebook .glyph { background: #1877F2; }
.event-platform-btn.instagram .glyph { background: linear-gradient(135deg, #F58529, #DD2A7B, #8134AF); }
.event-platform-btn.youtube .glyph { background: #FF0000; }

.event-add-cal {
  background: transparent;
  color: var(--fg);
  border: 1px solid var(--border);
  padding: 10px 14px;
  border-radius: var(--r-md);
  font-size: 12px;
  font-weight: var(--fw-medium);
  cursor: pointer;
  transition: all var(--dur-fast) var(--ease);
}
.event-add-cal:hover { border-color: var(--fg); background: var(--bg); }

/* ============================================================
   "What is Bomb Party?" two-card layout
   ============================================================ */
.wibp-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
}
@media (max-width: 720px) { .wibp-grid { grid-template-columns: 1fr; } }

.wibp-card {
  background: var(--bg-elevated);
  border: 1px solid var(--border);
  border-radius: var(--r-xl);
  padding: 32px;
}
.wibp-card.embed-card { padding: 0; overflow: hidden; }

.wibp-eyebrow {
  font-size: 11px;
  letter-spacing: var(--tracking-caps);
  text-transform: uppercase;
  color: var(--fg-muted);
  font-weight: var(--fw-semi);
  margin-bottom: 12px;
}
.wibp-title {
  font-size: 26px;
  font-weight: var(--fw-semi);
  letter-spacing: -0.01em;
  margin-bottom: 12px;
  line-height: 1.15;
}
.wibp-body {
  font-size: 14px;
  color: var(--fg-muted);
  line-height: var(--lh-loose);
  margin-bottom: 24px;
}

.steps-row {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
}
.step {
  text-align: center;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
}
.step-icon {
  width: 44px; height: 44px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--primary), var(--accent));
  display: flex;
  align-items: center;
  justify-content: center;
  color: white;
  font-weight: var(--fw-semi);
  font-size: 16px;
}
.step-label {
  font-size: 12px;
  font-weight: var(--fw-semi);
  letter-spacing: 0.02em;
}
.step-desc {
  font-size: 11px;
  color: var(--fg-muted);
  line-height: 1.4;
}

.tiktok-embed {
  width: 100%;
  background: #000;
  position: relative;
  aspect-ratio: 9 / 16;
  max-height: 540px;
  margin: 0 auto;
}
.tiktok-embed .img-placeholder {
  background:
    repeating-linear-gradient(45deg, #1a1a1a 0 8px, #2a2a2a 8px 16px);
  height: 100%;
  color: rgba(255,255,255,0.5);
  border: 0;
}

/* ============================================================
   Email/SMS signup
   ============================================================ */
.signup-card {
  background: var(--bg-elevated);
  border: 1px solid var(--border);
  border-radius: var(--r-xl);
  padding: 48px;
  max-width: 560px;
  margin: 0 auto;
  text-align: center;
}
.signup-eyebrow {
  font-size: 11px;
  letter-spacing: var(--tracking-caps);
  text-transform: uppercase;
  color: var(--fg-muted);
  font-weight: var(--fw-semi);
  margin-bottom: 12px;
}
.signup-title {
  font-size: 32px;
  font-weight: var(--fw-semi);
  letter-spacing: -0.02em;
  margin-bottom: 12px;
  line-height: 1.05;
}
.signup-sub {
  font-size: 14px;
  color: var(--fg-muted);
  margin-bottom: 28px;
  line-height: var(--lh-loose);
}
.signup-form {
  display: flex;
  flex-direction: column;
  gap: 12px;
  text-align: left;
}
.signup-field label {
  display: block;
  font-size: 11px;
  letter-spacing: var(--tracking-caps);
  text-transform: uppercase;
  color: var(--fg-muted);
  font-weight: var(--fw-semi);
  margin-bottom: 6px;
}
.signup-field label .opt { color: var(--fg-muted); opacity: 0.6; font-weight: var(--fw-regular); }
.signup-input {
  width: 100%;
  padding: 14px 16px;
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: var(--r-md);
  font-family: inherit;
  font-size: 14px;
  color: var(--fg);
  transition: border-color var(--dur-fast) var(--ease);
}
.signup-input:focus { outline: 0; border-color: var(--primary); }
.signup-consent {
  font-size: 11px;
  color: var(--fg-muted);
  line-height: 1.5;
  margin-top: 4px;
  text-align: left;
}
.signup-submit-row {
  margin-top: 12px;
  display: flex;
  justify-content: center;
}

/* ============================================================
   TEAM CARDS (revised) — photo + show name + state + socials + recruit
   ============================================================ */
.team-grid-v2 {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 16px;
}
.team-card-v2 {
  background: var(--bg-elevated);
  border: 1px solid var(--border);
  border-radius: var(--r-lg);
  overflow: hidden;
  transition: border-color var(--dur-base) var(--ease), transform var(--dur-base) var(--ease);
  display: flex;
  flex-direction: column;
}
.team-card-v2:hover { border-color: var(--primary); transform: translateY(-2px); }

.team-photo-v2 {
  position: relative;
  aspect-ratio: 4 / 5;
  background: var(--bg-deep);
  overflow: hidden;
}
.team-photo-v2 .img-placeholder {
  background: repeating-linear-gradient(45deg, var(--bg-deep) 0 6px, var(--bg-elevated) 6px 12px);
  height: 100%;
  border: 0;
}
.team-socials-overlay {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  padding: 10px 12px;
  background: linear-gradient(180deg, transparent, rgba(42,31,64,0.85));
  display: flex;
  gap: 10px;
  justify-content: center;
}
.team-social {
  width: 28px; height: 28px;
  border-radius: 50%;
  background: rgba(255,255,255,0.15);
  border: 1px solid rgba(255,255,255,0.25);
  display: flex;
  align-items: center;
  justify-content: center;
  color: white;
  font-size: 11px;
  font-weight: var(--fw-semi);
  cursor: pointer;
  transition: all var(--dur-fast) var(--ease);
  text-decoration: none;
}
.team-social:hover { background: var(--primary); border-color: var(--primary); transform: translateY(-2px); }
.team-social.suite { background: linear-gradient(135deg, var(--primary), var(--accent)); border-color: transparent; }

.team-meta-v2 {
  padding: 14px;
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.team-name-v2 {
  font-size: 15px;
  font-weight: var(--fw-semi);
  letter-spacing: -0.01em;
}
.team-show {
  font-size: 12px;
  color: var(--accent);
  font-weight: var(--fw-medium);
  font-style: italic;
}
.team-state {
  font-size: 11px;
  letter-spacing: var(--tracking-caps);
  text-transform: uppercase;
  color: var(--fg-muted);
  font-weight: var(--fw-semi);
  display: inline-flex;
  align-items: center;
  gap: 5px;
  margin-top: 2px;
}
.team-state::before {
  content: "";
  width: 4px; height: 4px;
  background: var(--fg-muted);
  border-radius: 50%;
}

/* Recruit card — last slot in team grid */
.team-recruit {
  background: var(--bg);
  border: 1.5px dashed var(--accent);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  padding: 24px;
  cursor: pointer;
  transition: all var(--dur-base) var(--ease);
  min-height: 320px;
}
.team-recruit:hover {
  background: var(--bg-elevated);
  border-color: var(--primary);
  transform: translateY(-2px);
}
.team-recruit-glyph {
  width: 56px; height: 56px;
  border: 1.5px dashed var(--accent);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 28px;
  color: var(--accent);
  margin-bottom: 16px;
  font-weight: var(--fw-regular);
  transition: all var(--dur-base) var(--ease);
}
.team-recruit:hover .team-recruit-glyph {
  background: var(--primary);
  border-color: var(--primary);
  color: white;
}
.team-recruit-title {
  font-size: 16px;
  font-weight: var(--fw-semi);
  margin-bottom: 6px;
  color: var(--fg);
}
.team-recruit-desc {
  font-size: 12px;
  color: var(--fg-muted);
  line-height: var(--lh-loose);
  max-width: 22ch;
}

/* ============================================================
   DUAL TICKER — locked T3 with split rep / trade rows
   ============================================================ */
.ticker-trade-link {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  padding: 4px 12px;
  border-radius: var(--r-pill);
  background: rgba(255,255,255,0.06);
  color: inherit;
  text-decoration: none;
  transition: all var(--dur-fast) var(--ease);
  cursor: pointer;
  border: 1px solid transparent;
}
.ticker-trade-link:hover {
  background: var(--primary);
  color: white;
  border-color: var(--primary);
}
.ticker-trade-link .tier-pip {
  width: 6px; height: 6px; border-radius: 50%;
  background: var(--primary);
}
.ticker-trade-link .tier-pip.unicorn { background: #ffb703; }
.ticker-trade-link .tier-pip.diamond { background: #25F4EE; }
.ticker-row.rep-row {
  background: var(--fg);
}
.ticker-row.trade-row {
  background: var(--header-bg);
  border-top: 1px solid rgba(255,255,255,0.06);
}
.ticker-row .row-label {
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  background: var(--header-bg);
  color: rgba(255,255,255,0.5);
  font-size: 10px;
  letter-spacing: var(--tracking-caps);
  text-transform: uppercase;
  font-weight: var(--fw-semi);
  padding: 0 14px;
  display: flex;
  align-items: center;
  z-index: 2;
  border-right: 1px solid rgba(255,255,255,0.08);
}
.ticker-row.rep-row .row-label { background: var(--fg); }

/* Hero CTA stack additions */
.hero-cta-stream-group {
  display: inline-flex;
  position: relative;
}
.hero-cta-stream-group .stream-options {
  position: absolute;
  top: calc(100% + 8px);
  left: 0;
  background: var(--bg-elevated);
  border: 1px solid var(--border);
  border-radius: var(--r-md);
  padding: 6px;
  display: none;
  flex-direction: column;
  gap: 2px;
  min-width: 160px;
  z-index: 10;
  box-shadow: var(--shadow-2);
}
.hero-cta-stream-group:hover .stream-options { display: flex; }
.hero-cta-stream-group .stream-option {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 12px;
  border-radius: var(--r-sm);
  font-size: 13px;
  color: var(--fg);
  cursor: pointer;
  background: transparent;
  border: 0;
}
.hero-cta-stream-group .stream-option:hover { background: var(--bg-deep); }
.hero-cta-stream-group .stream-option .glyph {
  width: 14px; height: 14px; border-radius: 3px;
}

/* Off-at-launch badge for Nic-Nac section */
.dormant-badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: rgba(92, 87, 106, 0.15);
  border: 1px solid var(--border);
  border-radius: var(--r-pill);
  padding: 6px 14px;
  font-size: 11px;
  letter-spacing: var(--tracking-caps);
  text-transform: uppercase;
  color: var(--fg-muted);
  font-weight: var(--fw-semi);
  margin-bottom: 16px;
}
.dormant-badge::before {
  content: "";
  width: 6px; height: 6px;
  border-radius: 50%;
  background: var(--fg-muted);
}

/* ============================================================
   Imagery treatment variations
   ============================================================ */
.img-row {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
}
.img-cell {
  aspect-ratio: 1;
  background: var(--bg-deep);
  position: relative;
  overflow: hidden;
}
.img-cell .img-placeholder {
  background:
    repeating-linear-gradient(45deg, var(--bg-deep) 0 6px, var(--bg-elevated) 6px 12px);
  height: 100%;
}
/* Treatments */
.img-square { border: 1px solid var(--border); border-radius: 0; }
.img-rounded { border-radius: var(--r-lg); }
.img-circle { border-radius: 50%; }
.img-arch { border-radius: 999px 999px 8px 8px; }
.img-hex {
  clip-path: polygon(50% 0, 100% 25%, 100% 75%, 50% 100%, 0 75%, 0 25%);
}
.img-polaroid {
  background: white;
  padding: 8px 8px 24px;
  border: 1px solid var(--border);
  box-shadow: var(--shadow-1);
  aspect-ratio: 0.85;
}
.img-polaroid .img-cell-inner {
  aspect-ratio: 1;
  background:
    repeating-linear-gradient(45deg, var(--bg-deep) 0 6px, var(--bg-elevated) 6px 12px);
}
.img-polaroid .caption {
  text-align: center;
  font-size: 10px;
  letter-spacing: var(--tracking-caps);
  text-transform: uppercase;
  color: var(--fg-muted);
  padding-top: 6px;
}

/* ============================================================
   Spec lines (small explanatory captions in stages)
   ============================================================ */
.spec {
  font-family: ui-monospace, "SF Mono", Menlo, monospace;
  font-size: 11px;
  letter-spacing: var(--tracking-caps);
  text-transform: uppercase;
  color: var(--fg-muted);
}

/* ============================================================
   Customization slot legend
   ============================================================ */
.legend-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 24px;
}
@media (max-width: 720px) { .legend-grid { grid-template-columns: 1fr; } }
.legend-col {
  background: var(--bg-elevated);
  border: 1px solid var(--border);
  border-radius: var(--r-xl);
  padding: 24px;
}
.legend-col h3 { margin-bottom: 16px; font-size: 16px; }
.legend-col ul {
  list-style: none;
  padding: 0;
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: 8px;
  font-size: 13px;
  color: var(--fg-muted);
}
.legend-col li { padding-left: 16px; position: relative; }
.legend-col li::before {
  content: "";
  position: absolute;
  left: 0;
  top: 8px;
  width: 6px;
  height: 6px;
  border-radius: 1px;
}
.legend-col.swappable li::before { background: var(--primary); }
.legend-col.locked li::before { background: var(--fg-muted); }

homepage.css:
/* ============================================================
   HOMEPAGE — Sasha's Sparkle Suite (live site)
   Layered on top of tokens.css + components.css
   ============================================================ */

/* ---------- Theme variables driven by Tweaks ---------- */
:root {
  --hp-primary: var(--primary);
  --hp-accent: var(--accent);
  --hp-bg: var(--bg);
  --hp-bg-elevated: var(--bg-elevated);
  --hp-section-pad: 96px;
  --hp-radius-card: var(--r-xl);
  --hp-display-font: var(--font-sans);
  --hp-body-font: var(--font-sans);
  --hp-heading-weight: 600;
  --hp-heading-tracking: -0.01em;
  --hp-saturation: 1;
  --hp-density: 1;
  --hp-mobile-sticky-ticker-top: 0px;
  --hp-mobile-sticky-trade-top: 76px;
