}

body.bling-kitchen .hp-about-media-card:nth-child(2) {
  background-image:
    linear-gradient(180deg, rgba(35, 20, 45, 0.08) 0%, rgba(35, 20, 45, 0.72) 100%),
    url("https://static.readdy.ai/image/6521ef01a44cd5c540b1d9b66db907e8/3c1b6a9fe12ad8046cfafac1de340145.jpeg");
}

body.bling-kitchen .hp-about-media-play {
  display: none;
}

body.bling-kitchen .hp-about-media-type {
  background: rgba(255, 248, 238, 0.9);
  color: var(--bk-ink);
}

body.bling-kitchen .hp-about-media-caption {
  color: #fff8ee;
  text-shadow: 0 2px 12px rgba(0, 0, 0, 0.42);
}

body.bling-kitchen .hp-signup-card {
  max-width: 980px;
}

body.bling-kitchen .hp-signup-submit {
  background: linear-gradient(135deg, #5f7461, #5f2a83);
}

body.bling-kitchen .hp-footer {
  background: #2b1a33 !important;
  color: rgba(255, 248, 238, 0.78);
  border: 0;
  box-shadow: none !important;
}

body.bling-kitchen .hp-footer-brand,
body.bling-kitchen .hp-footer a {
  color: #fff8ee;
}

body.bling-kitchen .hp-footer-tag,
body.bling-kitchen .hp-footer-bottom,
body.bling-kitchen .hp-footer-bottom p {
  color: rgba(255, 248, 238, 0.78);
}

@media (max-width: 720px) {
  .bk-home-announcement {
    display: block;
  }

  .bk-home-header-inner {
    grid-template-columns: 1fr auto;
  }

  .bk-home-logo {
    justify-self: end;
  }

  .bk-home-shop {
    display: none;
  }

  .bk-home-hero {
    min-height: 620px;
  }

  .bk-home-hero::after {
    background: linear-gradient(180deg, rgba(21, 12, 31, 0.22), rgba(21, 12, 31, 0.86));
  }

  .bk-home-pantry-callout {
    display: block;
  }

  .bk-home-pantry-callout a {
    margin-top: 18px;
  }

  body.bling-kitchen .bk-home-guide {
    grid-template-columns: 1fr;
  }

  body.bling-kitchen .bk-home-guide-step {
    min-height: 0;
  }
}

body.homepage {
  background: var(--hp-bg);
  font-family: var(--hp-body-font);
}

body.homepage #root,
body.tradepage #root,
body.joinpage #root {
  overflow: visible;
}

/* Saturation applied to content wrapper, NOT body — body filter breaks position:fixed */
.hp-saturate {
  filter: saturate(var(--hp-saturation));
}

body.homepage h1, body.homepage h2, body.homepage h3, body.homepage h4 {
  font-family: var(--hp-display-font);
  font-weight: var(--hp-heading-weight);
  letter-spacing: var(--hp-heading-tracking);
}

.hp-sticky-stack {
  position: sticky;
  top: 0;
  z-index: 90;
  box-shadow: 0 18px 38px rgba(42, 31, 64, 0.08);
}

/* ============================================================
   Header (live-show hub)
   ============================================================ */
.hp-header {
  position: relative;
  z-index: 3;
  background:
    radial-gradient(circle at 12% 0%, color-mix(in oklch, var(--hp-primary) 16%, transparent), transparent 22rem),
    rgba(255, 255, 255, 0.88);
  border-bottom: 1px solid color-mix(in oklch, var(--hp-primary) 18%, var(--border));
  color: var(--fg);
  backdrop-filter: blur(18px);
}
.hp-header-inner {
  max-width: 1280px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: minmax(190px, 1fr) auto minmax(160px, 1fr);
  gap: 18px;
  align-items: center;
  padding: 12px 24px;
}
.hp-header-nav {
  display: inline-flex;
  align-items: center;
  gap: clamp(18px, 2.4vw, 32px);
  flex-wrap: nowrap;
  justify-self: center;
  max-width: 100%;
  padding: 0;
}
.hp-header-link {
  position: relative;
  display: inline-flex;
  align-items: center;
  min-height: 34px;
  padding: 4px 0;
  color: color-mix(in oklch, var(--fg) 70%, var(--fg-muted));
  background: transparent;
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.11em;
  text-decoration: none;
  text-transform: uppercase;
  white-space: nowrap;
  transition: color var(--dur-fast) var(--ease), transform var(--dur-fast) var(--ease);
}
.hp-header-link::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  height: 2px;
  border-radius: 999px;
  background: linear-gradient(90deg, var(--hp-primary), var(--hp-accent));
  opacity: 0;
  transform: scaleX(0.58);
  transform-origin: center;
  transition: opacity var(--dur-fast) var(--ease), transform var(--dur-fast) var(--ease);
}
.hp-header-link:hover {
  color: color-mix(in oklch, var(--hp-primary) 84%, var(--fg));
  transform: translateY(-1px);
}
.hp-header-link:hover::after {
  opacity: 0.55;
  transform: scaleX(1);
}
.hp-header-link[aria-current="page"] {
  color: color-mix(in oklch, var(--hp-primary) 82%, var(--fg));
}
.hp-header-link[aria-current="page"]::after {
  opacity: 1;
  transform: scaleX(1);
}
.hp-header-link-disabled {
  gap: 6px;
  color: color-mix(in oklch, var(--fg-muted) 76%, transparent);
  cursor: not-allowed;
  opacity: 0.76;
}
.hp-header-link-disabled:hover {
  color: color-mix(in oklch, var(--fg-muted) 76%, transparent);
  transform: none;
}
.hp-header-link-disabled::after,
.hp-header-link-disabled:hover::after {
  opacity: 0;
  transform: scaleX(0.58);
}
.hp-coming-soon-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: auto;
  padding: 0;
  color: color-mix(in oklch, var(--hp-primary) 68%, var(--fg-muted));
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.1em;
}
.hp-burger {
  width: 40px;
  height: 40px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 8px;
  color: white;
  background: rgba(255,255,255,0.04);
  border: 1px solid rgba(255,255,255,0.06);
  transition: background var(--dur-fast) var(--ease);
}
.hp-burger:hover { background: rgba(255,255,255,0.08); }
.hp-burger svg { width: 18px; height: 18px; }
.hp-brand {
  min-width: 0;
  text-align: left;
  display: flex;
  flex-direction: column;
  gap: 4px;
  align-items: flex-start;
  justify-self: start;
}
.hp-brand-name {
  font-family: var(--hp-display-font);
  font-size: clamp(18px, 2vw, 22px);
  font-weight: 600;
  letter-spacing: -0.01em;
  color: var(--fg);
  white-space: nowrap;
  max-width: min(34vw, 360px);
  overflow: hidden;
  text-overflow: ellipsis;
}
.hp-brand-sub {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: color-mix(in oklch, var(--hp-primary) 72%, var(--fg));
}
.hp-live-dot {
  width: 8px;
  height: 8px;
  border-radius: 999px;
  background: #ff3366;
  box-shadow: 0 0 0 5px rgba(255, 51, 102, 0.12);
  animation: amethyst-pulse 1.8s ease-in-out infinite;
}
.hp-shop-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  min-height: 44px;
  padding: 10px 18px;
  background: var(--hp-card-accent);
  color: var(--hp-action-fg);
  border-radius: 999px;
  font-size: 13px;
  font-weight: 800;
  letter-spacing: 0.04em;
  border: 1px solid color-mix(in oklch, var(--hp-accent) 46%, white);
  cursor: pointer;
  text-decoration: none;
  text-transform: uppercase;
  box-shadow:
    inset 0 1px rgba(255, 255, 255, 0.28),
    0 14px 30px color-mix(in oklch, var(--hp-accent) 22%, transparent);
  transition: transform var(--dur-fast) var(--ease), box-shadow var(--dur-fast) var(--ease);
  justify-self: end;
}
.hp-shop-btn:hover {
  transform: translateY(-2px);
  box-shadow:
    inset 0 1px rgba(255, 255, 255, 0.34),
    0 18px 38px color-mix(in oklch, var(--hp-accent) 26%, transparent);
}

@media (max-width: 720px) {
  .hp-header-inner {
    grid-template-columns: minmax(0, 1fr) auto;
    justify-items: stretch;
    gap: 8px 14px;
    padding: 10px 16px 8px;
  }

  .hp-header-nav {
    grid-column: 1 / -1;
    grid-row: 2;
    justify-content: flex-start;
    justify-self: stretch;
    width: 100%;
    overflow-x: auto;
    scrollbar-width: none;
  }

  .hp-header-nav::-webkit-scrollbar {
    display: none;
  }

  .hp-brand {
    grid-column: 1;
    grid-row: 1;
    justify-self: start;
  }

  .hp-brand-name {
    max-width: min(58vw, 320px);
  }

  .hp-header-link {
    min-height: 30px;
  }

  .hp-shop-btn {
    grid-column: 2;
    grid-row: 1;
    justify-self: end;
    min-height: 40px;
    padding: 8px 16px;
  }
}

/* Announcement banner */
.hp-announce {
  background: linear-gradient(90deg, var(--hp-primary), var(--hp-accent));
  color: white;
  padding: 10px 24px;
  text-align: center;
  font-size: 13px;
  font-weight: 500;
  letter-spacing: 0.02em;
  position: relative;
  overflow: hidden;
}
.hp-announce::before, .hp-announce::after {
  content: "✦";
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  opacity: 0.5;
  font-size: 11px;
}
.hp-announce::before { left: 24px; }
.hp-announce::after { right: 24px; }

/* ============================================================
   Ticker (T3 dual)
   ============================================================ */
.hp-ticker {
  position: relative;
  z-index: 2;
  background: #ffffff;
  border-bottom: 1px solid var(--border);
  overflow: hidden;
}
.hp-ticker-sr {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  border: 0;
}
.hp-ticker-row {
  display: flex;
  align-items: center;
  position: relative;
  border-bottom: 1px solid var(--border);
  height: 38px;
  overflow: hidden;
}
.hp-ticker-row:last-child { border-bottom: 0; }
.hp-ticker-row.reverse {
  background: #111111;
  color: #ffffff;
}
.hp-ticker-label {
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  z-index: 2;
  display: flex;
  align-items: center;
  padding: 0 28px 0 18px;
  background: #ffffff;
  font-family: ui-monospace, "SF Mono", Menlo, monospace;
  font-size: 10px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--fg-muted);
  font-weight: 600;
  min-width: 160px;
}
.hp-ticker-row.reverse .hp-ticker-label {
  color: rgba(255, 255, 255, 0.78);
  background: #111111;
}
.hp-ticker-track {
  display: flex;
  gap: 36px;
  white-space: nowrap;
  padding-left: 170px;
  animation: hp-ticker-scroll var(--hp-ticker-dynamic-duration, var(--hp-ticker-duration, 72s)) linear infinite;
  animation-duration: calc(var(--hp-ticker-dynamic-duration, var(--hp-ticker-duration, 72s)) / var(--ticker-speed, 1));
}
.hp-ticker-row.reverse .hp-ticker-track {
  animation-direction: reverse;
  animation-duration: calc(var(--hp-ticker-dynamic-duration, var(--hp-trade-ticker-duration, 60s)) / var(--ticker-speed, 1));
}
@keyframes hp-ticker-scroll {
  from { transform: translateX(0); }
  to { transform: translateX(var(--hp-ticker-scroll-offset, -50%)); }
}
.hp-ticker-item {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 13px;
  color: var(--fg);
  font-weight: 500;
}
.hp-ticker-item-link {
  cursor: pointer;
  text-decoration: underline;
  text-decoration-offset: 3px;
}
.hp-ticker-item .dot {
  width: 5px; height: 5px; border-radius: 50%;
  background: var(--hp-primary);
}
.hp-ticker-trade {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 13px;
  color: var(--fg);
  font-weight: 700;
  text-decoration: none;
  transition: color var(--dur-fast) var(--ease);
}
.hp-ticker-trade:hover { color: var(--hp-primary); }
.hp-ticker-empty {
  display: inline-flex;
  align-items: center;
  font-size: 13px;
  color: var(--fg);
  font-weight: 700;
}
.hp-ticker-row.reverse .hp-ticker-trade {
  color: #ffffff;
}
.hp-ticker-row.reverse .hp-ticker-empty {
  color: #ffffff;
}
.hp-ticker-row.reverse .hp-ticker-trade:hover {
  color: color-mix(in oklab, white 76%, var(--hp-accent));
}
.hp-ticker-trade .pip {
  width: 8px; height: 8px;
  border-radius: 2px;
  transform: rotate(45deg);
  background: var(--fg-muted);
}
.hp-ticker-trade .pip.diamond { background: linear-gradient(135deg, #B0E0FF, #5C8FBE); }
.hp-ticker-trade .pip.unicorn {
  background: linear-gradient(135deg, var(--hp-primary), var(--hp-accent), #FFD700);
  box-shadow: 0 0 6px rgba(210, 9, 227, 0.4);
}

@media (max-width: 640px) {
  .hp-header-inner {
    padding-inline: 12px;
  }

  .hp-header-nav {
    gap: 16px;
    max-width: 100%;
  }

  .hp-coming-soon-badge {
    display: none;
  }

  .hp-header-link {
    justify-content: center;
    min-width: 0;
    min-height: 44px;
    padding-inline: 0;
    font-size: 12px;
  }

  .hp-shop-btn {
    min-height: 44px;
  }

  .hp-ticker {
    overflow-x: clip;
    contain: layout paint;
  }

  .hp-ticker-row {
    width: 100%;
    max-width: 100vw;
    display: block;
    contain: layout paint;
  }

  .hp-ticker-label {
    min-width: 124px;
    padding: 0 22px 0 14px;
  }

  .hp-ticker-track {
    position: absolute;
    inset: 0 auto 0 0;
    align-items: center;
    width: max-content;
    max-width: none;
    min-width: max-content;
    padding-left: 132px;
    gap: 24px;
  }
}

/* ============================================================
   Hero (HE2 full-bleed)
   ============================================================ */
.hp-hero {
  position: relative;
  min-height: clamp(620px, 86vh, 760px);
  display: flex;
  align-items: center;
  color: white;
  overflow: hidden;
}
.hp-hero-media {
  position: absolute;
  inset: 0;
  z-index: 0;
  background:
    linear-gradient(180deg, rgba(14,8,32,0.1) 0%, rgba(14,8,32,0.55) 65%, rgba(14,8,32,0.85) 100%),
    radial-gradient(ellipse at 30% 30%, var(--hp-primary), transparent 60%),
    radial-gradient(ellipse at 70% 70%, var(--hp-accent), #0E0820 70%);
  background-blend-mode: normal, soft-light, normal;
}
.hp-hero .hp-hero-fx-layer {
  position: absolute;
  z-index: 1;
}
.hp-hero-inner {
  position: relative;
  z-index: 2;
  width: 100%;
  max-width: 1280px;
  margin: 0 auto;
  padding: 96px 24px 96px;
  display: grid;
  grid-template-columns: minmax(0, 620px);
  justify-content: center;
  text-align: center;
}
.hp-hero-inner > div {
  min-width: 0;
}
.hp-hero-headline {
  font-family: var(--hp-display-font);
  font-size: clamp(48px, 7vw, 88px);
  font-weight: var(--hp-heading-weight);
  letter-spacing: var(--hp-heading-tracking);
  line-height: 1.08;
  margin-bottom: 18px;
  padding-block: 0.04em 0.12em;
  color: white;
  text-wrap: balance;
  overflow: visible;
}
.hp-hero-headline em {
  font-style: italic;
  font-weight: 400;
  color: rgba(255,255,255,0.85);
}
.hp-hero-sub {
  font-size: 18px;
  line-height: 1.55;
  color: rgba(255,255,255,0.78);
  max-width: 540px;
  margin-left: auto;
  margin-right: auto;
  margin-bottom: 36px;
}
.hp-mhf-hero-kicker {
  margin-bottom: 14px;
  color: rgba(255,255,255,0.78);
  font-size: 13px;
  font-weight: 800;
  letter-spacing: 0.24em;
  text-transform: uppercase;
}
.hp-hero-ctas {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  align-items: center;
  justify-content: center;
}
.hp-hero-cta-stack {
  display: inline-flex;
  flex-direction: column;
  gap: 12px;
  width: fit-content;
  max-width: 100%;
}
.hp-reveal-screenshot-tip {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-wrap: wrap;
  gap: 4px 8px;
  width: min(100%, 680px);
  margin: 28px auto 0;
  padding: 12px 18px;
  border: 1px solid var(--hp-tip-border);
  border-radius: 14px;
  background: var(--hp-tip-surface);
  color: var(--hp-tip-ink);
  box-shadow: 0 12px 32px rgba(0, 0, 0, 0.22);
  font-size: 13px;
  line-height: 1.5;
  text-align: center;
  text-shadow: none;
}
.hp-reveal-screenshot-tip strong { color: var(--hp-tip-accent); }
.hp-hero-cta-primary-row {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  justify-content: center;
}
.hp-hero-trade-board-cta {
  width: 100%;
  justify-content: center;
}
.hp-hero-side {
  background: rgba(255,255,255,0.06);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border: 1px solid rgba(255,255,255,0.12);
  border-radius: 16px;
  padding: 24px;
  align-self: end;
  min-width: 320px;
}
.hp-hero-side-label {
  font-size: 11px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: rgba(255,255,255,0.6);
  margin-bottom: 14px;
  display: flex;
  align-items: center;
  gap: 8px;
}
.hp-hero-side-label .live-pip {
  width: 8px; height: 8px;
  border-radius: 50%;
  background: #FF3366;
  box-shadow: 0 0 0 4px rgba(255,51,102,0.3);
  animation: hp-pulse 1.6s var(--ease) infinite;
}
@keyframes hp-pulse {
  0%, 100% { opacity: 1; transform: scale(1); }
  50% { opacity: 0.7; transform: scale(0.92); }
}
.hp-stream-row {
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.hp-stream-btn {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 14px 16px;
  border-radius: 10px;
  background: rgba(255,255,255,0.08);
  border: 1px solid rgba(255,255,255,0.12);
  color: white;
  font-size: 14px;
  font-weight: 500;
  cursor: pointer;
  transition: all var(--dur-fast) var(--ease);
  text-align: left;
  width: 100%;
}
.hp-stream-btn:hover {
  background: rgba(255,255,255,0.15);
  transform: translateY(-1px);
}
.hp-stream-btn .glyph {
  width: 28px; height: 28px;
  border-radius: 6px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 12px;
  font-weight: 700;
  color: white;
  flex-shrink: 0;
}
.hp-stream-btn .glyph.tt { background: linear-gradient(135deg, #25F4EE, #FE2C55); }
.hp-stream-btn .glyph.fb { background: #1877F2; }
.hp-stream-btn .glyph.shop { background: linear-gradient(135deg, var(--hp-primary), var(--hp-accent)); }
.hp-stream-btn .meta {
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.hp-stream-btn .meta .name { font-size: 14px; }
.hp-stream-btn .meta .handle {
  font-size: 11px;
  color: rgba(255,255,255,0.55);
  font-family: ui-monospace, monospace;
}

@media (max-width: 900px) {
  .hp-hero-inner { padding-bottom: 56px; }
}

@media (max-width: 640px) {
  .hp-hero-inner {
    width: 100vw;
    max-width: 100vw;
    margin-inline: calc(50% - 50vw);
    padding: 72px 20px 56px;
  }

  .hp-hero-headline {
    font-size: clamp(36px, 10.5vw, 48px);
    line-height: 1.12;
    max-width: 11ch;
    padding-block: 0.04em 0.12em;
    margin-left: auto;
    margin-right: auto;
    overflow-wrap: anywhere;
  }

  .hp-hero-sub {
    max-width: 100%;
  }
}

/* Watch live dropdown */
.hp-watch-wrap {
  position: relative;
  display: inline-block;
}
.hp-watch-caret {
  margin-left: 4px;
  font-size: 11px;
  opacity: 0.7;
}
.hp-watch-menu {
  position: absolute;
  top: calc(100% + 8px);
  left: 0;
  min-width: 240px;
  background: rgba(20, 12, 40, 0.92);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border: 1px solid rgba(255,255,255,0.12);
  border-radius: 12px;
  padding: 6px;
  display: flex;
  flex-direction: column;
  gap: 2px;
  opacity: 0;
  visibility: hidden;
  transform: translateY(-4px);
  transition: opacity var(--dur-fast) var(--ease), transform var(--dur-fast) var(--ease), visibility var(--dur-fast);
  z-index: 10;
  box-shadow: 0 16px 40px rgba(0,0,0,0.4);
}
.hp-watch-wrap.open .hp-watch-menu {
  opacity: 1;
  visibility: visible;
  transform: translateY(0);
}
.hp-watch-option {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px 12px;
  border-radius: 8px;
  color: white;
  text-decoration: none;
  transition: background var(--dur-fast) var(--ease);
}
.hp-watch-option:hover { background: rgba(255,255,255,0.08); color: white; }
.hp-watch-option .glyph {
  width: 28px; height: 28px;
  border-radius: 6px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 12px;
  font-weight: 700;
  color: white;
  flex-shrink: 0;
}
.hp-watch-option .glyph.tt { background: linear-gradient(135deg, #25F4EE, #FE2C55); }
.hp-watch-option .glyph.fb { background: #1877F2; }
.hp-watch-option .meta { display: flex; flex-direction: column; gap: 2px; }
.hp-watch-option .name { font-size: 14px; font-weight: 500; }
.hp-watch-option .handle { font-size: 11px; color: rgba(255,255,255,0.55); font-family: ui-monospace, monospace; }
.hp-btn-outline .live-pip {
  width: 7px; height: 7px;
  border-radius: 50%;
  background: #FF3366;
  box-shadow: 0 0 0 3px rgba(255,51,102,0.3);
  animation: hp-pulse 1.6s var(--ease) infinite;
}

/* ============================================================
   LRQ rail
   ============================================================ */
.hp-lrq {
  background: #ffffff;
  border-bottom: 1px solid var(--border);
}
.hp-lrq-inner {
  max-width: 1280px;
  margin: 0 auto;
  padding: 18px 24px;
  display: flex;
  align-items: center;
  gap: 24px;
  flex-wrap: wrap;
}
.hp-lrq-title {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 11px;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  font-weight: 600;
  color: var(--fg);
}
.hp-lrq-title .live-dot {
  width: 8px; height: 8px;
  border-radius: 50%;
  background: #FF3366;
  box-shadow: 0 0 0 4px rgba(255,51,102,0.2);
  animation: hp-pulse 1.6s var(--ease) infinite;
}
.hp-lrq-items {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
  flex: 1;
}
.hp-lrq-item {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  background: var(--hp-bg);
  border: 1px solid var(--border);
  border-radius: 999px;
  padding: 8px 16px 8px 8px;
}
.hp-lrq-item .pos {
  width: 26px; height: 26px;
  border-radius: 50%;
  background: var(--hp-primary);
  color: white;
  font-size: 12px;
  font-weight: 600;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}
.hp-lrq-item.on-deck .pos {
  background: var(--hp-bg-elevated);
  color: var(--fg);
  border: 1px solid var(--border);
}
.hp-lrq-item .name { font-size: 13px; font-weight: 500; }
.hp-lrq-item .label {
  font-size: 10px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--fg-muted);
  margin-right: 4px;
}

/* ============================================================
   Sticky trade preview strip
   ============================================================ */
.hp-trade-preview {
  position: relative;
  z-index: 1;
  background: var(--hp-preview-bg, color-mix(in oklab, #ffffff 92%, transparent));
  color: var(--hp-preview-fg, var(--fg));
  backdrop-filter: blur(10px);
  border-bottom: 1px solid var(--border);
}
.hp-trade-preview-inner {
  max-width: 1280px;
  margin: 0 auto;
  padding: 10px 24px;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto auto;
  grid-template-areas: "head items link updated";
  gap: 16px;
  align-items: center;
}
.hp-trade-preview-head {
  grid-area: head;
  display: inline-flex;
  align-items: center;
  gap: 10px;
  font-size: 10px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--hp-preview-fg, var(--fg));
  font-weight: 700;
  white-space: nowrap;
}
.hp-trade-preview-head .live-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #FF3366;
  box-shadow: 0 0 0 4px rgba(255,51,102,0.2);
  animation: hp-pulse 1.6s var(--ease) infinite;
}
.hp-trade-preview-items {
  grid-area: items;
  display: flex;
  gap: 10px;
  overflow-x: auto;
  scrollbar-width: none;
}
.hp-trade-preview-items::-webkit-scrollbar {
  display: none;
}
.hp-trade-preview-pill {
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
  padding: 8px 12px 8px 8px;
  border-radius: 999px;
  border: 1px solid var(--border);
  background: var(--hp-bg-elevated);
  text-decoration: none;
  color: var(--fg);
  cursor: pointer;
  text-align: left;
}
.hp-trade-preview-pill .pos {
  width: 26px;
  height: 26px;
  border-radius: 50%;
  background: var(--hp-primary);
  color: white;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 12px;
  font-weight: 700;
  flex-shrink: 0;
}
.hp-trade-preview-pill .meta {
  display: flex;
  flex-direction: column;
  min-width: 0;
}
.hp-trade-preview-pill .label {
  font-size: 9px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--fg-muted);
  font-weight: 600;
}
.hp-trade-preview-pill .name {
  font-size: 13px;
  font-weight: 600;
  white-space: nowrap;
}
.hp-trade-preview-link {
  grid-area: link;
  white-space: nowrap;
  font-size: 12px;
  font-weight: 700;
  color: var(--hp-primary);
  text-decoration: none;
  background: transparent;
  border: 0;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  transition: transform var(--dur-fast) var(--ease), color var(--dur-fast) var(--ease), opacity var(--dur-fast) var(--ease);
  transform-origin: center right;
}
.hp-trade-preview-updated {
  grid-area: updated;
  justify-self: end;
  color: var(--hp-preview-muted, var(--fg-muted));
  font-size: 11px;
  font-weight: 600;
  white-space: nowrap;
}
.hp-trade-preview-link:hover {
  transform: translateX(2px);
}
.hp-trade-preview-link:active {
  transform: scale(0.96);
  opacity: 0.72;
}
.hp-trade-preview-link:focus-visible {
  outline: 2px solid color-mix(in oklab, var(--hp-primary) 45%, white);
  outline-offset: 4px;
}
@media (max-width: 860px) {
  .hp-trade-preview-inner {
    grid-template-columns: minmax(0, 1fr) auto;
    grid-template-areas:
      "head updated"
      "items items"
      "link link";
    align-items: stretch;
  }
  .hp-trade-preview-link {
    justify-self: start;
  }
}

@media (max-width: 640px) {
  .hp-trade-preview-inner {
    padding: 10px 16px;
    gap: 10px;
  }

  .hp-trade-preview-items {
    max-width: 100%;
    overscroll-behavior-inline: contain;
  }
}

.hp-lineup-status { margin: 0; font-size: 14px; color: var(--fg-muted); }
.hp-queue-modal-mask {
  position: fixed;
  inset: 0;
  z-index: 96;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
  background: rgba(14, 8, 32, 0.58);
  backdrop-filter: blur(6px);
  animation: hp-modal-fade 180ms var(--ease);
}

.hp-queue-modal {
  overflow: hidden;
  width: min(560px, 100%);
  max-height: min(80vh, 760px);
  display: flex;
  flex-direction: column;
  gap: 18px;
  padding: 24px;
  border: 1px solid var(--border);
  border-radius: 24px;
  background: color-mix(in oklab, var(--hp-bg-elevated) 92%, white);
  box-shadow: 0 28px 80px rgba(14, 8, 32, 0.28);
  animation: hp-modal-rise 240ms cubic-bezier(.22, 1, .36, 1);
}

@keyframes hp-modal-fade {
  from { opacity: 0; }
  to { opacity: 1; }
}

@keyframes hp-modal-rise {
  from {
    opacity: 0;
    transform: translateY(18px) scale(0.985);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

.hp-queue-modal-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
}

.hp-queue-modal-eyebrow {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--hp-primary);
}

.hp-queue-modal-title {
  margin: 6px 0 0;
  font-family: var(--hp-display-font);
  font-size: clamp(2rem, 4vw, 2.5rem);
  line-height: 1;
  letter-spacing: -0.03em;
  color: var(--fg);
}

.hp-queue-modal-close {
  width: 40px;
  height: 40px;
  flex-shrink: 0;
  border-radius: 999px;
  border: 1px solid var(--border);
  background: white;
  color: #2b1b1f;
  font-size: 24px;
  font-weight: 700;
  line-height: 1;
  cursor: pointer;
}

.hp-queue-modal-close:hover {
  background: #f7edf6;
}

.hp-queue-modal-close:focus-visible {
  outline: 3px solid var(--hp-primary);
  outline-offset: 3px;
}

.hp-queue-modal-list {
  min-height: 0;
  overscroll-behavior: contain;
  display: flex;
  flex-direction: column;
  gap: 10px;
  overflow-y: auto;
  padding-right: 4px;
  min-height: 0;
}

.hp-queue-modal-row {
  display: grid;
  grid-template-columns: 30px 1fr;
  align-items: center;
  gap: 12px;
  padding: 12px 14px;
  border-radius: 16px;
  background: white;
  border: 1px solid rgba(89, 62, 69, 0.16);
  color: #2b1b1f;
}

.hp-queue-modal-row.now {
  background: linear-gradient(95deg,
    color-mix(in oklab, var(--hp-primary) 9%, white),
    color-mix(in oklab, var(--hp-accent) 9%, white)
  );
}

.hp-queue-modal-row .pos {
  width: 30px;
  height: 30px;
  border-radius: 50%;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 12px;
  font-weight: 700;
  background: #1f1718;
  border: 1px solid rgba(89, 62, 69, 0.18);
  color: #fffaf6;
}

.hp-queue-modal-row.now .pos {
  background: var(--hp-primary);
  border-color: transparent;
  color: white;
}

.hp-queue-modal-row .meta {
  display: flex;
  flex-direction: column;
  min-width: 0;
}

.hp-queue-modal-row .label {
  font-size: 9px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: #8a6f76;
  font-weight: 700;
}

.hp-queue-modal-row .name {
  overflow-wrap: anywhere;
  font-size: 14px;
  font-weight: 700;
  color: #2b1b1f;
}

.hp-queue-modal-empty {
  overflow-wrap: anywhere;
  padding: 20px 0 6px;
  font-size: 14px;
  line-height: 1.6;
  color: var(--fg-muted);
}

@media (max-width: 640px) {
  .hp-queue-modal-mask {
    padding: 16px;
    align-items: flex-end;
  }

  .hp-queue-modal {
    max-height: 78vh;
    padding: 20px 18px;
    border-radius: 22px 22px 0 0;
  }
}

/* ============================================================
   Section frame
   ============================================================ */
.hp-section {
  padding: var(--hp-section-pad) 0;
}
.hp-section.tight { padding: calc(var(--hp-section-pad) * 0.6) 0; }
.hp-container {
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 24px;
}
.hp-section-eyebrow {
  font-family: ui-monospace, "SF Mono", Menlo, monospace;
  font-size: 12px;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--hp-primary);
  margin-bottom: 16px;
  display: inline-flex;
  align-items: center;
  gap: 10px;
}
.hp-section-eyebrow::before {
  content: ""; width: 24px; height: 1px;
  background: var(--hp-primary);
}
.hp-section-title {
  font-family: var(--hp-display-font);
  font-size: clamp(32px, 4vw, 48px);
  letter-spacing: var(--hp-heading-tracking);
  line-height: 1.12;
  margin-bottom: 12px;
  padding-block: 0.03em 0.09em;
  font-weight: var(--hp-heading-weight);
  max-width: 820px;
  text-wrap: balance;
  overflow: visible;
}
.hp-section-sub {
  font-size: 17px;
  line-height: 1.55;
  color: var(--fg-muted);
  max-width: 640px;
  margin-bottom: 48px;
}

/* ============================================================
   Dance Floor
   ============================================================ */
.hp-trade-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 24px;
}
.hp-trade-card {
  background: var(--hp-bg-elevated);
  border: 1px solid var(--border);
  border-radius: var(--hp-radius-card);
  overflow: hidden;
  cursor: pointer;
  transition: transform 400ms cubic-bezier(.4,0,.2,1), box-shadow 400ms cubic-bezier(.4,0,.2,1);
  position: relative;
}
.hp-trade-card:hover {
  transform: translateY(-6px);
  box-shadow: 0 24px 48px rgba(42,31,64,0.16);
}
.hp-trade-photo {
  aspect-ratio: 1 / 1;
  background: linear-gradient(135deg, var(--bg-deep), var(--hp-bg-elevated));
  position: relative;
  overflow: hidden;
}
.hp-trade-photo .placeholder {
  position: absolute; inset: 0;
  display: flex; align-items: center; justify-content: center;
  color: rgba(42,31,64,0.32);
  font-size: 11px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}
.hp-trade-tier {
  position: absolute;
  top: 14px;
  left: 14px;
  padding: 6px 10px;
  background: rgba(255,255,255,0.92);
  backdrop-filter: blur(10px);
  border-radius: 999px;
  font-size: 10px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  font-weight: 600;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: var(--fg);
}
.hp-trade-tier .pip {
  width: 8px; height: 8px;
  border-radius: 50%;
  background: var(--fg-muted);
}
.hp-trade-tier.diamond .pip { background: linear-gradient(135deg, #B0E0FF, #5C8FBE); }
.hp-trade-tier.unicorn { background: linear-gradient(135deg, rgba(210,9,227,0.95), rgba(72,13,223,0.95)); color: white; }
.hp-trade-tier.unicorn .pip { background: linear-gradient(135deg, #FFD700, white); box-shadow: 0 0 6px white; }
.hp-trade-status {
  position: absolute;
  top: 14px;
  right: 14px;
  padding: 6px 10px;
  background: rgba(0,0,0,0.6);
  color: white;
  backdrop-filter: blur(10px);
  border-radius: 999px;
  font-size: 10px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  font-weight: 600;
}
.hp-trade-status.reserved { background: rgba(255,200,0,0.92); color: #2A1F40; }
.hp-trade-status.traded { background: rgba(120,120,120,0.6); }
.hp-trade-meta {
  padding: 18px;
}
.hp-trade-name {
  font-size: 16px;
  font-weight: 600;
  margin-bottom: 6px;
  letter-spacing: -0.005em;
}
.hp-trade-desc {
  font-size: 13px;
  color: var(--fg-muted);
  line-height: 1.5;
  margin-bottom: 14px;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.hp-trade-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: 14px;
  border-top: 1px solid var(--border);
}
.hp-trade-cta {
  font-size: 12px;
  font-weight: 600;
  color: var(--hp-primary);
  display: inline-flex;
  align-items: center;
  gap: 4px;
  letter-spacing: 0.04em;
}

/* ============================================================
   Event Calendar
   ============================================================ */
.hp-event-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 24px;
  max-width: 880px;
  margin: 0 auto;
}
.hp-events-head {
  max-width: 880px;
  margin: 0 auto 36px;
  text-align: center;
  display: flex;
  flex-direction: column;
  align-items: center;
}
.hp-events-head .hp-section-eyebrow::after {
  content: ""; width: 24px; height: 1px;
  background: var(--hp-primary);
}
.hp-events-head .hp-section-sub {
  margin-left: auto;
  margin-right: auto;
  max-width: 560px;
}
@media (max-width: 800px) {
  .hp-event-grid { grid-template-columns: 1fr; }
}
.hp-event-card {
  position: relative;
  background: var(--hp-bg-elevated);
  border: 1px solid var(--border);
  border-radius: var(--hp-radius-card);
  padding: 18px 18px 16px;
  display: flex;
  flex-direction: column;
  gap: 14px;
}
.hp-event-card.featured {
  background: linear-gradient(180deg, var(--hp-bg-elevated), var(--bg-deep));
  border-color: var(--hp-primary);
}

/* Featured pill — top-right corner */
.hp-event-pill {
  position: absolute;
  top: 14px;
  right: 14px;
  font-size: 10px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  font-weight: 700;
  padding: 6px 10px;
  border-radius: 999px;
  background: var(--hp-primary);
  color: white;
  display: inline-flex;
  align-items: center;
  gap: 6px;
}
.hp-event-pill .pip {
  width: 6px; height: 6px;
  border-radius: 50%;
  background: white;
  animation: hp-pulse 1.6s var(--ease) infinite;
}

/* Event title */
.hp-event-name {
  font-family: var(--hp-display-font);
  font-size: 19px;
  font-weight: 700;
  letter-spacing: var(--hp-heading-tracking);
  line-height: 1.2;
  color: var(--fg);
  padding-right: 78px; /* space for featured pill */
  margin: 0;
}

/* Date + time meta block */
.hp-event-meta {
  display: flex;
  flex-direction: column;
  gap: 4px;
  margin-top: -8px;
}
.hp-event-meta-row {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 13px;
  color: var(--hp-primary);
  font-weight: 500;
}
.hp-event-meta-icon {
  display: inline-flex;
  color: var(--hp-primary);
}

/* Show note — a restrained editorial inset that stays readable across skins. */
.hp-event-description {
  position: relative;
  margin: 0;
  padding: 11px 14px 11px 17px;
  overflow-wrap: anywhere;
  white-space: pre-line;
  color: var(--hp-card-muted);
  background: color-mix(in srgb, var(--hp-card-accent) 7%, transparent);
  border: 1px solid color-mix(in srgb, var(--hp-card-accent) 18%, transparent);
  border-radius: 14px;
  font-size: 13.5px;
  font-weight: 500;
  line-height: 1.58;
  letter-spacing: 0.005em;
  box-shadow: inset 0 1px 0 color-mix(in srgb, white 38%, transparent);
}

/* Section heading w/ icon */
.hp-event-section {
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.hp-event-section-head {
  display: inline-flex;
  align-items: center;
  gap: 8px;
}
.hp-event-section-icon {
  width: 20px;
  height: 20px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
}
.hp-event-section-icon.discounts {
  color: var(--hp-primary);
}
.hp-event-section-icon.featured-collections {
  color: var(--hp-accent);
}
.hp-event-section-title {
  font-size: 14px;
  font-weight: 700;
  color: var(--fg);
  letter-spacing: 0;
}

/* Discount code rows — full-width */
.hp-event-codes {
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.hp-event-code-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 9px 12px;
  background: var(--hp-bg);
  border: 1px solid var(--border);
  border-radius: 10px;
  transition: border-color var(--dur-fast) var(--ease);
}
.hp-event-code-row:hover {
  border-color: var(--hp-primary);
}
.hp-event-code-text {
  font-size: 13px;
  color: var(--fg);
  line-height: 1.45;
  min-width: 0;
}
.hp-event-code-text strong {
  font-family: ui-monospace, "SF Mono", Menlo, monospace;
  font-weight: 700;
  letter-spacing: 0.04em;
  color: var(--fg);
}
.hp-event-code-text .dash {
  color: var(--fg-muted);
}
.hp-event-code-text .desc {
  color: var(--fg-muted);
}
.hp-event-copy {
  flex-shrink: 0;
  background: transparent;
  border: 1px solid var(--border);
  border-radius: 999px;
  padding: 6px 14px;
  font-size: 12px;
  font-weight: 600;
  color: var(--hp-primary);
  cursor: pointer;
  letter-spacing: 0.02em;
  transition: all var(--dur-fast) var(--ease);
}
.hp-event-copy:hover {
  background: var(--hp-primary);
  color: white;
  border-color: var(--hp-primary);
}
.hp-event-copy.copied {
  background: var(--hp-primary);
  color: white;
  border-color: var(--hp-primary);
}

/* Featured collection pills — 2-column stack */
.hp-event-collections {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
}
.hp-event-collection-pill {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  padding: 7px 14px;
  background: color-mix(in oklab, var(--hp-primary) 8%, transparent);
  border: 1px solid color-mix(in oklab, var(--hp-primary) 22%, transparent);
  border-radius: 999px;
  font-size: 13px;
  font-weight: 500;
  color: var(--hp-primary);
  text-decoration: none;
  transition: all var(--dur-fast) var(--ease);
}
.hp-event-collection-pill:hover {
  background: var(--hp-primary);
  color: white;
  border-color: var(--hp-primary);
}

/* Actions row — stacked full-width */
.hp-event-actions {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-top: 6px;
}
.hp-event-platform {
  width: 100%;
  justify-content: center;
}
.hp-event-add {
  width: 100%;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 12px 22px;
  border-radius: 999px;
  background: transparent;
  color: var(--fg-muted);
  border: 1px solid var(--border);
  font-size: 14px;
  font-weight: 500;
  cursor: pointer;
  letter-spacing: 0.01em;
  white-space: nowrap;
  transition: all var(--dur-fast) var(--ease);
}
.hp-event-add:hover {
  color: var(--hp-primary);
  border-color: var(--hp-primary);
}
.hp-calendar-modal-mask {
  position: fixed;
  inset: 0;
  z-index: 97;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
  background: rgba(14, 8, 32, 0.58);
  backdrop-filter: blur(6px);
  animation: hp-modal-fade 180ms var(--ease);
}
.hp-calendar-modal {
  width: min(440px, 100%);
  padding: 24px;
  border: 1px solid var(--border);
  border-radius: 24px;
  background: color-mix(in oklab, var(--hp-bg-elevated) 92%, white);
  box-shadow: 0 28px 80px rgba(14, 8, 32, 0.28);
  animation: hp-modal-rise 240ms cubic-bezier(.22, 1, .36, 1);
}
.hp-calendar-modal-head { display: flex; align-items: flex-start; justify-content: space-between; gap: 16px; }
.hp-calendar-modal-eyebrow { font-size: 11px; font-weight: 700; letter-spacing: .18em; text-transform: uppercase; color: var(--hp-primary); }
.hp-calendar-modal-title { margin: 6px 0; font-family: var(--hp-display-font); font-size: clamp(1.75rem, 7vw, 2.25rem); line-height: 1; color: var(--fg); }
.hp-calendar-modal-head p { margin: 0; color: var(--fg-muted); font-size: 14px; }
.hp-calendar-modal-close { width: 40px; height: 40px; flex-shrink: 0; border-radius: 999px; border: 1px solid var(--border); background: white; color: #2b1b1f; font-size: 24px; font-weight: 700; line-height: 1; cursor: pointer; }
.hp-calendar-modal-close:hover { background: #f7edf6; }
.hp-calendar-choice-list { display: grid; gap: 10px; margin-top: 22px; }
.hp-calendar-choice { display: flex; align-items: center; justify-content: center; min-height: 48px; padding: 12px 18px; border: 1px solid var(--border); border-radius: 14px; background: var(--hp-bg); color: var(--fg); font: inherit; font-size: 15px; font-weight: 700; cursor: pointer; text-decoration: none; }
.hp-calendar-choice:hover { border-color: var(--hp-primary); color: var(--hp-primary); }
.hp-calendar-choice.google { background: #4285f4; border-color: #4285f4; color: white; }
.hp-calendar-choice.outlook { background: #0078d4; border-color: #0078d4; color: white; }
.hp-calendar-choice.other { width: 100%; }
.hp-calendar-modal-note { margin: 14px 0 0; color: var(--fg-muted); font-size: 12px; line-height: 1.45; text-align: center; }
.hp-event-platform {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  padding: 12px 22px;
  border-radius: 999px;
  font-size: 14px;
  font-weight: 600;
  border: 0;
  cursor: pointer;
  color: white;
  letter-spacing: 0.01em;
  white-space: nowrap;
  transition: transform var(--dur-fast) var(--ease), filter var(--dur-fast) var(--ease);
}
.hp-event-platform.tt {
  background: linear-gradient(95deg, var(--hp-primary), var(--hp-accent));
}
.hp-event-platform.tiktok {
  background: linear-gradient(95deg, var(--hp-primary), var(--hp-accent));
}
.hp-event-platform.fb {
  background: #1877F2;
}
.hp-event-platform.instagram { background: linear-gradient(95deg, #833AB4, #FD1D1D, #FCAF45); }
.hp-event-platform.youtube { background: #FF0000; }
.hp-event-platform.facebook { background: #1877F2; }
.hp-event-platform.whatnot { background: #3a6cff; }
.hp-event-platform.custom { background: linear-gradient(95deg, var(--hp-primary), var(--hp-accent)); }
.hp-event-platform:hover { filter: brightness(1.05); transform: translateY(-1px); }
.hp-event-platform .glyph {
  width: 18px; height: 18px;
  border-radius: 4px;
  flex-shrink: 0;
}
.hp-event-platform .glyph.tt { background: rgba(255,255,255,0.95); position: relative; }
.hp-event-platform .glyph.tiktok { background: rgba(255,255,255,0.95); position: relative; }
.hp-event-platform .glyph.tt::after {
  content: "♪";
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 12px;
  color: var(--hp-primary);
  font-weight: 700;
}
.hp-event-platform .glyph.fb { background: rgba(255,255,255,0.95); position: relative; }
.hp-event-platform .glyph.fb::after {
  content: "f";
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: Georgia, serif;
  font-style: italic;
  font-weight: 900;
  font-size: 13px;
  color: #1877F2;
}

/* ============================================================
   What is a Bomb Party (explainer + video)
   ============================================================ */
.hp-wibp-grid {
  display: grid;
  grid-template-columns: 1.1fr 1fr;
  gap: 24px;
  max-width: 880px;
  margin: 0 auto;
}
@media (max-width: 900px) { .hp-wibp-grid { grid-template-columns: 1fr; } }

.hp-wibp-card {
  background: var(--hp-bg-elevated);
  border: 1px solid var(--border);
  border-radius: var(--hp-radius-card);
  color: var(--hp-card-fg);
  padding: 36px;
  display: flex;
  flex-direction: column;
  gap: 18px;
}
.hp-wibp-eyebrow {
  font-family: ui-monospace, "SF Mono", Menlo, monospace;
  font-size: 11px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--hp-card-accent);
  font-weight: 600;
}
.hp-event-platform .glyph.tiktok::after {
  content: "♪";
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 12px;
  color: var(--hp-primary);
  font-weight: 700;
}
.hp-event-platform .glyph.instagram,
.hp-event-platform .glyph.youtube,
.hp-event-platform .glyph.facebook,
.hp-event-platform .glyph.whatnot,
.hp-event-platform .glyph.custom { background: rgba(255,255,255,0.95); position: relative; }
.hp-event-platform .glyph.instagram::after,
.hp-event-platform .glyph.youtube::after,
.hp-event-platform .glyph.facebook::after,
.hp-event-platform .glyph.whatnot::after,
.hp-event-platform .glyph.custom::after {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 10px;
  font-weight: 800;
  color: var(--hp-primary);
}
.hp-event-platform .glyph.instagram::after { content: "◎"; }
.hp-event-platform .glyph.youtube::after { content: "▶"; }
.hp-event-platform .glyph.facebook::after { content: "f"; }
.hp-event-platform .glyph.whatnot::after { content: "W"; }
.hp-event-platform .glyph.custom::after { content: "↗"; }
.hp-wibp-title {
  font-family: var(--hp-display-font);
  font-size: 32px;
  letter-spacing: var(--hp-heading-tracking);
  line-height: 1.1;
  color: var(--hp-card-fg);
}
.hp-wibp-body {
  font-size: 15px;
  line-height: 1.6;
  color: var(--hp-card-muted);
}
.hp-steps {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 14px;
  margin-top: 12px;
}
.hp-step {
  background: var(--hp-bg);
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 14px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.hp-step-num {
  width: 42px; height: 42px;
  border-radius: 50%;
  background: var(--hp-media-card-header-bg);
  color: var(--hp-media-card-accent-contrast);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  box-shadow: 0 10px 24px color-mix(in srgb, var(--hp-primary) 24%, transparent);
}
.hp-step-num .hp-customer-media-icon-svg { width: 19px; height: 19px; }
body.bg-suite-paper .hp-step-num,
body.bg-rose-gold-paper .hp-step-num,
body.bg-amber-paper .hp-step-num,
body.bg-quartz-paper .hp-step-num {
  color: #141111;
}
.hp-step-label {
  font-size: 14px;
  font-weight: 600;
  color: var(--hp-card-fg);
}
.hp-step-desc {
  font-size: 12px;
  color: var(--hp-card-muted);
  line-height: 1.5;
}
/* The three-step explainer remains a visual row on larger screens. On phones,
   each step needs enough measure for its label and supporting copy, so use a
   compact, stacked sequence rather than three squeezed columns. */
@media (max-width: 720px) {
  .hp-steps {
    grid-template-columns: 1fr;
    gap: 12px;
  }

  .hp-step {
    grid-template-columns: 42px minmax(0, 1fr);
    column-gap: 14px;
    row-gap: 3px;
    align-items: start;
  }

  .hp-step-num {
    grid-row: span 2;
  }

  .hp-step-label,
  .hp-step-desc {
    min-width: 0;
  }
}
.hp-wibp-video {
  width: min(100%, 340px);
  justify-self: center;
}

.hp-customer-media-card {
  position: relative;
  display: flex;
  flex-direction: column;
  min-width: 0;
  margin: 0;
  overflow: hidden;
  color: var(--hp-media-card-fg);
  background: var(--hp-media-card-bg);
  border: 1px solid var(--hp-media-card-border);
  border-radius: var(--hp-media-card-radius);
  box-shadow: var(--hp-media-card-shadow);
  isolation: isolate;
  transition: transform 180ms ease, box-shadow 180ms ease, border-color 180ms ease;
}
.hp-customer-media-card::before {
  content: "";
  position: absolute;
  z-index: 4;
  top: 0;
  bottom: 0;
  left: -45%;
  width: 28%;
  background: linear-gradient(90deg, transparent, rgba(255,255,255,0.2), transparent);
  transform: skewX(-16deg);
  transition: left 520ms ease;
  pointer-events: none;
}
@media (hover: hover) {
  .hp-customer-media-card.is-populated:hover {
    transform: translateY(-4px);
    box-shadow: var(--hp-media-card-hover-shadow);
  }
  .hp-customer-media-card.is-populated:hover::before { left: 118%; }
}
.hp-customer-media-header {
  position: relative;
  z-index: 2;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  gap: 12px;
  align-items: center;
  min-height: 72px;
  padding: 13px 15px;
  color: var(--hp-media-card-accent-contrast);
  background: var(--hp-media-card-header-bg);
}
.hp-customer-media-icon,
.hp-customer-media-empty-icon {
  display: grid;
  place-items: center;
  width: 42px;
  height: 42px;
  flex: 0 0 auto;
  color: var(--hp-media-icon-fg);
  background: var(--hp-media-icon-bg);
  border: 1px solid rgba(255,255,255,0.24);
  border-radius: 999px;
}
.hp-customer-media-icon-svg { display: block; width: 20px; height: 20px; }
.hp-customer-media-heading { min-width: 0; display: grid; gap: 2px; }
.hp-customer-media-heading strong { font-size: 14px; line-height: 1.25; }
.hp-customer-media-heading > span {
  overflow: hidden;
  font-size: 11px;
  line-height: 1.35;
  opacity: 0.86;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.hp-customer-media-spark { display: grid; place-items: center; opacity: 0.68; }
.hp-customer-media-spark .hp-customer-media-icon-svg { width: 18px; height: 18px; }
.hp-customer-media-viewport {
  position: relative;
  display: grid;
  min-height: 0;
  overflow: hidden;
  background: #0e0820;
}
.hp-customer-media-card-showcase .hp-customer-media-viewport { aspect-ratio: 5 / 7; }
.hp-customer-media-card-short .hp-customer-media-viewport { aspect-ratio: 9 / 16; }
.hp-customer-media-card-showcase.is-empty .hp-customer-media-viewport,
.hp-customer-media-card-short.is-empty .hp-customer-media-viewport { aspect-ratio: 4 / 3; }
.hp-customer-media-card[data-media-provider="youtube"] { width: min(100%, 520px); }
.hp-customer-media-card[data-media-provider="youtube"] .hp-customer-media-viewport { aspect-ratio: 16 / 9; }
.hp-customer-media-card[data-media-provider="facebook"] .hp-customer-media-viewport { aspect-ratio: 4 / 5; }
.hp-customer-media-card-portrait .hp-customer-media-viewport { aspect-ratio: 4 / 5; }
.hp-customer-media-player,
.hp-customer-media-player .ss-tiktok-embed-frame,
.hp-customer-media-player .ss-customer-video-frame { width: 100%; height: 100%; min-height: 0; }
.hp-customer-media-footer {
  position: relative;
  z-index: 3;
  margin: 0;
  padding: 10px 12px;
  color: var(--hp-media-card-fg);
  background: var(--hp-media-card-footer-bg);
  border-top: 1px solid var(--hp-media-card-border);
}
.hp-customer-video-footer {
  display: grid;
  gap: 10px;
  padding-bottom: 16px;
}
.hp-customer-video-footer::after {
  content: "";
  position: absolute;
  right: 0;
  bottom: 0;
  left: 0;
  height: 6px;
  background: var(--hp-media-card-header-bg);
}
.hp-customer-video-caption {
  display: block;
  padding: 2px 8px 0;
  font-size: 13px;
  font-weight: 700;
  line-height: 1.45;
  text-align: center;
  overflow-wrap: anywhere;
}
.hp-customer-media-action {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  gap: 10px;
  align-items: center;
  width: 100%;
  min-height: 46px;
  padding: 11px 15px;
  color: var(--hp-media-cta-fg);
  background: var(--hp-media-cta-bg);
  border-radius: 999px;
  font-size: 13px;
  font-weight: 800;
  text-align: center;
  text-decoration: none;
}
.hp-customer-media-action .hp-customer-media-icon-svg { width: 17px; height: 17px; }
.hp-customer-media-action:focus-visible {
  outline: 3px solid color-mix(in srgb, var(--hp-primary) 65%, white);
  outline-offset: 3px;
}
.hp-customer-media-empty {
  display: grid;
  place-items: center;
  align-content: center;
  gap: 14px;
  width: 100%;
  height: 100%;
  min-height: 220px;
  padding: 30px;
  color: var(--hp-media-placeholder-fg);
  background:
    radial-gradient(circle at 50% 34%, color-mix(in srgb, var(--hp-primary) 20%, transparent), transparent 42%),
    var(--hp-media-placeholder-bg);
  border: 1px dashed color-mix(in srgb, var(--hp-primary) 35%, transparent);
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-align: center;
  text-transform: uppercase;
}
.hp-customer-media-empty-icon {
  width: 54px;
  height: 54px;
  color: var(--hp-card-accent);
  background: color-mix(in srgb, var(--hp-bg-elevated) 74%, transparent);
  border-color: color-mix(in srgb, var(--hp-primary) 28%, transparent);
}

/* Shared TikTok player: the player stays in-page, begins muted when visible,
   and exposes a host-page sound toggle without covering TikTok's own controls. */
.ss-tiktok-embed {
  position: relative;
  overflow: hidden;
  isolation: isolate;
}
.ss-customer-video-embed {
  position: relative;
  overflow: hidden;
  isolation: isolate;
}
.ss-tiktok-embed-fallback {
  display: grid;
  place-items: center;
}
.ss-customer-video-embed-fallback {
  display: grid;
  place-items: center;
}
.ss-tiktok-embed-coming-soon,
.hp-media-coming-soon {
  position: relative;
  z-index: 1;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 36px;
  padding: 8px 14px;
  border: 1px solid rgba(255,255,255,0.34);
  border-radius: 999px;
  background: rgba(11, 9, 24, 0.7);
  color: #fff;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
}
.ss-tiktok-embed-frame {
  display: block;
  width: 100%;
  height: 100%;
  min-height: inherit;
  border: 0;
  background: #0e0820;
}
.ss-customer-video-frame {
  display: block;
  width: 100%;
  height: 100%;
  min-height: inherit;
  border: 0;
  background: #0e0820;
}
.ss-tiktok-embed .ss-tiktok-sound-toggle {
  position: absolute;
  z-index: 4;
  top: 14px;
  right: 14px;
  border: 1px solid rgba(255,255,255,0.34);
  border-radius: 999px;
  padding: 8px 11px;
  background: rgba(11, 9, 24, 0.7);
  color: #fff;
  font: inherit;
  font-size: 12px;
  font-weight: 700;
  line-height: 1;
  cursor: pointer;
  backdrop-filter: blur(8px);
}
.ss-tiktok-embed .ss-tiktok-sound-toggle:hover,
.ss-tiktok-embed .ss-tiktok-sound-toggle:focus-visible {
  background: rgba(11, 9, 24, 0.92);
  outline: 2px solid #25f4ee;
  outline-offset: 2px;
}
.bwb-featured-video.ss-tiktok-embed::before {
  display: none;
}

/* ============================================================
   About
   ============================================================ */
.hp-about-grid {
  display: grid;
  grid-template-columns: 1.05fr 0.95fr;
  gap: 28px;
  align-items: stretch;
  max-width: 1080px;
  margin: 0 auto;
}
@media (max-width: 980px) {
  .hp-about-grid { grid-template-columns: 1fr; }
}

.hp-about-copy {
  background: var(--hp-bg-elevated);
  border: 1px solid var(--border);
  border-radius: var(--hp-radius-card);
  padding: 36px;
  position: relative;
  overflow: hidden;
}
.hp-about-copy::before {
  content: "";
  position: absolute;
  top: -80px;
  right: -80px;
  width: 220px;
  height: 220px;
  border-radius: 50%;
  background: radial-gradient(circle, color-mix(in oklab, var(--hp-primary) 14%, transparent), transparent 70%);
  pointer-events: none;
}
.hp-about-copy > * { position: relative; z-index: 1; }

.hp-about-body {
  display: flex;
  flex-direction: column;
  gap: 18px;
}
.hp-about-body p {
  margin: 0;
  font-size: 15px;
  line-height: 1.7;
  color: var(--fg-muted);
}

.hp-about-portrait-card {
  align-self: start;
  width: min(100%, 440px);
  justify-self: center;
}

.hp-about-portrait-image {
  display: block;
  width: 100%;
  height: 100%;
  border: 0;
  border-radius: 0;
  object-fit: cover;
  /*
   * A portrait source often leaves a large amount of empty headroom above the
   * person.  The card is deliberately clipped, so a small subject-forward
   * zoom keeps that dead space out of the first visible row without exposing
   * a second image edge.  This applies to every rep rather than baking a
   * special crop into one customer's image.
   */
  object-position: var(--hp-about-portrait-focus-x, 50%) var(--hp-about-portrait-focus-y, 20%);
  transform: scale(var(--hp-about-portrait-zoom, 1.18));
  /* Keep a comfortable amount of headroom after the subject-forward zoom. */
  transform-origin: var(--hp-about-portrait-focus-x, 50%) var(--hp-about-portrait-focus-y, 20%);
}

.hp-about-shorts-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 18px;
  max-width: 1080px;
  margin: 28px auto 0;
  align-items: start;
}

.hp-about-short-card {
  width: min(100%, 348px);
  justify-self: center;
  min-height: 0;
}

.hp-about-short-card .ss-tiktok-embed-frame,
.hp-about-short-card .ss-customer-video-frame {
  display: block;
  width: 100%;
  height: 100%;
  border: 0;
  background: #0e0820;
}

.hp-about-media-caption {
  font-size: 13px;
  line-height: 1.55;
  color: var(--hp-media-card-fg);
  text-align: center;
}

@media (max-width: 1100px) {
  .hp-about-shorts-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 700px) {
  .hp-about-shorts-grid {
    grid-template-columns: 1fr;
    margin-top: 20px;
  }

  .hp-about-short-card {
    width: min(100%, 348px);
  }
}

/* ============================================================
   Signup
   ============================================================ */
.hp-signup {
  background: var(--hp-bg);
  padding: var(--hp-section-pad) 0;
}
.hp-signup-card {
  max-width: 880px;
  margin: 0 auto;
  background: var(--hp-bg-elevated);
  border: 1px solid var(--border);
  border-radius: var(--hp-radius-card);
  padding: 56px 56px 48px;
  display: flex;
  flex-direction: column;
  gap: 32px;
  position: relative;
  overflow: hidden;
  color: var(--hp-card-fg);
}
.hp-signup-card::before {
  content: "";
  position: absolute;
  top: -120px;
  right: -120px;
  width: 320px;
  height: 320px;
  border-radius: 50%;
  background: radial-gradient(circle, color-mix(in oklab, var(--hp-primary) 18%, transparent), transparent 70%);
  pointer-events: none;
}
.hp-signup-card::after {
  content: "";
  position: absolute;
  bottom: -140px;
  left: -100px;
  width: 280px;
  height: 280px;
  border-radius: 50%;
  background: radial-gradient(circle, color-mix(in oklab, var(--hp-accent) 14%, transparent), transparent 70%);
  pointer-events: none;
}
.hp-signup-card-body {
  position: relative;
  z-index: 2;
  text-align: center;
}
.hp-signup-eyebrow {
  font-family: ui-monospace, "SF Mono", Menlo, monospace;
  font-size: 11px;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--hp-card-accent);
  margin-bottom: 12px;
}
.hp-signup-title {
  font-family: var(--hp-display-font);
  font-size: clamp(30px, 3.6vw, 42px);
  font-weight: 700;
  letter-spacing: var(--hp-heading-tracking);
  line-height: 1.14;
  margin: 0 0 8px;
  padding-block: 0.03em 0.09em;
  color: var(--hp-card-fg);
  overflow: visible;
}
.hp-signup-sub {
  font-size: 15px;
  line-height: 1.6;
  color: var(--hp-card-muted);
  margin: 0;
  max-width: 520px;
  margin-left: auto;
  margin-right: auto;
}
.hp-signup-form {
  position: relative;
  z-index: 2;
  display: flex;
  flex-direction: column;
  gap: 24px;
  text-align: left;
}
.hp-signup-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
}
@media (max-width: 600px) {
  .hp-signup-row { grid-template-columns: 1fr; }
}
.hp-signup-field {
  display: flex;
  flex-direction: column;
  gap: 8px;
  min-width: 0;
}
.hp-signup-label {
  font-size: 11px;
  letter-spacing: 0.12em;
  font-weight: 600;
  text-transform: uppercase;
  color: var(--hp-card-muted);
  display: inline-flex;
  align-items: baseline;
  gap: 8px;
}
.hp-signup-label-aux {
  font-size: 10px;
  letter-spacing: 0.04em;
  text-transform: none;
  font-weight: 400;
  color: var(--hp-card-muted);
  opacity: 0.7;
}
.hp-signup-input {
  background: var(--hp-field-bg);
  border: 1px solid var(--border);
  color: var(--hp-field-fg);
  padding: 14px 16px;
  border-radius: 10px;
  font-family: inherit;
  font-size: 15px;
  outline: none;
  transition: border-color var(--dur-fast) var(--ease), box-shadow var(--dur-fast) var(--ease);
  width: 100%;
}
.hp-signup-input:focus {
  border-color: var(--hp-primary);
  box-shadow: 0 0 0 3px color-mix(in oklab, var(--hp-primary) 14%, transparent);
}
.hp-signup-input::placeholder { color: var(--hp-card-muted); opacity: 0.55; }
.hp-signup-consent-box {
  display: grid;
  gap: 12px;
  border: 1px solid var(--border);
  border-radius: 20px;
  background: var(--hp-form-panel-bg);
  color: var(--hp-form-panel-fg);
  padding: 18px 20px;
}
.hp-signup-preferences {
  display: grid;
  gap: 16px;
  border: 1px solid var(--border);
  border-radius: 20px;
  background: color-mix(in oklab, var(--hp-form-panel-bg) 72%, transparent);
  padding: 18px 20px;
}
.hp-signup-preferences-heading {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  color: var(--hp-form-panel-fg);
  font-size: 14px;
}
.hp-signup-preferences-heading span {
  border-radius: 999px;
  background: var(--hp-field-bg);
  color: var(--hp-card-muted);
  font-size: 11px;
  font-weight: 700;
  padding: 4px 9px;
}
.hp-signup-preferences-copy,
.hp-signup-field-note {
  margin: -7px 0 0;
  color: var(--hp-card-muted);
  font-size: 12px;
  line-height: 1.45;
}
.hp-signup-field-note {
  margin: 0;
}
.hp-signup-check {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  font-size: 14px;
  line-height: 1.5;
  color: var(--hp-form-panel-fg);
}
.hp-signup-check input {
  margin-top: 3px;
  flex-shrink: 0;
}
.hp-unsubscribe-toggle {
  position: relative;
  align-items: center;
  min-height: 56px;
  padding: 12px 14px;
  border: 1px solid var(--border);
  border-radius: 16px;
  background: var(--hp-bg-elevated);
  cursor: pointer;
}
.hp-unsubscribe-toggle input {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  margin: 0;
  opacity: 0;
  pointer-events: none;
}
.hp-toggle-control {
  width: 46px;
  height: 28px;
  border-radius: 999px;
  background: var(--border);
  position: relative;
  flex-shrink: 0;
  transition: background var(--dur-fast) var(--ease);
}
.hp-toggle-control::after {
  content: "";
  position: absolute;
  top: 4px;
  left: 4px;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  background: white;
  box-shadow: 0 2px 8px rgba(14, 8, 32, 0.18);
  transition: transform var(--dur-fast) var(--ease);
}
.hp-unsubscribe-toggle input:checked + .hp-toggle-control {
  background: var(--hp-primary);
}
.hp-unsubscribe-toggle input:checked + .hp-toggle-control::after {
  transform: translateX(18px);
}
.hp-unsubscribe-toggle:focus-within {
  outline: 2px solid color-mix(in oklab, var(--hp-primary) 28%, white);
  outline-offset: 3px;
}

.hp-signup-actions {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 14px;
}
.hp-signup-submit {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  padding: 14px 32px;
  background: var(--hp-card-accent);
  color: var(--hp-action-fg);
  border-radius: 999px;
  font-size: 14px;
  font-weight: 600;
  letter-spacing: 0.02em;
  cursor: pointer;
  border: 0;
  transition: background var(--dur-fast) var(--ease), transform var(--dur-fast) var(--ease);
  white-space: nowrap;
}
.hp-signup-submit:hover {
  background: var(--hp-accent);
  transform: translateY(-1px);
}
.hp-signup-submit:disabled {
  cursor: wait;
  opacity: 0.72;
  transform: none;
}
.hp-signup-submit-arrow {
  display: inline-block;
  transition: transform var(--dur-fast) var(--ease);
}
.hp-signup-submit:hover .hp-signup-submit-arrow {
  transform: translateX(3px);
}
.hp-signup-consent {
  font-size: 11px;
  line-height: 1.55;
  color: var(--hp-card-muted);
  margin: 0;
  text-align: center;
  max-width: 540px;
}
.hp-signup-consent a {
  color: var(--hp-primary);
  text-decoration: underline;
  text-underline-offset: 2px;
}
.hp-signup-consent a:hover { color: var(--hp-accent); }
.hp-signup-status {
  margin: 0;
  font-size: 13px;
  line-height: 1.5;
  text-align: center;
}
.hp-signup-status.success {
  color: #13653d;
}
.hp-signup-status.error {
  color: #9c1c3d;
}

@media (max-width: 600px) {
  .hp-signup-card { padding: 36px 24px 32px; }
}

/* ============================================================
   Footer
   ============================================================ */
.hp-footer {
  background: #0E0820;
  color: rgba(255,255,255,0.7);
  padding: 64px 24px 32px;
}
.hp-footer-inner {
  max-width: 1280px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: minmax(260px, 1.4fr) repeat(2, minmax(120px, 1fr));
  gap: 48px;
  margin-bottom: 48px;
}
@media (max-width: 800px) { .hp-footer-inner { grid-template-columns: 1fr 1fr; } }
.hp-footer-brand {
  font-family: var(--hp-display-font);
  font-size: 22px;
  font-weight: 600;
  letter-spacing: -0.01em;
  color: white;
  margin-bottom: 14px;
}
.hp-footer-tag {
  font-size: 13px;
  line-height: 1.55;
  margin-bottom: 24px;
}
.hp-footer-team {
  margin: -12px 0 20px;
  color: rgba(255,255,255,0.86);
  font-size: 13px;
  font-weight: 600;
  line-height: 1.45;
}
.hp-footer-socials {
  display: flex;
  gap: 8px;
}
.hp-footer-social {
  width: 44px; height: 44px;
  border-radius: 50%;
  border: 1px solid rgba(255,255,255,0.15);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: white;
  text-decoration: none;
  transition: all var(--dur-fast) var(--ease);
}
.hp-footer-social-logo {
  width: 20px;
  height: 20px;
  display: block;
  fill: currentColor;
}
.hp-footer-social-logo-stroke {
  fill: none;
  stroke: currentColor;
  stroke-width: 1.9;
  stroke-linecap: round;
  stroke-linejoin: round;
}
.hp-footer-social-fallback {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.04em;
}
.hp-footer-social:hover { background: white; color: #0E0820; }
.hp-footer-col ul {
  list-style: none;
  padding: 0;
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.hp-footer-col a {
  display: inline-flex;
  align-items: center;
  min-height: 26px;
  color: rgba(255,255,255,0.65);
  font-size: 13px;
  line-height: 1.35;
  text-decoration: none;
  transition: color var(--dur-fast) var(--ease);
}
.hp-footer-col a:hover { color: white; }
.hp-footer-coming-soon {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  min-height: 26px;
  color: rgba(255,255,255,0.42);
  font-size: 13px;
  line-height: 1.35;
}
.hp-footer-coming-soon span {
  border-radius: 999px;
  border: 1px solid rgba(255,255,255,0.16);
  padding: 2px 7px;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: rgba(255,255,255,0.66);
}
.hp-footer-bottom {
  max-width: 1280px;
  margin: 0 auto;
  border-top: 1px solid rgba(255,255,255,0.1);
  padding-top: 24px;
  font-size: 11px;
  line-height: 1.6;
  color: rgba(255,255,255,0.45);
}
.hp-footer-bottom p { margin-bottom: 8px; }
.hp-footer-bottom .legal-row {
  display: flex;
  justify-content: space-between;
  margin-bottom: 16px;
  flex-wrap: wrap;
  gap: 12px;
}
.hp-footer-bottom a {
  display: inline-flex;
  align-items: center;
  min-height: 24px;
  color: rgba(255,255,255,0.6);
}
.hp-footer-bottom a.ss-powered-by {
  text-decoration: underline;
  text-underline-offset: 2px;
}
.hp-footer-bottom a.ss-powered-by:hover { color: white; }
.hp-footer-bottom a.ss-powered-by:focus-visible {
  outline: 2px solid currentColor;
  outline-offset: 3px;
}

/* ============================================================
   Buttons (homepage variants — built on top of design system)
   ============================================================ */
.hp-btn-primary {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  padding: 14px 26px;
  border-radius: 999px;
  background: var(--hp-card-accent);
  color: var(--hp-action-fg);
  font-size: 14px;
  font-weight: 600;
  letter-spacing: 0.02em;
  border: 0;
  cursor: pointer;
  position: relative;
  overflow: hidden;
  transition: transform var(--dur-fast) var(--ease);
  text-decoration: none;
  white-space: nowrap;
}
.hp-btn-primary:hover { transform: translateY(-1px); }
.hp-btn-primary.solid {
  background: var(--hp-card-accent);
  color: var(--hp-action-fg);
}
.hp-btn-primary.solid-light {
  background: var(--fg);
  color: white;
}
.hp-btn-outline {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  padding: 12px 22px;
  border-radius: 999px;
  background: transparent;
  color: white;
  border: 1px solid rgba(255,255,255,0.4);
  font-size: 14px;
  font-weight: 500;
  cursor: pointer;
  text-decoration: none;
  transition: all var(--dur-fast) var(--ease);
  white-space: nowrap;
}
.hp-btn-outline:hover { background: white; color: var(--fg); border-color: white; }
.hp-watch-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #FF3B5C;
  box-shadow: 0 0 0 0 rgba(255, 59, 92, 0.65);
  animation: hp-watch-dot-pulse 1.6s var(--ease) infinite;
}
.hp-btn-outline:hover .hp-watch-dot {
  box-shadow: 0 0 0 0 rgba(255, 59, 92, 0);
}
@keyframes hp-watch-dot-pulse {
  0%   { box-shadow: 0 0 0 0 rgba(255, 59, 92, 0.65); }
  70%  { box-shadow: 0 0 0 8px rgba(255, 59, 92, 0); }
  100% { box-shadow: 0 0 0 0 rgba(255, 59, 92, 0); }
}

/* B6 Sparkle Burst — reuse from components.css but add animation hook */
.hp-btn-sparkle .spark {
  position: absolute;
  width: 4px; height: 4px;
  background: white;
  border-radius: 50%;
  pointer-events: none;
  opacity: 0;
}
.hp-btn-sparkle:hover .spark {
  animation: hp-sparkle-burst 700ms var(--ease) forwards;
}
.hp-btn-sparkle:hover .spark:nth-child(1) { animation-delay: 0ms; --tx: -22px; --ty: -16px; }
.hp-btn-sparkle:hover .spark:nth-child(2) { animation-delay: 80ms; --tx: 24px; --ty: -18px; }
.hp-btn-sparkle:hover .spark:nth-child(3) { animation-delay: 160ms; --tx: -16px; --ty: 18px; }
.hp-btn-sparkle:hover .spark:nth-child(4) { animation-delay: 240ms; --tx: 22px; --ty: 16px; }
@keyframes hp-sparkle-burst {
  0% { opacity: 0; transform: translate(0, 0) scale(0); }
  20% { opacity: 1; transform: translate(0, 0) scale(1); }
  100% { opacity: 0; transform: translate(var(--tx), var(--ty)) scale(0.4); }
}

/* ============================================================
   FLAMBOYANCE — sparkle FX layer
   ============================================================ */
.hp-fx-layer {
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 70;
  overflow: hidden;
}
.hp-fx-sparkle {
  position: absolute;
  width: 6px; height: 6px;
  background: white;
  border-radius: 50%;
  box-shadow: 0 0 8px white, 0 0 16px var(--hp-primary);
  opacity: 0;
  animation: hp-fx-twinkle 4s linear infinite;
}

.hp-fx-layer-glow::before,
.hp-fx-layer-glow::after {
  content: "";
  position: absolute;
  width: min(68vw, 780px);
  aspect-ratio: 1;
  border-radius: 999px;
  background:
    radial-gradient(circle, color-mix(in oklab, var(--hp-primary) 44%, transparent) 0%, color-mix(in oklab, var(--hp-primary) 18%, transparent) 42%, transparent 72%);
  filter: blur(18px);
  opacity: 0.72;
  animation: hp-fx-soft-glow 9s ease-in-out infinite;
}

.hp-fx-layer-glow::before {
  left: -10vw;
  top: 14vh;
}

.hp-fx-layer-glow::after {
  right: -16vw;
  bottom: -18vh;
  background:
    radial-gradient(circle, color-mix(in oklab, var(--hp-accent) 38%, transparent) 0%, color-mix(in oklab, var(--hp-accent) 14%, transparent) 44%, transparent 74%);
  animation-delay: -3s;
}

@keyframes hp-fx-twinkle {
  0% { opacity: 0; transform: translateY(20px) scale(0.4); }
  20% { opacity: 0.9; }
  80% { opacity: 0.9; }
  100% { opacity: 0; transform: translateY(-100vh) scale(0.6); }
}

@keyframes hp-fx-soft-glow {
  0%, 100% { opacity: 0.48; transform: translate3d(0, 0, 0) scale(0.9); }
  50% { opacity: 0.86; transform: translate3d(5vw, -4vh, 0) scale(1.08); }
}

/*
 * Hero motion is the authoritative visual choice for the hero. A rep can
 * still choose a sparkly page treatment, but Soft glow must remain a clearly
 * distinct, sparkle-free hero rather than competing with a fixed texture or
 * the confetti layer from the previously selected skin.
 */
body.hero-motion-soft-glow.tex-sparkle::before {
  display: none;
}

body.hero-motion-soft-glow.fx-confetti .hp-hero::before {
  display: none;
}

/* Body-level FX modes */
body.fx-confetti .hp-section,
body.fx-confetti .hp-hero {
  position: relative;
}
body.fx-confetti .hp-section::before,
body.fx-confetti .hp-hero::before {
  content: "";
  position: absolute;
  inset: 0;
  background-image:
    radial-gradient(circle at 10% 10%, var(--hp-primary) 1.5px, transparent 2px),
    radial-gradient(circle at 30% 70%, var(--hp-accent) 1.5px, transparent 2px),
    radial-gradient(circle at 70% 30%, var(--hp-primary) 1.5px, transparent 2px),
    radial-gradient(circle at 90% 80%, var(--hp-accent) 1.5px, transparent 2px),
    radial-gradient(circle at 50% 50%, white 1px, transparent 1.5px);
  background-size: 200px 200px, 240px 240px, 180px 180px, 220px 220px, 150px 150px;
  opacity: 0.18;
  pointer-events: none;
  z-index: 0;
}

body.fx-aurora .hp-hero-media {
  background:
    linear-gradient(180deg, rgba(14,8,32,0.1) 0%, rgba(14,8,32,0.55) 65%, rgba(14,8,32,0.85) 100%),
    conic-gradient(from 200deg at 50% 50%, var(--hp-primary), var(--hp-accent), #FF6BD6, var(--hp-primary));
  filter: saturate(1.2);
  animation: hp-aurora 14s linear infinite;
}
@keyframes hp-aurora {
  0% { background-position: 0% 0%; filter: saturate(1.2) hue-rotate(0deg); }
  100% { background-position: 100% 100%; filter: saturate(1.2) hue-rotate(360deg); }
}

body.fx-holographic .hp-trade-card,
body.fx-holographic .hp-event-card,
body.fx-holographic .hp-wibp-card {
  background: linear-gradient(135deg,
    rgba(255,255,255,0.92),
    rgba(255,200,255,0.85),
    rgba(200,220,255,0.85),
    rgba(255,255,200,0.85)
  );
  background-size: 200% 200%;
  animation: hp-holo 6s ease infinite;
  border-color: rgba(255,255,255,0.6);
}
@keyframes hp-holo {
  0%, 100% { background-position: 0% 50%; }
  50% { background-position: 100% 50%; }
}

/* Glass cards */
body.surface-glass .hp-trade-card,
body.surface-glass .hp-event-card,
body.surface-glass .hp-wibp-card {
  background: rgba(255,255,255,0.5);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  border-color: rgba(255,255,255,0.7);
}

/* Bouncy buttons */
body.btn-bouncy .hp-btn-primary:hover,
body.btn-bouncy .hp-btn-outline:hover {
  animation: hp-btn-bounce 600ms cubic-bezier(.36, 0, .04, 1.2);
}
@keyframes hp-btn-bounce {
  0%, 100% { transform: translateY(-1px); }
  30% { transform: translateY(-4px) rotate(-1deg); }
  60% { transform: translateY(-1px) rotate(0.5deg); }
}

/* Wiggle hover */
body.btn-wiggle .hp-btn-primary:hover {
  animation: hp-btn-wiggle 500ms ease-in-out;
}
@keyframes hp-btn-wiggle {
  0%, 100% { transform: rotate(0deg); }
  25% { transform: rotate(-2deg); }
  75% { transform: rotate(2deg); }
}

/* Pulsing CTA */
body.cta-pulse .hp-btn-primary:not(.outline) {
  animation: hp-cta-pulse 2s ease-in-out infinite;
}
@keyframes hp-cta-pulse {
  0%, 100% { box-shadow: 0 0 0 0 rgba(210,9,227,0.4); }
  50% { box-shadow: 0 0 0 14px rgba(210,9,227,0); }
}

/* Holographic Unicorn cards */
body.holo-unicorn .hp-trade-card:has(.hp-trade-tier.unicorn) {
  background: linear-gradient(135deg, #FFE6FF, #E6E6FF, #FFFFE6);
  background-size: 200% 200%;
  animation: hp-holo 4s ease infinite;
}

/* Texture overlays */
body.tex-grain::before {
  content: "";
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 75;
  background-image: url("data:image/svg+xml;base64,");
  opacity: 0.5;
  mix-blend-mode: overlay;
}

body.tex-sparkle::before {
  content: "";
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 75;
  background-image:
    radial-gradient(circle at 15% 25%, white 0.5px, transparent 1.5px),
    radial-gradient(circle at 65% 85%, white 0.5px, transparent 1.5px),
    radial-gradient(circle at 85% 15%, white 0.5px, transparent 1.5px),
    radial-gradient(circle at 25% 75%, white 0.5px, transparent 1.5px);
  background-size: 80px 80px, 100px 100px, 110px 110px, 90px 90px;
  opacity: 0.4;
  mix-blend-mode: screen;
  animation: hp-tex-sparkle 30s linear infinite;
}
@keyframes hp-tex-sparkle {
  0% { background-position: 0 0, 0 0, 0 0, 0 0; }
  100% { background-position: 80px 80px, -100px 100px, 110px -110px, -90px -90px; }
}

/* Gradient mesh bg */
body.bg-mesh {
  background:
    radial-gradient(ellipse at 0% 0%, color-mix(in oklch, var(--hp-primary) 30%, var(--hp-bg)), transparent 50%),
    radial-gradient(ellipse at 100% 100%, color-mix(in oklch, var(--hp-accent) 30%, var(--hp-bg)), transparent 50%),
    var(--hp-bg);
}

