/* Halloween Pumpkin and Witch semantic contrast contract */
body.surface-midnight-glass {
  --hp-card-fg: #fff7ed;
  --hp-card-muted: #d6c8bb;
  --hp-card-accent: #ff9a3d;
  --hp-final-fg: #fff7ed;
  --hp-final-muted: #e3b7ff;
  --hp-final-icon-fg: #2a1f40;
}

body.btn-pumpkin-glow {
  --hp-action-fg: #2a1f40;
}

body.surface-pumpkin-cat-glass {
  --hp-final-fg: #fff7ed;
  --hp-final-muted: #dacbc1;
  --hp-final-icon-fg: #200d02;
  --hp-card-fg: #fff7ed;
  --hp-card-muted: #dacbc1;
  --hp-card-accent: #ffb776;
  --hp-form-panel-bg: #1b1511;
  --hp-form-panel-fg: #fff7ed;
  --hp-field-bg: #100c09;
  --hp-field-fg: #fff7ed;
}
/* One accepted-reveal target per list and ticker; decorative sparkle stays silent. */
.hp-lineup-order-count { font-size: .78em; opacity: .78; font-variant-numeric: tabular-nums; white-space: nowrap; }
[data-lineup-token], [data-lineup-surface] { position: relative; }
[data-lineup-flare="true"] { animation: hp-lineup-reveal-glow 950ms ease-out both; }
.hp-lineup-sparkle { display: none; }
[data-lineup-token][data-lineup-flare="true"] .hp-lineup-sparkle { display: block; position: absolute; inset-inline-end: .3em; top: -.25em; pointer-events: none; font-size: 1.05em; color: currentColor; animation: hp-lineup-reveal-sparkle 950ms ease-out both; }
@keyframes hp-lineup-reveal-glow { 0%, 100% { box-shadow: none; } 25% { box-shadow: 0 0 0 2px color-mix(in srgb, currentColor 28%, transparent), 0 0 18px color-mix(in srgb, currentColor 22%, transparent); } }
@keyframes hp-lineup-reveal-sparkle { 0%, 100% { opacity: 0; } 25% { opacity: .9; } 75% { opacity: .2; transform: translateY(-3px); } }
@media (prefers-reduced-motion: reduce) { [data-lineup-flare="true"] { animation: none; background-color: color-mix(in srgb, currentColor 12%, transparent); } [data-lineup-token][data-lineup-flare="true"] .hp-lineup-sparkle { display: none; animation: none; } }

/* Empty lineup: one useful row, shared across all current and future skins. */
.hp-lineup-idle-inner { max-width:1280px; margin:0 auto; padding:0 24px; }
.hp-lineup-idle-prompt {
  display:flex; align-items:center; gap:10px; min-height:48px;
  padding:10px 0; box-sizing:border-box; width:fit-content; max-width:100%;
  font-size:13px; line-height:1.5; font-weight:600;
  color:var(--hp-preview-fg, var(--fg)); text-decoration:none; overflow-wrap:anywhere;
}
.hp-lineup-idle-prompt svg { flex:none; opacity:.8; }
a.hp-lineup-idle-prompt:hover { text-decoration:underline; text-underline-offset:3px; }
a.hp-lineup-idle-prompt:focus-visible { outline:2px solid currentColor; outline-offset:2px; border-radius:4px; }
@media (max-width:640px) { .hp-lineup-idle-inner { padding:0 16px; } }
#events { scroll-margin-top:180px; }

