/* ---------- Two-column layout ---------- */
.tp-board {
  padding: 16px 0 80px;
}
.tp-board-inner {
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 24px;
  display: grid;
  grid-template-columns: 320px 1fr;
  gap: 32px;
  align-items: start;
}
.tp-board-inner.no-lrq {
  grid-template-columns: 1fr;
}
.tp-board-inner > * { min-width: 0; }
@media (max-width: 900px) {
  .tp-board-inner {
    grid-template-columns: 1fr;
    gap: 18px;
  }
}

/* ---------- LRQ rail (sticky, side column) ---------- */
.tp-lrq-rail {
  position: sticky;
  top: 156px;
  max-height: calc(100vh - 172px);
  background: var(--hp-bg-elevated);
  border: 1px solid var(--border);
  border-radius: var(--hp-radius-card);
  padding: 18px;
  display: flex;
  flex-direction: column;
  gap: 14px;
  overflow: hidden;
}
.tp-lrq-head {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 11px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  font-weight: 700;
  color: var(--fg);
}
.tp-lrq-head .live-dot {
  width: 8px; height: 8px;
  border-radius: 50%;
  background: #FF3366;
  box-shadow: 0 0 0 4px rgba(255,51,102,0.2);
  animation: hp-pulse 1.6s var(--ease) infinite;
}
.tp-lrq-head .ofs-dot {
  width: 8px; height: 8px;
  border-radius: 50%;
  background: var(--fg-muted);
}
.tp-lrq-meta {
  font-size: 12px;
  color: var(--fg-muted);
  line-height: 1.5;
}
.tp-lrq-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
  flex: 1 1 auto;
  min-height: 0;
  overflow-y: auto;
  padding-right: 6px;
  scrollbar-width: thin;
  scrollbar-color: color-mix(in oklab, var(--hp-primary) 45%, var(--border)) transparent;
}
.tp-lrq-list::-webkit-scrollbar {
  width: 8px;
}
.tp-lrq-list::-webkit-scrollbar-track {
  background: transparent;
}
.tp-lrq-list::-webkit-scrollbar-thumb {
  background: color-mix(in oklab, var(--hp-primary) 45%, var(--border));
  border-radius: 999px;
}
.tp-lrq-row {
  display: grid;
  grid-template-columns: 26px 1fr auto;
  align-items: center;
  gap: 10px;
  padding: 10px 12px;
  background: var(--hp-bg);
  border: 1px solid var(--border);
  border-radius: 12px;
}
.tp-lrq-row.now {
  background: linear-gradient(95deg,
    color-mix(in oklab, var(--hp-primary) 8%, var(--hp-bg)),
    color-mix(in oklab, var(--hp-accent) 8%, var(--hp-bg))
  );
  border-color: color-mix(in oklab, var(--hp-primary) 30%, transparent);
}
.tp-lrq-row .pos {
  width: 26px; height: 26px;
  border-radius: 50%;
  background: var(--hp-bg-elevated);
  border: 1px solid var(--border);
  display: inline-flex; align-items: center; justify-content: center;
  font-size: 12px; font-weight: 700;
  color: var(--fg-muted);
}
.tp-lrq-row.now .pos {
  background: var(--hp-primary);
  color: white;
  border-color: transparent;
}
.tp-lrq-row .name {
  font-size: 13px;
  font-weight: 600;
  color: var(--fg);
}
.tp-lrq-row .label {
  font-size: 9px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--fg-muted);
  font-weight: 600;
}
.tp-lrq-empty {
  text-align: center;
  padding: 18px 8px;
  font-size: 13px;
  color: var(--fg);
  font-weight: 600;
}
.tp-lrq-empty span { letter-spacing: 0.1em; }
.tp-lrq-stats {
  display: flex;
  justify-content: space-between;
  padding-top: 12px;
  border-top: 1px dashed var(--border);
  font-size: 11px;
  color: var(--fg-muted);
}
.tp-lrq-stats strong {
  color: var(--fg);
  font-size: 14px;
  font-weight: 700;
  display: block;
}

/* ---------- Mobile drawer banner ---------- */
.tp-drawer {
  display: none;
  position: sticky;
  top: 0;
  z-index: 30;
  background: var(--hp-bg-elevated);
  border-bottom: 1px solid var(--border);
}
@media (max-width: 900px) {
  .tp-drawer {
    display: block;
    top: var(--hp-mobile-sticky-drawer-top);
