}

.tp-drawer-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 16px;
  cursor: pointer;
  user-select: none;
}
.tp-drawer-bar-left {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.06em;
}
.tp-drawer-bar .live-dot {
  width: 8px; height: 8px;
  border-radius: 50%;
  background: #FF3366;
