  margin-bottom: 2px;
}
.tp-drawer-count {
  font-size: 11px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--fg-muted);
  font-weight: 600;
}
.tp-drawer-toggle {
  flex-shrink: 0;
  border: 1px solid var(--border);
  background: var(--hp-bg-elevated);
  color: var(--hp-primary);
  border-radius: 999px;
  padding: 8px 12px;
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
}
.tp-drawer-toggle:hover {
  border-color: var(--hp-primary);
  background: color-mix(in oklab, var(--hp-primary) 8%, var(--hp-bg-elevated));
}
@media (max-width: 560px) {
  .tp-drawer-tools {
    flex-direction: column;
    align-items: stretch;
  }
  .tp-drawer-toggle {
    width: 100%;
  }
}

/* ---------- Filter pill bar ---------- */
.tp-filters {
  /* Keep search above the inventory without covering dancers while browsing. */
  position: static;
  background: color-mix(in oklab, var(--hp-bg) 92%, transparent);
  backdrop-filter: blur(8px);
  border: 1px solid var(--border);
  border-radius: var(--hp-radius-card);
  box-shadow: 0 16px 34px rgba(42, 31, 64, 0.08);
  padding: 14px 0;
