  padding: 0 24px;
}
.tp-filters.style-pills .tp-filters-row {
  display: flex;
  gap: 10px;
  overflow-x: auto;
  padding: 0;
  scrollbar-width: none;
}
.tp-filters-row-primary {
  margin-bottom: 0;
}
.tp-filters-row-collections {
  margin-bottom: 0;
}
.tp-filters.style-pills .tp-filters-row::-webkit-scrollbar { display: none; }
.tp-filter-pill {
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 8px 14px;
  border-radius: 999px;
  background: var(--hp-bg-elevated);
  border: 1px solid var(--border);
  font-size: 13px;
  font-weight: 500;
  color: var(--fg);
