  flex-shrink: 0;
}
.tp-filter-sort {
  margin-left: auto;
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 8px 14px;
  background: transparent;
  border: 1px dashed var(--border);
  border-radius: 999px;
  font-size: 12px;
  color: var(--fg-muted);
  font-weight: 600;
  letter-spacing: 0.04em;
  cursor: pointer;
}
.tp-filter-panel {
  margin: 0 24px;
  border: 1px solid var(--border);
