  align-items: center;
  gap: 6px;
  padding: 9px 14px;
  background: var(--hp-bg-elevated);
  border: 1px solid var(--border);
  border-radius: 8px;
  font-size: 13px;
  font-weight: 500;
  color: var(--fg);
  cursor: pointer;
}
.tp-filter-drop .chev {
  font-size: 10px;
  color: var(--fg-muted);
}

/* Sidebar style */
.tp-filters.style-sidebar {
  position: static;
  background: transparent;
  backdrop-filter: none;
  border: 0;
  padding: 0;
  margin: 0;
}

/* ---------- Trade grid ---------- */
.tp-grid-wrap { padding: 0 24px; }
.tp-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
  gap: 20px;
}
.tp-board-pagination {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 16px;
  flex-wrap: wrap;
  padding: 24px 0 0;
}
.tp-load-more {
  border: 1px solid var(--hp-primary);
  background: var(--hp-primary);
  color: white;
  border-radius: 999px;
  padding: 11px 18px;
  font-size: 13px;
  font-weight: 700;
  cursor: pointer;
  box-shadow: 0 12px 28px -20px color-mix(in oklab, var(--hp-primary) 60%, black);
  transition: transform var(--dur-fast) var(--ease), box-shadow var(--dur-fast) var(--ease);
}
.tp-load-more:hover {
  transform: translateY(-1px);
  box-shadow: 0 16px 32px -22px color-mix(in oklab, var(--hp-primary) 70%, black);
}
.tp-grid.aspect-square .tp-card-photo { aspect-ratio: 1 / 1; }
.tp-grid.aspect-portrait .tp-card-photo { aspect-ratio: 4 / 5; }

/* ---------- Trade card ---------- */
.tp-card {
  background: var(--hp-bg-elevated);
  color: var(--hp-card-fg, var(--fg));
  border: 1px solid var(--border);
  border-radius: var(--hp-radius-card);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  cursor: pointer;
  transition: transform var(--dur-base) var(--ease),
              box-shadow var(--dur-base) var(--ease),
              border-color var(--dur-base) var(--ease);
  position: relative;
}
.tp-card:hover {
  transform: translateY(-3px);
  box-shadow: 0 14px 38px -22px rgba(72, 13, 223, 0.4);
  border-color: color-mix(in oklab, var(--hp-primary) 25%, var(--border));
}

.tp-card-photo {
  background: linear-gradient(135deg, var(--bg-deep), var(--hp-bg-elevated));
  position: relative;
  overflow: hidden;
}
.tp-card-photo.has-photo::after {
  opacity: 0;
}
.tp-card-photo::after {
  /* placeholder shimmer / mock jewelry photo treatment */
  content: "";
  position: absolute;
  inset: 0;
  background:
    radial-gradient(circle at 30% 30%, rgba(255,255,255,0.4), transparent 50%),
    radial-gradient(circle at 70% 70%, color-mix(in oklab, var(--hp-primary) 20%, transparent), transparent 60%);
}
.tp-card-photo-img,
.tp-card-expand-photo-img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}
.tp-grid .tp-card-photo.has-photo,
.tp-card-expand-photo.has-photo {
  aspect-ratio: 3 / 4;
  background: #a8aaa9;
}
.tp-card-expand-photo.has-photo {
  align-self: start;
  width: 100%;
  height: auto;
}
.tp-card-photo.has-photo .tp-card-photo-img,
.tp-card-expand-photo.has-photo .tp-card-expand-photo-img {
  object-fit: contain;
  object-position: center;
  padding: 0;
  background: transparent;
}
.tp-card-photo .photo-glyph {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  color: var(--hp-primary);
  z-index: 1;
}
.tp-card-photo .photo-glyph .tp-sparkle-mark {
  width: 64px;
  height: 64px;
}
/* Tier badge top-left */
.tp-card-tier {
  position: absolute;
  top: 10px;
  left: 10px;
  z-index: 2;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 5px 10px;
  border-radius: 999px;
  background: rgba(255,255,255,0.92);
  backdrop-filter: blur(6px);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: #2a1f40;
  border: 1px solid rgba(0,0,0,0.06);
}
.tp-card-tier.diamond {
  background: linear-gradient(95deg, #DCEEFF, #B0E0FF);
  color: #1E3A5F;
}
.tp-card-tier.unicorn {
  background: linear-gradient(95deg, var(--hp-primary), var(--hp-accent));
  color: white;
  border: 0;
  box-shadow: 0 6px 18px -6px var(--hp-accent);
}
.tp-card-tier .pip {
  width: 6px; height: 6px;
  border-radius: 50%;
  background: currentColor;
  opacity: 0.7;
}
.tp-card-tier.unicorn .pip {
  background: white;
  box-shadow: 0 0 6px white;
}

/* Unicorn card glow border */
.tp-card.unicorn {
  border-color: transparent;
  background:
    linear-gradient(var(--hp-bg-elevated), var(--hp-bg-elevated)) padding-box,
    linear-gradient(135deg, var(--hp-primary), var(--hp-accent), #FFD700, var(--hp-primary)) border-box;
  border: 2px solid transparent;
  background-size: 100% 100%, 300% 300%;
  animation: tp-unicorn-shimmer 6s linear infinite;
}
@keyframes tp-unicorn-shimmer {
  0% { background-position: 0% 0%, 0% 0%; }
  100% { background-position: 0% 0%, 300% 300%; }
}
.tp-card.unicorn::before {
  content: "";
  position: absolute;
  inset: -2px;
  border-radius: inherit;
  background: linear-gradient(135deg,
    color-mix(in oklab, var(--hp-primary) 40%, transparent),
    color-mix(in oklab, var(--hp-accent) 40%, transparent));
  filter: blur(20px);
  opacity: 0.35;
  z-index: -1;
  pointer-events: none;
}
.tp-card.diamond {
  border-color: color-mix(in oklab, #5C8FBE 40%, var(--border));
  box-shadow: 0 0 0 1px color-mix(in oklab, #5C8FBE 30%, transparent) inset;
}

/* Card body */
.tp-card-body {
  padding: 14px 16px 16px;
  display: flex;
  flex-direction: column;
  gap: 6px;
  flex: 1;
}
.tp-card-name {
  font-family: var(--hp-display-font);
  font-size: 17px;
  font-weight: var(--hp-heading-weight);
  color: var(--hp-card-fg, var(--fg));
  letter-spacing: var(--hp-heading-tracking);
  line-height: 1.2;
  margin: 0;
}
body.tradepage :is(.tp-card-name, .tp-card-expand-name) {
  color: var(--hp-card-fg, var(--fg));
}
.tp-card-meta {
  display: block;
  font-size: 13px;
  color: var(--hp-card-muted, var(--fg-muted));
  letter-spacing: 0.01em;
  line-height: 1.45;
}
.tp-card-collection {
  text-transform: uppercase;
  letter-spacing: 0.12em;
  font-weight: 600;
  font-size: 11px;
  color: var(--hp-card-fg, var(--fg));
}
.tp-card-material {
  font-size: 12px;
  color: var(--hp-card-muted, var(--fg-muted));
  line-height: 1.4;
  min-height: 1.4em;
}
.tp-card-quantity {
  width: fit-content;
  margin-top: 2px;
  border-radius: 999px;
  background: color-mix(in srgb, var(--primary) 10%, transparent);
  color: var(--hp-card-fg, var(--fg));
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.04em;
  line-height: 1.2;
  padding: 5px 9px;
}
.tp-card-action {
  align-self: flex-start;
  min-height: 40px;
  margin-top: auto;
  padding: 8px 12px;
  border: 1px solid var(--border);
  border-radius: 9px;
  background: transparent;
  color: var(--hp-card-fg, var(--fg));
  font: inherit;
  font-size: 12px;
  font-weight: 700;
  cursor: pointer;
}
.tp-card-action:hover { border-color: var(--hp-primary); }
.tp-card-action:focus-visible { outline: 3px solid var(--hp-primary); outline-offset: 2px; }

/* ---------- Expanded card overlay ---------- */
.tp-card-expand-mask {
  position: fixed;
  inset: 0;
  background: transparent;
  z-index: 80;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
}
.tp-card-expand-mask::before {
  content: "";
  position: absolute;
  inset: 0;
  background: rgba(14, 8, 32, 0.62);
  backdrop-filter: blur(4px);
  animation: tp-fade-in 0.4s ease-in-out;
}
@keyframes tp-fade-in {
  from { opacity: 0; }
  to { opacity: 1; }
}
.tp-card-expand {
  width: min(900px, 100%);
  max-height: 90vh;
  background: var(--hp-bg-elevated, #f2ebfa);
  opacity: 1;
  border-radius: 20px;
  overflow: auto;
  display: grid;
  grid-template-columns: 1fr 1fr;
  position: relative;
  z-index: 1;
  animation: tp-pop-in 0.4s ease-in-out;
}
@keyframes tp-pop-in {
  from { transform: scale(0.98) translateY(8px); }
  to { transform: none; }
}
@media (max-width: 700px) {
  .tp-card-expand { grid-template-columns: 1fr; }
  .tp-filter-grid { grid-template-columns: 1fr; }
  .tp-filters {
    box-shadow: 0 12px 28px rgba(14, 8, 32, 0.08);
  }
  .tp-mobile-filter-cue {
    display: flex;
    align-items: center;
    min-height: 24px;
  }
  .tp-filters-topline {
    flex-direction: column;
    align-items: stretch;
  }
  .tp-filter-actions {
    justify-content: space-between;
  }
  .tp-board-search-row {
    grid-template-columns: 1fr;
  }
  .tp-filter-primary-grid {
    grid-template-columns: 1fr;
    gap: 10px;
    padding: 0 24px;
  }
}
.tp-card-expand:has(.tp-card-expand-photo:not(.has-photo)) {
  grid-template-columns: 168px minmax(0, 1fr);
}
.tp-card-expand-photo {
  aspect-ratio: 4 / 5;
  background: linear-gradient(135deg, var(--bg-deep), var(--hp-bg));
  position: relative;
  overflow: hidden;
}
.tp-card-expand-photo:not(.has-photo) {
  aspect-ratio: auto;
  min-height: 100%;
  background:
    radial-gradient(circle at 50% 42%, color-mix(in oklab, var(--hp-primary) 16%, white), transparent 58%),
    linear-gradient(180deg, color-mix(in oklab, var(--hp-primary) 7%, white), var(--hp-bg));
}
.tp-card-expand-photo:not(.has-photo) .photo-glyph .tp-sparkle-mark {
  width: 36px;
  height: 36px;
  opacity: 0.7;
}
@media (max-width: 700px) {
  .tp-card-expand:has(.tp-card-expand-photo:not(.has-photo)) {
    grid-template-columns: 1fr;
  }
  .tp-card-expand-photo:not(.has-photo) {
    min-height: 0;
    height: 84px;
  }
}
.tp-card-expand-photo .photo-glyph {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  color: var(--hp-primary);
}
.tp-card-expand-photo .photo-glyph .tp-sparkle-mark {
  width: 88px;
  height: 88px;
}
.tp-card-expand-body {
  padding: 36px 32px;
  display: flex;
  flex-direction: column;
  gap: 16px;
  overflow: auto;
}
.tp-card-expand {
  color: var(--hp-card-fg, var(--fg));
}
.tp-card-expand-tier {
  align-self: flex-start;
}
.tp-card-expand-name {
  font-family: var(--hp-display-font);
  font-size: 32px;
  font-weight: var(--hp-heading-weight);
  letter-spacing: var(--hp-heading-tracking);
  margin: 0;
  line-height: 1.05;
}
.tp-card-expand-collection {
  font-size: 12px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--hp-primary);
  font-weight: 600;
}
.tp-card-expand-desc {
  font-size: 14px;
  line-height: 1.6;
  color: var(--hp-card-muted, var(--fg-muted));
}
.tp-card-expand-specs {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px 16px;
  padding: 16px;
  background: var(--hp-bg);
  border-radius: 12px;
  font-size: 12px;
}
.tp-card-expand-specs dt {
  color: var(--hp-card-muted, var(--fg-muted));
  letter-spacing: 0.08em;
  text-transform: uppercase;
  font-weight: 600;
  font-size: 11px;
  margin-bottom: 2px;
}
.tp-card-expand-specs dd {
  margin: 0;
  color: var(--hp-card-fg, var(--fg));
  font-weight: 500;
}
.tp-card-expand-note {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  margin: 0;
  padding: 12px 14px;
  border-radius: 12px;
  background: color-mix(in oklab, var(--hp-primary) 10%, var(--hp-bg-elevated));
  color: var(--hp-card-fg, var(--fg));
  font-size: 13px;
  line-height: 1.45;
}
.tp-card-expand-note p {
  margin: 0;
}
.tp-card-expand-note .tp-sparkle-mark {
  width: 16px;
  height: 16px;
  margin-top: 2px;
  color: var(--hp-primary);
}
.tp-card-expand-rule {
  margin: 0;
  color: var(--hp-card-muted, var(--fg-muted));
  font-size: 13px;
  line-height: 1.5;
}
.tp-sparkle-mark {
  width: 1em;
  height: 1em;
  display: block;
  flex: none;
}
.tp-card-expand-cta .tp-sparkle-mark {
  width: 16px;
  height: 16px;
}
.tp-empty-glyph .tp-sparkle-mark {
  width: 48px;
  height: 48px;
}
.tp-card-expand-cta {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 16px 28px;
  background: var(--hp-card-accent);
  color: var(--hp-action-fg);
  border: 0;
  border-radius: 14px;
  font-size: 15px;
  font-weight: 600;
  letter-spacing: 0.02em;
  cursor: pointer;
  margin-top: 4px;
  transition: transform var(--dur-fast) var(--ease), box-shadow var(--dur-fast) var(--ease);
}
.tp-card-expand-cta:hover {
  transform: translateY(-1px);
  box-shadow: 0 12px 28px -10px var(--hp-accent);
}
.tp-card-close {
  position: absolute;
  top: 14px; right: 14px;
  width: 36px; height: 36px;
  border-radius: 50%;
  background: rgba(255,255,255,0.92);
  border: 1px solid var(--border);
  display: grid;
  place-items: center;
  cursor: pointer;
  z-index: 5;
  font-size: 18px;
  color: #2a1f40;
}

/* ---------- Bottom sheet (request form / success) ---------- */
.tp-sheet-mask {
  position: fixed;
  inset: 0;
  background: transparent;
  z-index: 90;
  display: flex;
  align-items: flex-end;
  justify-content: center;
}
.tp-sheet-mask::before {
  content: "";
  position: absolute;
  inset: 0;
  background: rgba(14, 8, 32, 0.62);
  backdrop-filter: blur(4px);
  animation: tp-fade-in 0.4s ease-in-out;
}
.tp-sheet {
  width: min(560px, 100%);
  background: var(--hp-bg-elevated, #f2ebfa);
  opacity: 1;
  color: var(--hp-form-panel-fg, var(--hp-card-fg, var(--fg)));
  border-radius: 20px 20px 0 0;
  padding: 28px 28px 36px;
  position: relative;
  z-index: 1;
  animation: tp-slide-up 0.4s ease-in-out;
  max-height: 90vh;
  overflow: auto;
}
@keyframes tp-slide-up {
  from { transform: translateY(100%); }
  to { transform: translateY(0); }
}
.tp-sheet-handle {
  width: 40px; height: 4px;
  background: var(--border);
  border-radius: 999px;
  margin: 0 auto 18px;
}
.tp-sheet-eyebrow {
  font-family: ui-monospace, "SF Mono", Menlo, monospace;
  font-size: 11px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--hp-primary);
  margin-bottom: 8px;
}
.tp-sheet-title {
  font-family: var(--hp-display-font);
  font-size: 26px;
  font-weight: var(--hp-heading-weight);
  letter-spacing: var(--hp-heading-tracking);
  margin: 0 0 4px;
  line-height: 1.1;
  color: var(--hp-form-panel-fg, var(--hp-card-fg, var(--fg)));
}
body.tradepage .tp-sheet-title {
  color: var(--hp-form-panel-fg, var(--fg));
}
.tp-sheet-piece {
  font-size: 13px;
  color: var(--hp-card-muted, var(--fg-muted));
  margin-bottom: 22px;
}
.tp-sheet-piece strong { color: var(--hp-form-panel-fg, var(--fg)); font-weight: 600; }
.tp-sheet-helper {
  margin: -12px 0 6px;
  font-size: 13px;
  color: var(--hp-card-muted, var(--fg-muted));
  line-height: 1.55;
}
.tp-sheet-form {
  display: flex;
  flex-direction: column;
  gap: 14px;
}
.tp-sheet-field label {
  display: block;
  font-size: 12px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--hp-card-muted, var(--fg-muted));
  font-weight: 600;
  margin-bottom: 6px;
}
.tp-sheet-field input,
.tp-sheet-field textarea,
.tp-sheet-field select {
  width: 100%;
  padding: 12px 14px;
  border: 1px solid var(--border);
  border-radius: 10px;
  background: var(--hp-field-bg, var(--hp-bg));
  font-family: inherit;
  font-size: 14px;
  color: var(--hp-field-fg, var(--fg));
  resize: vertical;
}
.tp-sheet-field textarea { min-height: 88px; }
.tp-field-hint {
  margin: 6px 0 0;
  font-size: 12px;
  font-weight: 500;
  letter-spacing: 0;
  text-transform: none;
  line-height: 1.4;
  color: var(--hp-card-muted, var(--fg-muted));
}
.tp-sheet-field input:focus,
.tp-sheet-field textarea:focus,
.tp-sheet-field select:focus {
  outline: 0;
  border-color: var(--hp-primary);
  box-shadow: 0 0 0 3px color-mix(in oklab, var(--hp-primary) 16%, transparent);
}
.tp-sheet-match-target,
.tp-sheet-screening,
.tp-sheet-mismatch,
.tp-sheet-receipt {
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 11px 13px;
  background: var(--hp-bg);
  color: var(--hp-form-panel-fg, var(--fg));
  font-size: 13px;
  line-height: 1.5;
}
.tp-sheet-match-target strong,
.tp-sheet-match-target span {
  display: block;
}
.tp-sheet-match-target {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}
.tp-sheet-match-target > div { min-width: 0; }
.tp-sheet-match-target > div + div {
  border-left: 1px solid var(--border);
  padding-left: 12px;
}
.tp-sheet-match-target strong { font-size: 12px; text-transform: uppercase; letter-spacing: .08em; }
.tp-sheet-match-target span { margin-top: 4px; font-weight: 700; overflow-wrap: anywhere; }
.tp-sheet-match-target small { display: block; margin-top: 3px; color: var(--hp-card-muted, var(--fg-muted)); font-size: 12px; }
.tp-sheet-screening { margin: 0; }
.tp-sheet-mismatch { border-color: color-mix(in oklab, #a43b00 38%, var(--border)); }
.tp-sheet-mismatch p { margin: 4px 0 0; }
.tp-sheet-alternatives { display: grid; gap: 6px; margin-top: 10px; }
.tp-sheet-alternatives span { font-size: 12px; font-weight: 650; }
.tp-sheet-alternatives button,
.tp-sheet-receipt button,
.tp-sheet-receipt a {
  width: 100%;
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 9px 10px;
  background: var(--hp-bg-elevated);
  color: var(--hp-form-panel-fg, var(--fg));
  font: inherit;
  text-align: left;
  cursor: pointer;
}
.tp-sheet-receipt { display: grid; gap: 8px; text-align: left; margin-bottom: 16px; }
.tp-sheet-receipt p { margin: 0; }
.tp-sheet-receipt input { min-width: 0; width: 100%; padding: 8px; border: 1px solid var(--border); border-radius: 8px; }
.tp-sheet-upload {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  gap: 12px;
  align-items: center;
  border: 1px dashed color-mix(in oklab, var(--hp-primary) 34%, var(--border));
  border-radius: 12px;
  background: color-mix(in oklab, var(--hp-primary) 6%, var(--hp-bg));
  padding: 12px;
}
.tp-sheet-upload input[type="file"] {
  width: min(180px, 38vw);
  max-width: 100%;
  color: var(--hp-card-muted, var(--fg-muted));
  font-size: 12px;
}
.tp-sheet-upload strong,
.tp-sheet-upload span {
  display: block;
  line-height: 1.35;
}
.tp-sheet-upload strong {
  color: var(--hp-form-panel-fg, var(--fg));
  font-size: 13px;
  font-weight: 650;
  overflow-wrap: anywhere;
}
.tp-sheet-upload span {
  color: var(--hp-card-muted, var(--fg-muted));
  font-size: 12px;
  margin-top: 2px;
}
.tp-sheet-upload-review {
  display: grid;
  grid-template-columns: 88px minmax(0, 1fr);
  gap: 12px;
  align-items: start;
  margin-top: 10px;
  padding: 10px;
  border: 1px solid var(--border);
  border-radius: 12px;
  background: var(--hp-bg);
  color: var(--hp-form-panel-fg, var(--fg));
}
.tp-sheet-upload-review img,
.tp-sheet-upload-fallback {
  width: 88px;
  height: 88px;
  object-fit: cover;
  border-radius: 8px;
  background: var(--hp-bg-elevated);
  border: 1px solid var(--border);
}
.tp-sheet-upload-fallback {
  display: grid;
  place-items: center;
  font-size: 12px;
  color: var(--hp-card-muted, var(--fg-muted));
}
.tp-sheet-upload-details {
  display: grid;
  gap: 4px;
  min-width: 0;
  font-size: 12px;
  line-height: 1.4;
}
.tp-sheet-upload-details strong { overflow-wrap: anywhere; }
.tp-sheet-upload-details > span { color: var(--hp-card-muted, var(--fg-muted)); }
.tp-sheet-upload-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 5px;
}
.tp-sheet-upload-actions button {
  min-height: 36px;
  padding: 7px 10px;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: var(--hp-bg-elevated);
  color: var(--hp-form-panel-fg, var(--fg));
  font: inherit;
  font-weight: 650;
  cursor: pointer;
}
.tp-sheet-upload-actions button:focus-visible { outline: 3px solid var(--hp-primary); outline-offset: 2px; }
.tp-sheet-upload-actions button:disabled { opacity: .55; cursor: not-allowed; }
@media (max-width: 420px) {
  .tp-sheet-match-target { grid-template-columns: 1fr; }
  .tp-sheet-match-target > div + div { border-left: 0; border-top: 1px solid var(--border); padding-left: 0; padding-top: 10px; }
}
.tp-sheet-error {
  border: 1px solid color-mix(in oklab, #b42318 28%, var(--border));
  background: color-mix(in oklab, #b42318 10%, white);
  color: #7a271a;
  border-radius: 10px;
  padding: 12px 14px;
  font-size: 12px;
  line-height: 1.5;
}
.tp-sheet-submit {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 14px 24px;
  background: var(--hp-card-accent);
  color: var(--hp-action-fg);
  border: 0;
  border-radius: 12px;
  font-size: 14px;
  font-weight: 600;
  letter-spacing: 0.02em;
  cursor: pointer;
  margin-top: 4px;
}
.tp-sheet-submit:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}
.tp-sheet-close {
  position: absolute;
  top: 14px; right: 14px;
  width: 32px; height: 32px;
  border-radius: 50%;
  background: transparent;
  border: 1px solid var(--border);
  display: grid;
  place-items: center;
  cursor: pointer;
  font-size: 16px;
  color: var(--hp-card-muted, var(--fg-muted));
}

/* Success state */
.tp-sheet.success { text-align: center; padding-top: 48px; padding-bottom: 48px; }
.tp-sheet-success-icon {
  width: 64px; height: 64px;
  border-radius: 50%;
  background: var(--hp-card-accent);
  margin: 0 auto 18px;
  display: grid; place-items: center;
  color: var(--hp-action-fg, white);
  font-size: 28px;
}
.tp-sheet-success-title {
  font-family: var(--hp-display-font);
  font-size: 26px;
  margin: 0 0 8px;
  letter-spacing: var(--hp-heading-tracking);
}
.tp-sheet-success-body {
  font-size: 13px;
  color: var(--hp-card-muted, var(--fg-muted));
  line-height: 1.6;
  max-width: 44ch;
  margin: 0 auto 22px;
}
.tp-sheet-success-legal {
  font-size: 12px;
  color: var(--hp-card-muted, var(--fg-muted));
  background: var(--hp-bg);
  border: 1px dashed var(--border);
  border-radius: 10px;
  padding: 12px;
  line-height: 1.5;
  text-align: left;
}

/* ---------- Empty state ---------- */
body.tradepage.dance-floor-empty .hp-ticker-row.reverse {
  display: none;
}
body.tradepage .hp-ticker-row:not(.reverse):not(:has(.hp-ticker-item)) {
  display: none;
}
body.tradepage.dance-floor-empty .hp-ticker:not(:has(.hp-ticker-row:not(.reverse) .hp-ticker-item)) {
  display: none;
}
.tp-empty {
  text-align: center;
  padding: 48px 24px;
  border: 1px solid color-mix(in oklab, var(--hp-primary) 22%, var(--border));
  border-radius: var(--hp-radius-card);
  background:
    radial-gradient(circle at 50% 0%, color-mix(in oklab, var(--hp-primary) 14%, transparent), transparent 58%),
    var(--hp-bg-elevated);
}
.tp-empty-glyph {
  display: flex;
  justify-content: center;
  color: var(--hp-primary);
  margin-bottom: 12px;
}
.tp-empty-title {
  font-family: var(--hp-display-font);
  font-size: 28px;
  margin: 0 0 8px;
  letter-spacing: var(--hp-heading-tracking);
}
.tp-empty-sub {
  font-size: 14px;
  color: var(--fg-muted);
  max-width: 44ch;
  margin: 0 auto 18px;
  line-height: 1.55;
}
.tp-empty-next {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  padding: 10px 18px;
  border-radius: 999px;
  background: var(--hp-bg);
  border: 1px solid var(--border);
  font-size: 12px;
  color: var(--fg);
  font-weight: 600;
  letter-spacing: 0.04em;
}
.tp-empty-next .live-dot {
  width: 6px; height: 6px;
  border-radius: 50%;
  background: var(--hp-primary);
}
.tp-empty-reset {
  align-self: center;
  border: 1px solid var(--hp-primary);
  background: white;
  color: var(--hp-primary);
  border-radius: 999px;
  padding: 10px 16px;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
}

/* ---------- Brand separation note ---------- */
.tp-legal {
  max-width: 1280px;
  margin: 56px auto 0;
  padding: 24px;
  text-align: center;
  font-size: 11px;
  color: var(--fg-muted);
  border-top: 1px dashed var(--border);
  line-height: 1.6;
}
.tp-legal strong { color: var(--fg); font-weight: 600; }

@media (pointer: coarse) {
  .tp-drawer-bar,
  .tp-drawer-toggle,
  .tp-filter-link,
  .tp-filter-toggle,
  .tp-filter-pill,
  .tp-filter-sort,
  .tp-filter-chip,
  .tp-filter-drop,
  .tp-board-search input,
  .tp-board-sort select,
  .tp-card,
  .tp-card-expand-cta,
  .tp-sheet-submit,
  .tp-empty-reset,
  .tp-load-more {
    min-height: 44px;
    touch-action: manipulation;
  }

  .tp-card-close,
  .tp-sheet-close {
    min-width: 44px;
    min-height: 44px;
    touch-action: manipulation;
  }
}

@media (prefers-reduced-motion: reduce) {
  .tp-card,
  .tp-drawer-chev,
  .tp-drawer-body,
  .tp-filter-pill,
  .tp-card-expand-cta {
    transition: none !important;
  }

  .tp-lrq-head .live-dot,
  .tp-drawer-bar .live-dot,
  .tp-card.unicorn,
  .tp-card-expand-mask,
  .tp-card-expand-mask::before,
  .tp-card-expand,
  .tp-sheet-mask,
  .tp-sheet-mask::before,
  .tp-sheet {
    animation: none !important;
  }

  .tp-card:hover,
  .tp-card-expand-cta:hover {
    transform: none !important;
  }
}

