  body.mile-high-fizz-trade .tp-hero {
    padding: 56px 0 28px;
  }

  body.mile-high-fizz-trade .tp-hero-sub {
    font-size: 13px;
    letter-spacing: 0.02em;
    text-transform: none;
  }

  body.mile-high-fizz-trade .tp-filters,
  body.mile-high-fizz-trade .tp-card {
    border-radius: 22px;
  }

  body.mile-high-fizz-trade .tp-board-inner {
    padding: 0 16px;
  }
}

body.bling-kitchen-trade {
  --bk-ink: #20172b;
  --bk-plum: #6f2da8;
  --bk-violet: #9b5de5;
  background: linear-gradient(180deg, #fff9f1 0%, #f8eef8 52%, #fff 100%);
}

.bk-trade-shell {
  width: min(1180px, calc(100% - 32px));
  margin: 0 auto;
  padding: 28px 0 64px;
}

body.bling-kitchen-trade .hp-sticky-stack,
body.bling-kitchen-trade .tp-hero,
body.bling-kitchen-trade .tp-filters,
body.bling-kitchen-trade .tp-card,
body.bling-kitchen-trade .tp-sheet,
body.bling-kitchen-trade .hp-footer {
  border-radius: 8px;
  border-color: rgba(32, 23, 43, 0.13);
  background: rgba(255, 255, 255, 0.94);
  box-shadow: 0 18px 45px rgba(58, 29, 82, 0.13);
}

body.bling-kitchen-trade .tp-hero-title,
body.bling-kitchen-trade .hp-footer-brand {
  font-family: "Playfair Display", Georgia, serif;
  color: var(--bk-ink);
}

body.bling-kitchen-trade .tp-hero-eyebrow,
body.bling-kitchen-trade .tp-meta-pill,
body.bling-kitchen-trade .tp-card-collection {
  color: var(--bk-plum);
}

body.bling-kitchen-trade {
  --bk-muted: #6d5f73;
  --bk-sage: #5f7461;
  --bk-gold: #b5843f;
  background:
    linear-gradient(180deg, #fff8ee 0%, #f7eef5 48%, #fdfaf4 100%);
}

body.bling-kitchen-trade .tp-hero,
body.bling-kitchen-trade .tp-filters,
body.bling-kitchen-trade .tp-card,
body.bling-kitchen-trade .tp-sheet {
  background: rgba(255, 255, 255, 0.95);
  border-color: rgba(95, 42, 131, 0.14);
}

body.bling-kitchen-trade .tp-hero-title {
  color: var(--bk-ink);
}

body.bling-kitchen-trade .tp-hero-copy,
body.bling-kitchen-trade .tp-card-meta,
body.bling-kitchen-trade .tp-card-description,
body.bling-kitchen-trade .tp-sheet p {
  color: var(--bk-muted);
}

body.bling-kitchen-trade .tp-card-expand-cta,
body.bling-kitchen-trade .tp-request-submit {
  border-radius: 999px;
  background: linear-gradient(135deg, #5f7461, #5f2a83);
  color: #fff8ee;
}

body.bling-kitchen-trade .hp-footer {
  background: #2b1a33;
  color: rgba(255, 248, 238, 0.78);
  box-shadow: none;
}

body.bling-kitchen-trade .hp-footer-brand,
body.bling-kitchen-trade .hp-footer a {
  color: #fff8ee;
}

body.bling-kitchen-trade .hp-footer-tag,
body.bling-kitchen-trade .hp-footer-bottom,
body.bling-kitchen-trade .hp-footer-bottom p {
  color: rgba(255, 248, 238, 0.78);
}

/* Emerald Garden trade-board continuation */
body.bg-emerald-garden .tp-hero {
  background:
    linear-gradient(180deg, rgba(3, 44, 34, 0.06) 0%, rgba(3, 44, 34, 0.36) 62%, rgba(3, 44, 34, 0.78) 100%),
    linear-gradient(135deg, #dce8dc 0%, #7fa58c 30%, #236c55 58%, #063b2e 100%);
}

body.bg-emerald-garden .tp-board {
  background:
    radial-gradient(ellipse at 8% 10%, rgba(202, 218, 196, 0.42), transparent 22rem),
    radial-gradient(ellipse at 92% 90%, rgba(229, 211, 179, 0.3), transparent 22rem),
    linear-gradient(135deg, #f8f7f0, #ffffff 52%, #e5eee2);
}

body.bg-emerald-garden .tp-filters,
body.bg-emerald-garden .tp-card,
body.bg-emerald-garden .tp-card-expand,
body.bg-emerald-garden .tp-sheet,
body.bg-emerald-garden .tp-empty {
  color: #173f34;
}

body.bg-emerald-garden .tp-filter-chip {
  background: rgba(255, 255, 252, 0.94);
  border-color: rgba(229, 211, 179, 0.92);
  color: #064e3b;
}

body.bg-emerald-garden .tp-filter-pill.active,
body.bg-emerald-garden .tp-filter-chip.active,
body.bg-emerald-garden .tp-load-more {
  background: linear-gradient(90deg, #047857, #059669);
  border-color: #059669;
  color: #ffffff;
}

body.bg-emerald-garden .tp-filter-pill.active .count {
  background: rgba(255, 255, 255, 0.2);
  color: #ffffff;
}

body.bg-emerald-garden .tp-card-collection,
body.bg-emerald-garden .tp-card-expand-collection,
body.bg-emerald-garden .tp-sheet-eyebrow {
  color: #047857;
}

body.bg-emerald-garden .tp-card-photo,
body.bg-emerald-garden .tp-card-expand-photo {
  background:
    radial-gradient(circle at 22% 18%, rgba(255, 255, 255, 0.82), transparent 12rem),
    linear-gradient(135deg, #e8eee3, #c7d7c2 52%, #f1e5cf);
}

/* On touch-sized customer views, browse controls should scroll away with the
   site chrome instead of permanently covering dancers. Kept at the end so
   compact-phone filter rules above cannot pin them again. */
@media (max-width: 900px) {
  .tp-drawer,
  .tp-filters {
    position: static;
    top: auto;
    z-index: auto;
  }
}

/* A grid photo that fails keeps the loaded has-photo frame and the dark sparkle placeholder. */
.tp-grid .tp-card-photo.has-photo.photo-fallback {
  background: linear-gradient(135deg, var(--bg-deep), var(--hp-bg-elevated));
}
.tp-card-photo.has-photo.photo-fallback::after {
  opacity: 1;
}
.tp-card-expand-photo.has-photo.photo-fallback {
  background: linear-gradient(135deg, var(--bg-deep), var(--hp-bg-elevated));
}
.tp-card-expand-photo.has-photo.photo-fallback::after {
  content: "";
  position: absolute;
  inset: 0;
  opacity: 1;
  pointer-events: none;
  background:
    radial-gradient(circle at 30% 30%, rgba(255,255,255,0.4), transparent 50%),
    radial-gradient(circle at 70% 70%, color-mix(in oklab, var(--hp-primary) 20%, transparent), transparent 60%);
}
.tp-card-expand-photo.has-photo.photo-fallback .photo-glyph {
  z-index: 1;
  color: var(--hp-primary);
}
.tp-card-expand-photo.has-photo.photo-fallback .photo-glyph .tp-sparkle-mark {
  width: 64px;
  height: 64px;
  opacity: 1;
}

join.css:
/* ============================================================
   Join Team page — uses tokens + homepage chrome
   ============================================================ */

body.joinpage {
  background: var(--hp-bg);
  color: var(--fg);
  font-family: var(--hp-body-font);
  margin: 0;
  min-height: 100vh;
}

/* ---------- Saturation wrap (shared with homepage) ---------- */
body.joinpage .hp-saturate {
  filter: saturate(var(--hp-saturation, 1));
}

/* ============================================================
   Hero (with overlay content)
   ============================================================ */
.jp-hero {
  position: relative;
  min-height: 520px;
  display: flex;
  align-items: center;
  overflow: hidden;
  padding: 80px 0;
}
.jp-hero-media {
  position: absolute;
  inset: 0;
  background:
    linear-gradient(135deg, rgba(72, 13, 223, 0.55), rgba(210, 9, 227, 0.45)),
    radial-gradient(circle at 20% 30%, rgba(255,255,255,0.18), transparent 50%),
    linear-gradient(180deg, #2A1450 0%, #1A0F2E 100%);
  z-index: 0;
}
.jp-hero-media::before {
  content: "";
  position: absolute;
  inset: 0;
  background-image:
    radial-gradient(circle at 18% 32%, rgba(255,255,255,0.08) 0, transparent 28%),
    radial-gradient(circle at 78% 60%, rgba(255,255,255,0.06) 0, transparent 30%);
}
.jp-hero-inner {
  position: relative;
  z-index: 2;
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 24px;
  width: 100%;
  display: flex;
  justify-content: center;
}
.jp-hero-card {
  max-width: 720px;
  background: rgba(255, 255, 255, 0.08);
  backdrop-filter: blur(20px) saturate(140%);
  -webkit-backdrop-filter: blur(20px) saturate(140%);
  border: 1px solid rgba(255, 255, 255, 0.18);
  border-radius: var(--r-2xl, 24px);
  padding: 36px 40px;
  color: white;
  box-shadow: 0 30px 80px rgba(0, 0, 0, 0.35);
  margin: 0 auto;
  text-align: center;
}
.jp-hero-eyebrow {
  font-family: ui-monospace, "SF Mono", Menlo, monospace;
  font-size: 12px;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: rgba(255, 255, 255, 0.78);
  margin: 0 0 14px;
  display: inline-flex;
  align-items: center;
  gap: 10px;
  justify-content: center;
}
.jp-hero-eyebrow::before,
.jp-hero-eyebrow::after {
  content: "";
  width: 24px;
  height: 1px;
  background: rgba(255,255,255,0.6);
}
.jp-hero-title {
  font-family: var(--hp-display-font);
  font-weight: var(--hp-heading-weight, 600);
  font-size: clamp(40px, 5.5vw, 68px);
  line-height: 1.1;
  letter-spacing: -0.02em;
  margin: 0 0 12px;
  padding-block: 0.04em 0.12em;
  text-wrap: balance;
  overflow: visible;
}
.jp-hero-pitch {
  font-size: 17px;
  line-height: 1.55;
  color: rgba(255, 255, 255, 0.85);
  margin: 0 auto 26px;
  max-width: 56ch;
}
.jp-hero-localized {
  font-size: 14px;
  line-height: 1.5;
  color: rgba(255, 255, 255, 0.8);
  margin: -8px auto 22px;
  max-width: 50ch;
}
.jp-hero-ctas {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
  align-items: center;
  justify-content: center;
}
.jp-hero-compliance {
  margin: 16px auto 0;
  max-width: 58ch;
  font-size: 12px;
  line-height: 1.55;
  color: rgba(255, 255, 255, 0.72);
}
.jp-hero-compliance a {
  color: white;
  text-underline-offset: 2px;
}
.jp-hero-promo {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 13px;
  color: rgba(255,255,255,0.75);
  background: rgba(255,255,255,0.06);
  border: 1px dashed rgba(255,255,255,0.2);
  padding: 6px 12px;
  border-radius: 999px;
  margin-bottom: 14px;
  justify-content: center;
}
.jp-hero-promo .pip {
  width: 6px; height: 6px; border-radius: 50%;
  background: var(--hp-accent);
  box-shadow: 0 0 10px var(--hp-accent);
}

@media (max-width: 640px) {
  .jp-hero {
    padding: 64px 0;
  }

  .jp-hero-inner {
    width: 100vw;
    max-width: 100vw;
    margin-inline: calc(50% - 50vw);
    padding: 0 18px;
  }

  .jp-hero-card {
    box-sizing: border-box;
    width: calc(100vw - 48px);
    max-width: 340px;
    padding: 30px 20px;
  }

  .jp-hero-title {
    font-size: clamp(32px, 9.6vw, 44px);
    line-height: 1.12;
    width: 100%;
    max-width: 10ch;
    margin-inline: auto;
    overflow-wrap: anywhere;
  }

  .jp-hero-promo {
    box-sizing: border-box;
    display: flex;
    width: 100%;
    max-width: 100%;
    white-space: normal;
    overflow-wrap: anywhere;
  }

  .jp-hero-pitch {
    max-width: 24ch;
    overflow-wrap: anywhere;
  }
}

/* ============================================================
   Team grid
   ============================================================ */
.jp-section {
  padding: 80px 0;
}
.jp-container {
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 24px;
}
.jp-section-head {
  text-align: center;
  margin: 0 auto 48px;
  max-width: 720px;
}
.jp-section-eyebrow {
  font-family: ui-monospace, "SF Mono", Menlo, monospace;
  font-size: 12px;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--hp-primary);
  margin: 0 0 14px;
  display: inline-flex;
  align-items: center;
  gap: 10px;
}
.jp-section-eyebrow::before,
.jp-section-eyebrow::after {
  content: "";
  width: 24px;
  height: 1px;
  background: var(--hp-primary);
}
.jp-section-title {
  font-family: var(--hp-display-font);
  font-weight: var(--hp-heading-weight, 600);
  font-size: clamp(32px, 4vw, 48px);
  line-height: 1.12;
  letter-spacing: -0.02em;
  margin: 0 0 12px;
  padding-block: 0.03em 0.09em;
  text-wrap: balance;
  background: linear-gradient(90deg, var(--hp-primary), var(--hp-accent));
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  overflow: visible;
}
.jp-section-sub {
  font-size: 17px;
  line-height: 1.55;
  color: var(--fg-muted);
  margin: 0;
  text-wrap: pretty;
}

.jp-team-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 22px;
}
@media (max-width: 1100px) {
  .jp-team-grid { grid-template-columns: repeat(3, 1fr); }
}
@media (max-width: 800px) {
  .jp-team-grid { grid-template-columns: repeat(2, 1fr); gap: 16px; }
}
@media (max-width: 520px) {
  .jp-team-grid { grid-template-columns: 1fr; gap: 14px; }
}

.jp-team-card {
  background: var(--hp-bg-elevated);
  color: var(--hp-card-fg, var(--fg));
  border: 1px solid var(--border);
  border-radius: var(--r-xl, 18px);
  padding: 0;
  min-width: 0;
  text-align: center;
  display: flex;
  flex-direction: column;
  align-items: stretch;
  position: relative;
  overflow: hidden;
  transition: transform var(--dur-base) var(--ease), box-shadow var(--dur-base) var(--ease), border-color var(--dur-base) var(--ease);
}
.jp-team-card:hover {
  transform: translateY(-3px);
  box-shadow: 0 20px 40px color-mix(in srgb, var(--hp-primary) 12%, transparent);
  border-color: color-mix(in srgb, var(--hp-primary) 48%, transparent);
}
.jp-team-card.is-leader {
  border-color: color-mix(in srgb, var(--hp-primary) 48%, transparent);
}
.jp-team-leader-label {
  position: absolute;
  top: 14px;
  left: 12px;
  z-index: 1;
  font-family: ui-monospace, monospace;
  font-size: 10px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--hp-card-fg, var(--fg));
  background: var(--hp-bg-elevated);
  padding: 4px 10px;
  border-radius: 999px;
  border: 1px solid var(--border);
}
.jp-team-avatar {
  width: 100%;
  aspect-ratio: 8 / 7;
  border-radius: 0;
  position: relative;
  overflow: hidden;
  background: linear-gradient(135deg, color-mix(in srgb, var(--hp-primary) 18%, var(--hp-bg-elevated)), color-mix(in srgb, var(--hp-accent) 22%, var(--hp-bg-elevated)));
  margin: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--hp-card-fg, var(--fg));
  font-family: var(--hp-display-font);
  font-weight: 600;
  font-size: clamp(48px, 6vw, 80px);
  letter-spacing: -0.02em;
  border: 0;
  flex-shrink: 0;
}
.jp-team-body {
  padding: 18px 20px 20px;
  display: flex;
  flex: 1;
  flex-direction: column;
  align-items: center;
  min-width: 0;
  overflow-wrap: anywhere;
}
.jp-team-initials {
  padding: 20px;
}
.jp-team-business {
  font-size: 12px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  margin: 0 0 4px;
  color: var(--hp-card-accent, var(--hp-primary));
}
.jp-team-name {
  font-family: var(--hp-display-font);
  font-weight: 600;
  font-size: 22px;
  line-height: 1.2;
  letter-spacing: -0.01em;
  margin: 0 0 10px;
  color: var(--hp-card-fg, var(--fg));
}
.jp-team-location {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font-size: 13px;
  color: var(--hp-card-muted, var(--fg-muted));
  margin: 0 0 18px;
}
.jp-team-connect {
  margin-top: auto;
  width: 100%;
  border-top: 1px solid var(--border);
  padding-top: 16px;
}
.jp-team-connect-label {
  font-family: ui-monospace, monospace;
  font-size: 10px;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--hp-card-muted, var(--fg-muted));
  margin: 0 0 10px;
}
.jp-team-socials {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  justify-content: center;
}
.jp-team-social {
  width: 44px;
  height: 44px;
  min-width: 44px;
  min-height: 44px;
  border-radius: 50%;
  background: #fff;
  border: 1.5px solid rgba(20, 12, 34, 0.22);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: #140c22;
  text-decoration: none;
  transition: all var(--dur-fast) var(--ease);
}
.jp-team-social:hover {
  background: var(--hp-card-accent);
  color: var(--hp-action-fg);
  border-color: var(--hp-card-accent);
  transform: translateY(-2px);
}
.jp-team-social:focus-visible {
  outline: 2px solid var(--hp-primary, #480DDF);
  outline-offset: 3px;
}
.jp-team-social-logo {
  width: 20px;
  height: 20px;
  display: block;
  fill: currentColor;
}
.jp-team-social-logo-stroke {
  fill: none;
  stroke: currentColor;
  stroke-width: 1.9;
  stroke-linecap: round;
  stroke-linejoin: round;
}

/* "This is Your Spot" CTA card */
.jp-team-card.is-spot {
  background: var(--hp-bg-elevated);
  border: 1px solid var(--border);
}
.jp-team-card .jp-spot-art {
  color: var(--hp-card-accent, var(--hp-primary));
  background:
    radial-gradient(ellipse at 15% 20%, color-mix(in srgb, var(--hp-accent) 45%, transparent), transparent 45%),
    radial-gradient(ellipse at 90% 85%, color-mix(in srgb, var(--hp-primary) 45%, transparent), transparent 55%),
    var(--hp-bg-elevated);
}
.jp-spot-art::before {
  content: "";
  position: absolute;
  inset: 0;
  opacity: 0.45;
  background-image: radial-gradient(circle, currentColor 1px, transparent 2px);
  background-size: 29px 31px;
  mask-image: linear-gradient(160deg, black, transparent 55%, black);
}
.jp-spot-heart {
  width: 44%;
  height: auto;
  position: relative;
  filter: drop-shadow(0 0 12px color-mix(in srgb, var(--hp-accent) 60%, transparent));
}
.jp-spot-title {
  font-family: var(--hp-display-font);
  font-weight: 600;
  font-size: 20px;
  line-height: 1.25;
  margin: 0 0 8px;
  color: var(--hp-card-fg, var(--fg));
  text-wrap: balance;
}
.jp-spot-sub {
  font-size: 13px;
  color: var(--hp-card-muted, var(--fg-muted));
  margin: 0 0 18px;
  line-height: 1.5;
}
.jp-spot-btn {
  background: var(--hp-card-accent);
  color: var(--hp-action-fg);
  border: 0;
  padding: 12px 22px;
  border-radius: 999px;
  font-weight: 600;
  font-size: 14px;
  cursor: pointer;
  text-decoration: none;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  transition: transform var(--dur-fast) var(--ease), box-shadow var(--dur-fast) var(--ease);
  margin-top: auto;
}
.jp-spot-btn:hover {
  transform: translateY(-2px);
  box-shadow: 0 12px 28px rgba(72,13,223,0.3);
}

/* ============================================================
   Why Join — six benefit cards
   ============================================================ */
.jp-why {
  background: var(--hp-bg-elevated);
  scroll-margin-top: 220px;
}
.jp-benefits {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 22px;
}
@media (max-width: 900px) {
  .jp-benefits { grid-template-columns: repeat(2, 1fr); }
}
@media (max-width: 600px) {
  .jp-benefits { grid-template-columns: 1fr; }
}
.jp-benefit-card {
  background: white;
  border: 1px solid var(--border);
  border-radius: var(--r-xl, 18px);
  padding: 30px 26px;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  transition: transform var(--dur-base) var(--ease), box-shadow var(--dur-base) var(--ease);
}
.jp-benefit-card:hover {
  transform: translateY(-3px);
  box-shadow: 0 20px 40px rgba(72,13,223,0.08);
}
.jp-benefit-icon {
  width: 56px;
  height: 56px;
  border-radius: 16px;
  background: var(--hp-card-accent);
  display: flex;
  align-items: center;
  justify-content: center;
  color: white;
  color: var(--hp-action-fg);
  margin-bottom: 18px;
  box-shadow: 0 12px 24px rgba(72,13,223,0.2);
}
.jp-benefit-icon svg {
  width: 26px;
  height: 26px;
}
.jp-benefit-title {
  font-family: var(--hp-display-font);
  font-weight: 600;
  font-size: 20px;
  line-height: 1.25;
  letter-spacing: -0.01em;
  margin: 0 0 8px;
  color: var(--fg);
}
.jp-benefit-desc {
  font-size: 14px;
  line-height: 1.55;
  color: var(--fg-muted);
  margin: 0;
}

.jp-why--personal .jp-section-sub {
  max-width: 720px;
}
.jp-why--personal .jp-benefits {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}
.jp-why-actions {
  margin-top: 32px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-wrap: wrap;
  gap: 12px;
}
.jp-why-btn {
  min-height: 48px;
  padding: 0 22px;
  border-radius: 999px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  font-size: 14px;
  font-weight: 750;
  line-height: 1.2;
  text-decoration: none;
  transition: transform var(--dur-fast) var(--ease), box-shadow var(--dur-fast) var(--ease), border-color var(--dur-fast) var(--ease);
}
.jp-why-btn:hover {
  transform: translateY(-2px);
}
.jp-why-btn--primary {
  color: var(--hp-action-fg);
  background: var(--hp-card-accent);
  border: 1px solid transparent;
  box-shadow: 0 12px 28px rgba(72, 13, 223, 0.24);
}
.jp-why-btn--secondary {
  color: var(--fg);
  background: transparent;
  border: 1px solid var(--border);
}
.jp-why-text-links {
  display: flex;
  align-items: center;
  gap: 16px;
}
.jp-why-text-links a {
  color: var(--hp-primary);
  font-size: 14px;
  font-weight: 700;
  text-underline-offset: 4px;
}
@media (max-width: 900px) {
  .jp-why--personal .jp-benefits { grid-template-columns: 1fr; }
}
@media (max-width: 600px) {
  .jp-why-actions { align-items: stretch; flex-direction: column; }
  .jp-why-btn { width: 100%; box-sizing: border-box; }
  .jp-why-text-links { padding: 10px 4px 0; flex-direction: column; gap: 12px; text-align: center; }
}

/* ============================================================
   FAQ accordion (mirrors trade FAQ but standalone here)
   ============================================================ */
.jp-faq-wrap {
  max-width: 880px;
  margin: 0 auto;
  padding: 0 24px;
}
.jp-faq-list {
  margin-top: 8px;
}
.jp-faq-item {
  border-top: 1px solid var(--border);
  padding: 18px 0;
}
.jp-faq-item:last-child {
  border-bottom: 1px solid var(--border);
}
.jp-faq-q {
  width: 100%;
  padding: 0;
  border: 0;
  background: none;
  text-align: left;
  line-height: inherit;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 24px;
  cursor: pointer;
  font-family: var(--hp-display-font);
  font-weight: 500;
  font-size: 18px;
  letter-spacing: -0.01em;
  color: var(--fg);
  user-select: none;
}
.jp-faq-q .chev {
  font-size: 22px;
  color: var(--fg-muted);
  transition: transform var(--dur-base) var(--ease);
  flex-shrink: 0;
  line-height: 1;
}
.jp-faq-item.open .chev { transform: rotate(45deg); color: var(--hp-primary); }
.jp-faq-a {
  max-height: 0;
  overflow: hidden;
  transition: max-height var(--dur-base) var(--ease);
}
.jp-faq-item.open .jp-faq-a { max-height: 500px; }
.jp-faq-a-inner {
  padding-top: 14px;
  font-size: 15px;
  line-height: 1.6;
  color: var(--fg-muted);
}
.jp-faq-note {
  margin-top: 22px;
  border-radius: 18px;
  padding: 14px 16px;
  background: rgba(72, 13, 223, 0.06);
  border: 1px solid rgba(72, 13, 223, 0.14);
  font-size: 14px;
  line-height: 1.55;
  color: var(--fg-muted);
}
.jp-faq-note a {
  color: var(--hp-primary);
  font-weight: 600;
  text-underline-offset: 2px;
}
.jp-faq-link {
  text-align: center;
  margin-top: 36px;
}
.jp-faq-link a {
  color: var(--hp-primary);
  text-decoration: none;
  font-weight: 600;
  font-size: 15px;
  border-bottom: 1px solid currentColor;
  padding-bottom: 2px;
}

/* ============================================================
   Final CTA card
   ============================================================ */
.jp-final {
  padding: 40px 0 100px;
}
.jp-final-card {
  max-width: 880px;
  margin: 0 auto;
  background:
    radial-gradient(circle at 20% 20%, rgba(255,255,255,0.18), transparent 50%),
    linear-gradient(135deg, var(--hp-primary), var(--hp-accent));
  color: white;
  color: var(--hp-final-fg);
  border-radius: var(--r-2xl, 24px);
  padding: 56px 48px;
  text-align: center;
  position: relative;
  overflow: hidden;
  box-shadow: 0 30px 80px rgba(72,13,223,0.3);
}
.jp-final-card::before {
  content: "";
  position: absolute;
  top: -50%;
  right: -20%;
  width: 400px;
  height: 400px;
  background: radial-gradient(circle, rgba(255,255,255,0.18), transparent 70%);
  border-radius: 50%;
  pointer-events: none;
}
.jp-final-icon {
  width: 64px;
  height: 64px;
  border-radius: 18px;
  background: var(--hp-card-accent);
  border: 1px solid rgba(255,255,255,0.3);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 22px;
  position: relative;
  z-index: 1;
  color: var(--hp-final-icon-fg);
}
#faq {
  scroll-margin-top: 220px;
}
.jp-final-title {
  font-family: var(--hp-display-font);
  font-weight: var(--hp-heading-weight, 600);
  font-size: clamp(32px, 4vw, 48px);
  line-height: 1.12;
  letter-spacing: -0.02em;
  margin: 0 0 10px;
  padding-block: 0.03em 0.09em;
  text-wrap: balance;
  position: relative;
  z-index: 1;
  overflow: visible;
  color: var(--hp-final-fg);
}
.jp-final-sub {
  font-size: 17px;
  line-height: 1.55;
  color: var(--hp-final-muted);
  margin: 0 auto 28px;
  max-width: 56ch;
  position: relative;
  z-index: 1;
}
.jp-final-note {
  margin: -6px auto 22px;
  max-width: 56ch;
  font-size: 13px;
  line-height: 1.55;
  color: var(--hp-final-muted);
  position: relative;
  z-index: 1;
}
.jp-final-note a {
  color: white;
  text-underline-offset: 2px;
}
.jp-final-btn {
  background: var(--hp-card-accent);
  color: var(--hp-action-fg);
  border: 0;
  padding: 16px 32px;
  border-radius: 999px;
  font-weight: 700;
  font-size: 16px;
  cursor: pointer;
  text-decoration: none;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  transition: transform var(--dur-fast) var(--ease), box-shadow var(--dur-fast) var(--ease);
  position: relative;
  z-index: 1;
}
.jp-final-btn:hover {
  transform: translateY(-2px);
  box-shadow: 0 16px 32px rgba(0,0,0,0.2);
}

/* ============================================================
   Sharp / soft radius respects
   ============================================================ */
body.shape-sharp .jp-team-card,
body.shape-sharp .jp-benefit-card,
body.shape-sharp .jp-hero-card,
body.shape-sharp .jp-final-card { border-radius: 4px; }
body.shape-soft .jp-team-card,
body.shape-soft .jp-benefit-card,
body.shape-soft .jp-hero-card,
body.shape-soft .jp-final-card { border-radius: 28px; }

body.density-compact .jp-section { padding: 56px 0; }
body.density-spacious .jp-section { padding: 110px 0; }

