.jp-team-avatar-img {
  position: absolute;
  inset: 0;
  display: block;
  width: 100%;
  height: 100%;
  object-fit: var(--jp-team-photo-fit, cover);
  border-radius: 0;
  /*
   * Rectangular team portraits use stored Smart Frame metadata (or generous
   * head-and-shoulders defaults). Do not apply leftover object-left /
   * object-top / rotate-left presentation hacks — those shipped off-center
   * and tilted faces.
   */
  object-position: var(--jp-team-photo-focus-x, 50%) var(--jp-team-photo-focus-y, 38%);
  transform: rotate(var(--jp-team-photo-rotation, 0deg)) scale(var(--jp-team-photo-zoom, 1));
  transform-origin: var(--jp-team-photo-focus-x, 50%) var(--jp-team-photo-focus-y, 38%);
}

.jp-team-bio {
  margin: 0 0 16px;
  color: var(--hp-card-muted, var(--fg-muted));
  font-size: 0.85rem;
  line-height: 1.45;
}

body.britt-with-bling-join {
  --bwb-black: var(--hp-bg);
  --bwb-panel: var(--hp-bg-elevated);
  --bwb-gold: var(--hp-primary);
  --bwb-blush: color-mix(in srgb, var(--hp-primary) 36%, white 64%);
  --bwb-cyan: var(--hp-accent);
  overflow-x: clip;
  background: var(--hp-bg);
  color: #fff;
}

body.britt-with-bling-join::before {
  display: none;
}

.bwb-join-page {
  min-height: 100vh;
  overflow-x: clip;
  background: var(--hp-bg);
}

.bwb-join-shell {
  position: relative;
  background: var(--hp-bg);
}

.bwb-join-content {
  width: min(1240px, calc(100% - 32px));
  margin: 0 auto;
}

body.britt-with-bling-join .hp-sticky-stack,
body.britt-with-bling-join .hp-header {
  background: rgba(10, 10, 10, 0.92);
  border-bottom: 1px solid rgba(212, 175, 55, 0.22);
  backdrop-filter: blur(16px);
}

body.britt-with-bling-join .hp-brand-name {
  background: linear-gradient(90deg, var(--bwb-gold), var(--bwb-blush), var(--bwb-cyan));
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  font-family: "Playfair Display", Georgia, serif;
  font-size: clamp(1.5rem, 3vw, 2.45rem);
  font-weight: 900;
}

body.britt-with-bling-join .hp-brand-sub,
body.britt-with-bling-join .hp-header-link {
  color: rgba(255, 255, 255, 0.72);
}

body.britt-with-bling-join .hp-header-link[aria-current="page"],
body.britt-with-bling-join .hp-header-link:hover {
  color: var(--bwb-cyan);
}

body.britt-with-bling-join .hp-shop-btn {
  background: linear-gradient(90deg, var(--bwb-gold), var(--bwb-blush));
  color: #0a0a0a;
}

body.britt-with-bling-join .hp-ticker {
  border-top: 1px solid rgba(212, 175, 55, 0.3);
  border-bottom: 1px solid rgba(0, 217, 255, 0.25);
  background: #0a0a0a;
}

body.britt-with-bling-join .hp-ticker-row {
  background: linear-gradient(90deg, #0a0a0a, #1a1a1a, #0a0a0a);
}

body.britt-with-bling-join .hp-ticker-label {
  background: var(--bwb-blush);
  color: #0a0a0a;
}

body.britt-with-bling-join .hp-ticker-row.reverse .hp-ticker-label {
  background: var(--bwb-cyan);
  color: #0a0a0a;
}

body.britt-with-bling-join .hp-ticker-item,
body.britt-with-bling-join .hp-ticker-trade {
  color: var(--bwb-gold);
}

body.britt-with-bling-join .hp-ticker-row.reverse .hp-ticker-track:has(.hp-ticker-empty) {
  animation: none;
  transform: none;
}

body.britt-with-bling-join .hp-trade-preview {
  background: transparent;
}

body.britt-with-bling-join .jp-hero {
  min-height: 720px;
  background: var(--hp-bg);
}

body.britt-with-bling-join .jp-hero-media {
  background-image:
    linear-gradient(180deg, rgba(10, 10, 10, 0.28), rgba(10, 10, 10, 0.84)),
    url("/britt-with-bling/join-hero.jpeg");
  background-position: center;
  background-size: cover;
}

body.britt-with-bling-join .jp-hero-card {
  border: 1px solid rgba(212, 175, 55, 0.28);
  background: rgba(10, 10, 10, 0.64);
  box-shadow: 0 28px 90px rgba(0, 0, 0, 0.55);
  backdrop-filter: blur(12px);
}

body.britt-with-bling-join .jp-hero-eyebrow,
body.britt-with-bling-join .jp-hero-compliance {
  color: var(--bwb-cyan);
}

body.britt-with-bling-join .jp-hero-title {
  background: linear-gradient(90deg, var(--bwb-gold), var(--bwb-blush), var(--bwb-cyan));
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  font-family: "Playfair Display", Georgia, serif;
  font-size: clamp(3.2rem, 7vw, 7rem);
}

body.britt-with-bling-join .jp-hero-pitch,
body.britt-with-bling-join .jp-hero-localized,
body.britt-with-bling-join .jp-section-sub {
  color: rgba(255, 255, 255, 0.76);
}

body.britt-with-bling-join .jp-hero-promo {
  border-color: rgba(244, 194, 194, 0.35);
  background: rgba(244, 194, 194, 0.12);
  color: #fff;
}

body.britt-with-bling-join .jp-hero .hp-btn-primary,
body.britt-with-bling-join .jp-final-btn,
body.britt-with-bling-join .jp-spot-btn {
  background: var(--bwb-cyan);
  color: #0a0a0a;
  box-shadow: 0 18px 44px rgba(0, 217, 255, 0.22);
}

body.britt-with-bling-join .jp-section {
  background: var(--bwb-black);
}

body.britt-with-bling-join .jp-why {
  background: #111;
}

body.britt-with-bling-join .jp-section-title,
body.britt-with-bling-join .jp-team-business {
  background: linear-gradient(90deg, var(--bwb-gold), var(--bwb-blush), var(--bwb-cyan));
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}

body.britt-with-bling-join .jp-section-eyebrow {
  color: var(--bwb-cyan);
}

body.britt-with-bling-join .jp-team-card,
body.britt-with-bling-join .jp-benefit-card,
body.britt-with-bling-join .jp-faq-note,
body.britt-with-bling-join .jp-faq-item,
body.britt-with-bling-join .jp-final-card {
  border: 1px solid rgba(212, 175, 55, 0.26);
  background: linear-gradient(135deg, rgba(26, 26, 26, 0.96), rgba(10, 10, 10, 0.98));
  color: #fff;
  box-shadow: 0 22px 64px rgba(0, 0, 0, 0.42);
}

body.britt-with-bling-join .jp-team-card::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 8px;
  background: linear-gradient(90deg, var(--bwb-gold), var(--bwb-blush), var(--bwb-cyan));
}

body.britt-with-bling-join .jp-team-avatar,
body.britt-with-bling-join .jp-benefit-icon,
body.britt-with-bling-join .jp-final-icon,
body.britt-with-bling-join .jp-spot-glyph {
  border: 2px solid rgba(212, 175, 55, 0.35);
  background: #0a0a0a;
  color: var(--bwb-gold);
}

body.britt-with-bling-join .jp-team-name,
body.britt-with-bling-join .jp-benefit-title,
body.britt-with-bling-join .jp-faq-q,
body.britt-with-bling-join .jp-spot-title {
  color: #fff;
}

body.britt-with-bling-join .jp-team-location,
body.britt-with-bling-join .jp-benefit-desc,
body.britt-with-bling-join .jp-faq-a-inner,
body.britt-with-bling-join .jp-spot-sub,
body.britt-with-bling-join .jp-team-bio {
  color: rgba(255, 255, 255, 0.68);
}

body.britt-with-bling-join .jp-team-social {
  background: #061820;
  border-color: #00d9ff;
  color: #f4feff;
  box-shadow: 0 0 0 1px rgba(0, 217, 255, 0.35);
}

body.britt-with-bling-join .jp-team-social:hover {
  background: #00d9ff;
  color: #041018;
  border-color: #00d9ff;
}

body.britt-with-bling-join .jp-final {
  background: linear-gradient(90deg, var(--bwb-gold), var(--bwb-blush), var(--bwb-cyan));
}

body.britt-with-bling-join .hp-footer {
  border-top: 1px solid rgba(212, 175, 55, 0.22);
  background: var(--bwb-black);
}

body.britt-with-bling-join .hp-footer-brand {
  background: linear-gradient(90deg, var(--bwb-gold), var(--bwb-blush), var(--bwb-cyan));
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}

@media (max-width: 720px) {
  body.britt-with-bling-join .hp-header-inner {
    grid-template-columns: minmax(0, 1fr) auto;
    width: min(100% - 20px, 1180px);
    max-width: 100%;
  }

  body.britt-with-bling-join .hp-brand {
    min-width: 0;
  }

  body.britt-with-bling-join .hp-brand-name {
    max-width: 100%;
    overflow-wrap: anywhere;
  }

  body.britt-with-bling-join .hp-header-nav {
    grid-column: 1 / -1;
    max-width: 100%;
    overflow-x: auto;
  }

  body.britt-with-bling-join .hp-shop-btn {
    max-width: min(34vw, 132px);
    padding-inline: 16px;
  }
}

body.bling-kitchen-join {
  --bk-ink: #20172b;
  --bk-plum: #6f2da8;
  --bk-violet: #9b5de5;
  background: linear-gradient(180deg, #fff9f1 0%, #f8eef8 52%, #fff 100%);
}

.bk-join-shell {
  width: min(1180px, calc(100% - 32px));
  margin: 0 auto;
  padding: 28px 0 64px;
}

body.bling-kitchen-join .hp-sticky-stack,
body.bling-kitchen-join .jp-hero,
body.bling-kitchen-join .jp-section,
body.bling-kitchen-join .jp-final-card,
body.bling-kitchen-join .hp-footer {
  border-radius: 8px;
  border-color: rgba(32, 23, 43, 0.13);
  background: rgba(255, 255, 255, 0.94);
  box-shadow: 0 18px 45px rgba(58, 29, 82, 0.13);
}

body.bling-kitchen-join .jp-hero-title,
body.bling-kitchen-join .jp-section-title,
body.bling-kitchen-join .hp-footer-brand {
  font-family: "Playfair Display", Georgia, serif;
  color: var(--bk-ink);
}

body.bling-kitchen-join .jp-hero-eyebrow,
body.bling-kitchen-join .jp-card-kicker,
body.bling-kitchen-join .jp-faq-item button {
  color: var(--bk-plum);
}

body.bling-kitchen-join {
  --bk-muted: #6d5f73;
  --bk-sage: #5f7461;
  --bk-gold: #b5843f;
  background:
    linear-gradient(180deg, #fff8ee 0%, #f7eef5 48%, #fdfaf4 100%);
}

body.bling-kitchen-join .jp-hero,
body.bling-kitchen-join .jp-section,
body.bling-kitchen-join .jp-final-card {
  background: rgba(255, 255, 255, 0.95);
  border-color: rgba(95, 42, 131, 0.14);
}

body.bling-kitchen-join .jp-hero-title,
body.bling-kitchen-join .jp-section-title {
  color: var(--bk-ink);
}

body.bling-kitchen-join .jp-hero-sub,
body.bling-kitchen-join .jp-section-copy,
body.bling-kitchen-join .jp-benefit-card p,
body.bling-kitchen-join .jp-team-card p,
body.bling-kitchen-join .jp-faq-item p {
