body.bling-kitchen-join .jp-spot-btn,
body.bling-kitchen-join .jp-final-card a {
  border-radius: 999px;
  background: linear-gradient(135deg, #5f7461, #5f2a83);
  color: #fff8ee;
}

body.bling-kitchen-join .hp-footer {
  background: #2b1a33;
  color: rgba(255, 248, 238, 0.78);
  box-shadow: none;
}

body.bling-kitchen-join .hp-footer-brand,
body.bling-kitchen-join .hp-footer a {
  color: #fff8ee;
}

body.bling-kitchen-join .hp-footer-tag,
body.bling-kitchen-join .hp-footer-bottom,
body.bling-kitchen-join .hp-footer-bottom p {
  color: rgba(255, 248, 238, 0.78);
}

/* Emerald Garden join-page continuation */
body.bg-emerald-garden #team,
body.bg-emerald-garden #faq {
  background:
    radial-gradient(ellipse at 8% 14%, rgba(202, 218, 196, 0.44), transparent 21rem),
    radial-gradient(ellipse at 94% 88%, rgba(229, 211, 179, 0.28), transparent 22rem),
