}

body.bg-emerald-garden .jp-why,
body.bg-emerald-garden .jp-final {
  background:
    radial-gradient(circle at 104% -10%, rgba(255, 255, 255, 0.2), transparent 26rem),
    radial-gradient(circle at -8% 108%, rgba(4, 120, 87, 0.4), transparent 27rem),
