  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}

body.bg-emerald-garden .jp-why .jp-section-title,
body.bg-emerald-garden .jp-why .jp-section-eyebrow,
body.bg-emerald-garden .jp-why .jp-section-sub {
