body.bg-gnome-garden .hp-ticker-row { background: #233f2f; color: #fff3d6; }
body.bg-gnome-garden .hp-ticker-label { background: #14291f; color: #f4c45e; }
body.bg-gnome-garden .hp-ticker-row.reverse { background: #eee0b9; color: #243c29; }
