body.bg-gnome-garden .hp-ticker-row.reverse :is(.hp-ticker-trade, .hp-ticker-empty) { color: #243c29; }
body.bg-gnome-garden .hp-ticker-item .dot { background: #f4c45e; box-shadow: none; }

/* The content stays above the scene. Edge art has dedicated breathing room. */
