body.bg-gnome-garden :is(.mhf-hero-video, .mhf-hero-shade, .bwb-hero-image, .bwb-hero-shade, .bk-home-hero-image) { display: none; }
body.bg-gnome-garden .bk-home-hero::after { background: none; }
body.bg-gnome-garden :is(.mhf-hero, .bwb-hero, .bk-home-hero) { place-items: center; }
body.bg-gnome-garden :is(.mhf-hero-content, .bwb-hero-content, .bk-home-hero-content) {
  position: relative;
  z-index: 2;
  width: 100%;
  max-width: 1100px;
