body.bg-gnome-garden .hp-hero { min-height: 620px; }
body.bg-gnome-garden .hp-hero-inner > div { background: transparent; padding: 0; border: 0; box-shadow: none; backdrop-filter: none; }
body.bg-gnome-garden :is(.hp-hero-headline, .tp-hero-title, .jp-hero-title, .mhf-hero-title, .bwb-hero-title, .bk-home-hero-content h1) {
  color: #fff3d6;
