}
body.bg-gnome-garden .hp-btn-sparkle .spark { display: none; }
body.bg-gnome-garden :is(.hp-event-platform.tt, .hp-event-platform.tiktok, .hp-event-platform.custom) { background: #842421; color: #fff3d6; }
