}
body.bg-gnome-garden :is(.hp-event-name, .tp-card-name, .tp-card-expand-name, .tp-sheet-title, .jp-team-name, .jp-benefit-title, .jp-spot-title, .jp-final-title) { color: var(--hp-card-fg); }
body.bg-gnome-garden :is(.hp-step, .hp-signup-consent-box, .tp-filter-panel, .jp-faq-note) { background: #f5ecd7; border-color: #d5c49f; color: var(--hp-card-fg); }
body.bg-gnome-garden :is(.hp-step-num, .jp-benefit-icon, .jp-final-icon) { background: #842421; color: #fff3d6; }
body.bg-gnome-garden .hp-footer { background: #14291f; color: #e3d9bd; border-top: 1px solid #8e794a; }
body.bg-gnome-garden .hp-footer a:hover { color: #f4c45e; }
body.bg-gnome-garden .hp-trade-preview-link { color: #842421; }
body.bg-gnome-garden :is(input, textarea, select) { accent-color: #842421; }
body.bg-gnome-garden .tp-sheet-field :is(input, textarea, select) { background: var(--hp-field-bg); color: var(--hp-field-fg); }
body.bg-gnome-garden :is(a, button, input, select, textarea):focus-visible { outline: 3px solid #bd872a; outline-offset: 4px; }

.gg-decoration { position: absolute; inset: 0; z-index: 3; pointer-events: none; }
.gg-scene { position: absolute; inset: 0; z-index: 1; pointer-events: none; user-select: none; overflow: hidden; }
.gg-scene * { pointer-events: none; }
.gg-motion-control { position: absolute; left: 20px; bottom: 16px; z-index: 2; pointer-events: auto; padding: 8px 12px; min-height: 36px; border: 1px solid #d6b57477; border-radius: 20px; background: #14291fdd; color: #fff3d6; font: 12px/1.4 "DM Sans", sans-serif; cursor: pointer; }
.gg-decoration[data-paused="true"] .gg-scene *,
.gg-decoration[data-paused="true"] .gg-scene *::after { animation-play-state: paused !important; }
body.bg-gnome-garden :is(.hp-hero-fx-layer, .hp-fx-layer) { display: none; }
body.gg-utility .hp-hero { background: #f5edda; }
.gg-lantern { position: absolute; top: -16px; width: clamp(60px, 7vw, 100px); height: auto; transform-origin: 50% 0; animation: gg-sway 8s ease-in-out infinite; }
.gg-lantern-left { left: clamp(14px, 3vw, 46px); }
.gg-lantern-right { right: clamp(14px, 3vw, 46px); animation-delay: -3s; }
.gg-lantern img { width: 100%; height: auto; }
.gg-lantern::after { content: ''; position: absolute; inset: 40% -15% 4%; border-radius: 50%; background: radial-gradient(ellipse, #ffd16e50, transparent 68%); animation: gg-glow 5s ease-in-out infinite; }
.gg-gnome { position: absolute; right: clamp(16px, 3vw, 48px); bottom: -8px; width: clamp(100px, 12vw, 180px); height: auto; animation: gg-peek 650ms ease-out both; filter: drop-shadow(0 8px 12px #07160d66); }
.gg-firefly { position: absolute; width: 4px; height: 4px; border-radius: 50%; background: #ffe6a4; box-shadow: 0 0 8px 3px #f4c45e35; opacity: .6; animation: gg-drift 16s ease-in-out infinite; }
.gg-firefly[data-firefly-index="1"] { left: 6%; top: 45%; animation-delay: -2s; }
.gg-firefly[data-firefly-index="2"] { left: 18%; top: 78%; animation-delay: -7s; }
.gg-firefly[data-firefly-index="3"] { left: 87%; top: 58%; animation-delay: -11s; }
.gg-firefly[data-firefly-index="4"] { left: 92%; top: 24%; animation-delay: -4s; }
.gg-firefly[data-firefly-index="5"] { left: 37%; top: 12%; animation-delay: -9s; }
.gg-firefly[data-firefly-index="6"] { left: 69%; top: 88%; animation-delay: -13s; }
.gg-firefly[data-firefly-index="7"] { left: 3%; top: 85%; animation-delay: -6s; }
.gg-firefly[data-firefly-index="8"] { left: 77%; top: 15%; animation-delay: -15s; }
@keyframes gg-sway { 0%,100% { transform: rotate(-1deg); } 50% { transform: rotate(1deg); } }
@keyframes gg-glow { 0%,100% { opacity: .65; transform: scale(.97); } 50% { opacity: 1; transform: scale(1.03); } }
@keyframes gg-peek { from { opacity: 0; transform: translateY(20px); } to { opacity: 1; transform: translateY(0); } }
@keyframes gg-drift { 0%,100% { opacity: .2; transform: translate(0,0); } 50% { opacity: .75; transform: translate(14px,-24px); } }
@media (hover: hover) and (prefers-reduced-motion: no-preference) {
  body.btn-lantern-lift :is(.hp-btn-primary, .hp-btn-outline, .hp-shop-btn, .hp-signup-submit, .tp-card-expand-cta, .jp-spot-btn, .jp-final-btn):hover { transform: translateY(-2px); box-shadow: 0 9px 22px #9d713c36; }
}
@media (min-width: 768px) {
  body.bg-gnome-garden .tp-hero .gg-gnome { width: 110px; }
