@media (max-width: 900px) {
  body.bg-gnome-garden .hp-wibp-grid { grid-template-columns: minmax(0, 1fr); }
  body.bg-gnome-garden .hp-wibp-card { min-width: 0; overflow-wrap: anywhere; }
