  --nb-live: #61f29b;
  --fg: var(--nb-ink);
  --fg-muted: var(--nb-muted);
  --border: rgba(255, 104, 220, 0.3);
  --hp-bg: #120414;
  --hp-bg-elevated: #261029;
  --bg-deep: #09010c;
