  --hp-media-card-bg:#fffdf7; --hp-media-card-fg:#382617; --hp-media-card-muted:#715d49;
  --hp-media-card-header-bg:linear-gradient(125deg,#713518,#915022); --hp-media-card-footer-bg:#f3e4ca;
  --hp-media-card-border:#cdb18b; --hp-media-card-accent-contrast:#fff9ef;
