  --hp-media-card-shadow:0 24px 64px #75411715; --hp-media-card-hover-shadow:0 30px 74px #75411725;
  --hp-final-fg:#382617; --hp-final-muted:#715d49; --hp-final-icon-fg:#fff9ef;
  --bk-ink:#382617; --bk-muted:#715d49; --bk-plum:#87451b; --bk-violet:#91451d; --bk-gold:#b18338; --bk-sage:#76582e;
