 * fonts, spacing, header, tickers and Live Lineup geometry stay untouched. */
html:has(body.bg-fall-owl) {
  background: #201321;
  --bg: #201321;
  --bg-elevated: #302030;
}
body.bg-fall-owl {
  color-scheme: dark;
  --fg: #fff3e4;
  --fg-muted: #ddc8b8;
  --border: #70513e;
  --hp-bg: #201321;
  --hp-bg-elevated: #302030;
