  --hp-card-fg: #fff3e4;
  --hp-card-muted: #ddc8b8;
  --hp-card-accent: #efba73;
  --hp-form-panel-bg: #302030;
  --hp-form-panel-fg: #fff3e4;
  --hp-field-bg: #302030;
  --hp-field-fg: #fff3e4;
  --hp-final-fg: #fff3e4;
  --hp-final-muted: #ddc8b8;
  --hp-final-icon-fg: #28161e;
  --hp-action-fg: #28161e;
  --hp-media-card-bg: #302030;
