 body.bg-fall-owl .hp-hero .hp-hero-inner{width:100%;max-width:100%;margin:0;padding:42px 24px 52px;grid-template-columns:minmax(0,620px);justify-content:center;text-align:center}
 body.bg-fall-owl .hp-hero .hp-hero-headline{font-size:clamp(38px,6vw,56px);max-width:none;margin-inline:auto}
 body.bg-fall-owl .hp-hero .hp-hero-sub{margin-inline:auto}
 body.bg-fall-owl .hp-hero :is(.hp-hero-ctas,.hp-hero-cta-primary-row){justify-content:center}
 body.bg-fall-owl .hp-hero::after{display:none}
}
@media(max-width:600px){
 body.bg-fall-owl .hp-hero .hp-hero-media{aspect-ratio:1/1;background-position:right center!important}
 body.bg-fall-owl .hp-hero .hp-hero-inner{padding:32px 20px 44px}
 body.bg-fall-owl .hp-hero .hp-hero-headline{font-size:40px;line-height:1.1}
 body.bg-fall-owl .hp-hero .hp-hero-sub{font-size:16px}
}


/* Join retains its original centered card, with the matching autumn palette. */
body.bg-fall-owl .jp-hero-media {background:radial-gradient(ellipse at 88% 22%,#80523566,transparent 50%),linear-gradient(135deg,#201321,#3a2432 65%,#241623)!important;}

/* Center the original copy/actions in the open lane left of the owl. */
@media(min-width:1101px){
 body.bg-fall-owl .hp-hero .hp-hero-inner{width:56%;max-width:none;margin:0;padding:72px 24px;grid-template-columns:minmax(0,510px);justify-content:center;text-align:center}
 body.bg-fall-owl .hp-hero .hp-hero-headline{margin-inline:auto}
 body.bg-fall-owl .hp-hero .hp-hero-sub{margin-inline:auto}
 body.bg-fall-owl .hp-hero :is(.hp-hero-ctas,.hp-hero-cta-primary-row){justify-content:center}
}

/* Readability finishing across the existing Amethyst secondary surfaces. */
body.bg-fall-owl .jp-faq-note {
  background: #302030;
  border-color: #70513e;
  color: var(--hp-card-muted);
}
body.bg-fall-owl :is(.jp-faq-note a, .jp-faq-link, .hp-calendar-modal-eyebrow, .tp-sheet-eyebrow) {
  color: #efba73;
}
body.bg-fall-owl :is(.hp-signup-input, .tp-board-search input, .tp-board-sort select, .tp-sheet-field input, .tp-sheet-field textarea, .tp-sheet-field select) {
  border-color: #a17b59;
}
body.bg-fall-owl :is(a, button, input, select, textarea):focus-visible {
  outline: 2px solid #efba73;
  outline-offset: 3px;
}
body.bg-fall-owl input[type="checkbox"] { accent-color: #efba73; }
body.bg-fall-owl .tp-sheet-upload input::file-selector-button {
  background: #efba73;
  color: #28161e;
  border: 1px solid #a17b59;
  border-radius: 6px;
  padding: 6px 8px;
  font: inherit;
}


/* Controls stay on the artwork, above the mobile copy. */
body.bg-fall-owl .fow-controls{position:absolute;right:16px;bottom:16px;z-index:5;display:flex;flex-wrap:wrap;justify-content:flex-end;gap:8px;max-width:calc(100% - 32px);pointer-events:auto}
body.bg-fall-owl .hp-hero[data-appearance-preset="fall_owl_harvest_moon"] .fow-toggle{position:static;inset:auto;background:#302030ee;color:#fff3e4;min-height:44px;min-width:44px}
body.bg-fall-owl .fow-toggle[hidden]{display:none}
@media(max-width:600px){body.bg-fall-owl .hp-hero :is(.fow-poster,.fow-video){object-position:right center!important}}
body.bg-fall-owl .hp-hero[data-appearance-preset="fall_owl_harvest_moon"] .fow-media::after {
  background: linear-gradient(0deg,#201321,transparent 85px),linear-gradient(90deg,rgba(24,12,26,.32),rgba(24,12,26,.08) 39%,transparent 58%);
}
body.bg-fall-owl .hp-hero:has(.fow-media)::after { display: none; }
body.bg-fall-owl .hp-hero[data-appearance-preset="fall_owl_harvest_moon"] .fow-toggle {
  border: 1px solid #efba73;
  border-radius: 22px;
  padding: 9px 14px;
  background: #201321ed;
  font: 13px system-ui;
}
@media(max-width:1100px){body.bg-fall-owl .hp-hero .fow-media::after{display:none}}
@media(max-width:600px){
  body.bg-fall-owl .fow-controls{right:10px;bottom:10px;gap:6px}
  body.bg-fall-owl .hp-hero[data-appearance-preset="fall_owl_harvest_moon"] .fow-toggle{padding:8px 11px;font-size:12px}
}

starlight-christmas-hollow.css:
/* Starlight Christmas Hollow: palette and decorative hero only. Shared Amethyst
 * fonts, spacing, header, tickers and Live Lineup geometry stay untouched. */
html[data-customer-theme="starlight_christmas_hollow"] {
  background: #0b2039;
  --bg: #0b2039;
  --bg-elevated: #132e4b;
  --starlight-cranberry: #94283e;
  --starlight-ribbon: #692337;
}
html[data-customer-theme="starlight_christmas_hollow"] body {
  color-scheme: dark;
  --fg: #fff7e9;
  --fg-muted: #c5d5e5;
  --border: #50617a;
  --hp-bg: #0b2039;
  --hp-bg-elevated: #132e4b;
  --bg-deep: #061326;
  --hp-preview-bg: #132e4b;
  --hp-preview-fg: #fff7e9;
  --hp-preview-muted: #c5d5e5;
  --hp-preview-border: #50617a;
  --hp-card-fg: #fff7e9;
  --hp-card-muted: #c5d5e5;
  --hp-card-accent: #f2c77b;
  --hp-form-panel-bg: #132e4b;
  --hp-form-panel-fg: #fff7e9;
  --hp-field-bg: #132e4b;
  --hp-field-fg: #fff7e9;
  --hp-final-fg: #fff7e9;
  --hp-final-muted: #c5d5e5;
  --hp-final-icon-fg: #11263c;
  --hp-action-fg: #11263c;
  --hp-media-card-bg: #132e4b;
  --hp-media-card-fg: #fff7e9;
  --hp-media-card-muted: #c5d5e5;
  --hp-media-card-border: #50617a;
  --hp-media-card-header-bg: linear-gradient(135deg, #f2c77b, #f2c77b);
  --hp-media-card-footer-bg: #1b3855;
  --hp-media-card-shadow: 0 24px 64px #0000003b;
  --hp-media-card-hover-shadow: 0 30px 74px #00000050;
  --hp-media-card-accent-contrast: #11263c;
  --hp-media-icon-fg: #11263c;
  --hp-media-cta-fg: #11263c;
  --hp-media-placeholder-fg: #c5d5e5;
  --hp-media-placeholder-bg: #1b3855;
  --hp-media-cta-bg: #f2c77b;
  background: #0b2039;
  color: #fff7e9;
}

html[data-customer-theme="starlight_christmas_hollow"] body .hp-header {
  background: #132e4b;
  border-color: #50617a;
}
html[data-customer-theme="starlight_christmas_hollow"] body :is(.hp-brand-name, .hp-header-link) { color: #fff7e9; }
html[data-customer-theme="starlight_christmas_hollow"] body .hp-brand-sub { color: #c5d5e5; }
html[data-customer-theme="starlight_christmas_hollow"] body .hp-header-link[aria-current="page"] { color: #f2c77b; }

html[data-customer-theme="starlight_christmas_hollow"] body :is(.hp-ticker, .hp-ticker-row) {
  background: var(--starlight-ribbon);
  color: #fff7e9;
  border-color: #50617a;
}
html[data-customer-theme="starlight_christmas_hollow"] body .hp-ticker-row.reverse { background: #1b3855; }
html[data-customer-theme="starlight_christmas_hollow"] body :is(.hp-ticker-item, .hp-ticker-label, .hp-ticker-trade, .hp-ticker-empty) { color: #fff7e9; }
html[data-customer-theme="starlight_christmas_hollow"] body .hp-ticker-row.reverse :is(.hp-ticker-trade, .hp-ticker-empty) { color: #fff7e9; }
html[data-customer-theme="starlight_christmas_hollow"] body .hp-ticker-row.reverse .hp-ticker-trade:hover { color: #f2c77b; }
html[data-customer-theme="starlight_christmas_hollow"] body .hp-ticker-row .hp-ticker-label {
  background: var(--starlight-ribbon);
  color: #fff7e9;
}
html[data-customer-theme="starlight_christmas_hollow"] body .hp-ticker-row.reverse .hp-ticker-label {
  background: #1b3855;
  color: #fff7e9;
}
html[data-customer-theme="starlight_christmas_hollow"] body :is(.hp-trade-preview, .hp-lrq-strip, .hp-lrq, .hp-lineup-calendar-row) {
  background: #132e4b;
  color: #fff7e9;
  border-color: #50617a;
}
html[data-customer-theme="starlight_christmas_hollow"] body :is(.hp-lineup-idle-prompt, .hp-trade-preview-head, .hp-trade-preview-link, .hp-trade-preview-pill) { color: #fff7e9; }
html[data-customer-theme="starlight_christmas_hollow"] body :is(.hp-trade-preview-updated, .hp-trade-preview-pill .label) { color: #c5d5e5; }

html[data-customer-theme="starlight_christmas_hollow"] body :is(
  .hp-shop-btn, .hp-btn-primary, .hp-signup-submit, .tp-card-expand-cta,
  .tp-sheet-submit, .jp-spot-btn, .jp-final-btn, .jp-why-btn--primary,
  .mhf-cta-dance-floor, .bwb-cta-dance-floor
) {
  background: var(--starlight-cranberry);
  color: #fff7e9;
  border-color: #f2c77b;
  box-shadow: 0 9px 24px #0000003b;
}

/* The original full-bleed hero and original HTML copy/actions stay in place. */
html[data-customer-theme="starlight_christmas_hollow"] body .hp-hero[data-appearance-preset="starlight_christmas_hollow"] .hp-hero-media,
html[data-customer-theme="starlight_christmas_hollow"] body .jp-hero-media {
  background: linear-gradient(90deg, rgba(20, 8, 15, .08), rgba(20, 8, 15, 0)),
    url('/amethyst/skins/starlight-christmas-hollow/hero-poster.webp') center center / cover no-repeat;
  background-blend-mode: normal;
}
html[data-customer-theme="starlight_christmas_hollow"] body .hp-hero[data-appearance-preset="starlight_christmas_hollow"] .hp-hero-headline {
  color: #fff7e9;
  -webkit-text-fill-color: #fff7e9;
  background: none;
  text-shadow: 0 2px 14px #06132688;
}
html[data-customer-theme="starlight_christmas_hollow"] body .hp-hero[data-appearance-preset="starlight_christmas_hollow"] .hp-hero-sub {
  color: #f9ded5;
  text-shadow: 0 1px 6px #06132699;
}
html[data-customer-theme="starlight_christmas_hollow"] body .hp-hero[data-appearance-preset="starlight_christmas_hollow"] :is(.hp-btn-outline, .hp-btn-watch) {
  color: #fff7e9;
  border-color: #f2c77b99;
  background: #11263ca6;
  backdrop-filter: blur(8px);
}
html[data-customer-theme="starlight_christmas_hollow"] body .hp-hero[data-appearance-preset="starlight_christmas_hollow"] .hp-hero-fx-layer { display: none; }
html[data-customer-theme="starlight_christmas_hollow"] body .hp-hero[data-appearance-preset="starlight_christmas_hollow"] .sch-media {
  position: absolute;
  inset: 0;
  z-index: 1;
  overflow: hidden;
  pointer-events: none;
}
html[data-customer-theme="starlight_christmas_hollow"] body .hp-hero[data-appearance-preset="starlight_christmas_hollow"] :is(.sch-poster, .sch-video) {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center center;
  pointer-events: none;
}
html[data-customer-theme="starlight_christmas_hollow"] body .hp-hero[data-appearance-preset="starlight_christmas_hollow"] .sch-video { opacity: 0; }
html[data-customer-theme="starlight_christmas_hollow"] body .hp-hero[data-appearance-preset="starlight_christmas_hollow"] .sch-media[data-sch-has-frame="true"] .sch-video { opacity: 1; }
html[data-customer-theme="starlight_christmas_hollow"] body .hp-hero[data-appearance-preset="starlight_christmas_hollow"] .sch-media::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(90deg, rgba(20, 8, 15, .08), rgba(20, 8, 15, 0));
  pointer-events: none;
}
html[data-customer-theme="starlight_christmas_hollow"] body .hp-hero[data-appearance-preset="starlight_christmas_hollow"] .sch-toggle {
  position: absolute;
  inset-inline-end: 16px;
  bottom: 16px;
  z-index: 4;
  min-width: 44px;
  min-height: 44px;
  padding: 8px 14px;
  border: 1px solid #f2c77b99;
  border-radius: 999px;
  background: #132e4bee;
  color: #fff7e9;
  font: inherit;
  font-size: 12px;
  cursor: pointer;
}
html[data-customer-theme="starlight_christmas_hollow"] body .hp-hero[data-appearance-preset="starlight_christmas_hollow"] .sch-toggle:focus-visible {
  outline: 2px solid #fff7e9;
  outline-offset: 3px;
}

/* Surface tokens serve Home, Trade, Join and their existing forms uniformly. */
html[data-customer-theme="starlight_christmas_hollow"] body :is(#events, #wibp, #about, .hp-signup, .hp-footer) {
  background: #0b2039;
  color: #fff7e9;
  border-color: #50617a;
}
html[data-customer-theme="starlight_christmas_hollow"] body :is(.hp-event-card, .hp-wibp-card, .hp-trade-card, .hp-signup-card, .tp-lrq-rail, .tp-filters, .tp-card, .tp-card-expand, .tp-sheet, .jp-hero-card, .jp-team-card, .jp-benefit-card, .jp-faq-item, .jp-final-card) {
  background: #132e4b;
  color: var(--hp-card-fg);
  border-color: #50617a;
  box-shadow: 0 15px 38px #00000035;
}
html[data-customer-theme="starlight_christmas_hollow"] body :is(.hp-section-title, .hp-event-title, .hp-about-headline, .hp-signup-title, .tp-hero-title, .jp-hero-title, .jp-section-title) {
  color: #fff7e9;
  -webkit-text-fill-color: #fff7e9;
  background: none;
}
html[data-customer-theme="starlight_christmas_hollow"] body :is(.hp-section-sub, .hp-event-desc, .hp-event-meta, .hp-about-text, .hp-footer-tagline, .tp-hero-sub, .jp-hero-pitch, .jp-hero-localized, .jp-hero-compliance, .jp-section-sub) { color: #c5d5e5; }
html[data-customer-theme="starlight_christmas_hollow"] body .jp-hero-eyebrow { color: #f2c77b; }
html[data-customer-theme="starlight_christmas_hollow"] body .jp-hero-eyebrow::before,
html[data-customer-theme="starlight_christmas_hollow"] body .jp-hero-eyebrow::after { background: #50617a; }
html[data-customer-theme="starlight_christmas_hollow"] body .jp-hero-compliance a { color: #f2c77b; }
html[data-customer-theme="starlight_christmas_hollow"] body :is(.hp-event-tag, .hp-event-badge, .jp-hero-promo) {
  background: var(--starlight-ribbon);
  color: #fff7e9;
  border-color: #50617a;
}
html[data-customer-theme="starlight_christmas_hollow"] body .hp-event-pill { background: #f2c77b; color: #11263c; }
html[data-customer-theme="starlight_christmas_hollow"] body .hp-event-pill .pip { background: #11263c; }
html[data-customer-theme="starlight_christmas_hollow"] body .hp-step-num { background: #f2c77b; color: #132e4b; }
html[data-customer-theme="starlight_christmas_hollow"] body .tp-filter-chip { background: #0b2039; color: #fff7e9; border-color: #50617a; }
html[data-customer-theme="starlight_christmas_hollow"] body :is(.tp-filter-chip, .tp-filter-pill).active {
  background: var(--starlight-cranberry);
  color: #fff7e9;
  border-color: #f2c77b;
}
html[data-customer-theme="starlight_christmas_hollow"] body .hp-footer :is(.hp-footer-brand, .hp-footer-team, .hp-footer-col a) { color: var(--hp-card-fg); }
html[data-customer-theme="starlight_christmas_hollow"] body .hp-footer :is(.hp-footer-tag, .hp-footer-coming-soon, .hp-footer-bottom, .hp-footer-bottom a) { color: var(--hp-card-muted); }
html[data-customer-theme="starlight_christmas_hollow"] body .hp-footer .hp-footer-bottom { border-color: var(--border); }
html[data-customer-theme="starlight_christmas_hollow"] body .hp-footer .hp-footer-coming-soon span {
  background: #254765;
  color: var(--hp-card-muted);
  border-color: var(--border);
}
html[data-customer-theme="starlight_christmas_hollow"] body .hp-footer .hp-footer-social {
  background: #132e4b;
  color: var(--hp-card-fg);
  border-color: var(--border);
}
html[data-customer-theme="starlight_christmas_hollow"] body .hp-footer .hp-footer-social:hover {
  background: #254765;
  color: var(--hp-card-fg);
  border-color: var(--hp-card-accent);
}
html[data-customer-theme="starlight_christmas_hollow"] body .hp-footer :is(.hp-footer-col a, .hp-footer-bottom a):hover { color: var(--hp-card-accent); }
html[data-customer-theme="starlight_christmas_hollow"] body .hp-footer a:focus-visible { outline-color: var(--hp-card-accent); }

/* Platform labels and glyphs inherit the theme rather than provider colors. */
html[data-customer-theme="starlight_christmas_hollow"] body :is(.hp-event-platform, .event-platform-btn, .hp-calendar-choice.google, .hp-calendar-choice.outlook) {
  background: linear-gradient(105deg, #f2c77b, #f2c77b);
  color: #11263c;
  border-color: #f2c77b;
}
html[data-customer-theme="starlight_christmas_hollow"] body :is(.hp-event-platform, .event-platform-btn) .glyph {
  background: #11263c;
  color: #f2c77b;
}
html[data-customer-theme="starlight_christmas_hollow"] body .hp-event-platform .glyph::after { color: #f2c77b; }
html[data-customer-theme="starlight_christmas_hollow"] body :is(.hp-stream-btn, .hp-watch-option, .stream-option) .glyph {
  background: #f2c77b;
  color: #11263c;
}
html[data-customer-theme="starlight_christmas_hollow"] body :is(.hp-stream-btn, .hp-watch-option) {
  background: #132e4b;
  color: #fff7e9;
  border-color: #50617a;
}
html[data-customer-theme="starlight_christmas_hollow"] body :is(.hp-stream-btn, .hp-watch-option):hover { background: #254765; color: #fff7e9; }
html[data-customer-theme="starlight_christmas_hollow"] body :is(.hp-stream-btn, .hp-watch-option) .handle { color: #c5d5e5; }
html[data-customer-theme="starlight_christmas_hollow"] body .jp-team-social {
  background: #132e4b;
  color: #f2c77b;
  border-color: #50617a;
}
html[data-customer-theme="starlight_christmas_hollow"] body .jp-team-social:hover {
  background: #f2c77b;
  color: #11263c;
  border-color: #f2c77b;
}
html[data-customer-theme="starlight_christmas_hollow"] body :is(.hp-event-platform, .event-platform-btn, .jp-team-social):focus-visible {
  outline-color: #f2c77b;
}

/* Keep existing icon bubbles distinct from their own surrounding surfaces. */
html[data-customer-theme="starlight_christmas_hollow"] body .hp-customer-media-empty-icon {
  background: #11263c;
  color: #f2c77b;
  border-color: #c89b52;
}
html[data-customer-theme="starlight_christmas_hollow"] body :is(.jp-benefit-icon, .jp-final-icon, .tp-sheet-success-icon) {
  background: #f2c77b;
  color: #11263c;
  border-color: #c89b52;
}
html[data-customer-theme="starlight_christmas_hollow"] body .tp-empty-glyph { color: #f2c77b; opacity: 1; }
html[data-customer-theme="starlight_christmas_hollow"] body .hp-calendar-modal-close { background: #132e4b; color: #fff7e9; }
html[data-customer-theme="starlight_christmas_hollow"] body .hp-calendar-modal-close:hover { background: #254765; }

/* Selective champagne/copper accents on existing reveal and lineup circles. */
html[data-customer-theme="starlight_christmas_hollow"] body :is(.hp-step-num, .jp-benefit-icon, .hp-trade-preview-pill .pos, .hp-queue-modal-row .pos) {
  background: linear-gradient(135deg, #c98950, #f2c77b 48%, #b87540);
  color: #11263c;
  border-color: #a66a3c;
  box-shadow: inset 0 0 0 1px #f2c77b88;
}

/* Existing dialog, lineup and form states keep their original dimensions. */
html[data-customer-theme="starlight_christmas_hollow"] body :is(.hp-calendar-modal, .hp-queue-modal, .hp-queue-modal-row) {
  background: #132e4b;
  color: #fff7e9;
  border-color: #50617a;
}
html[data-customer-theme="starlight_christmas_hollow"] body .hp-queue-modal-row.now { background: #254765; }
html[data-customer-theme="starlight_christmas_hollow"] body .hp-queue-modal-row .name { color: #fff7e9; }
html[data-customer-theme="starlight_christmas_hollow"] body .hp-queue-modal-row .label { color: #c5d5e5; }
html[data-customer-theme="starlight_christmas_hollow"] body .hp-queue-modal-close { background: #132e4b; color: #fff7e9; }
html[data-customer-theme="starlight_christmas_hollow"] body .hp-queue-modal-close:hover { background: #254765; }
html[data-customer-theme="starlight_christmas_hollow"] body :is(.hp-event-copy:hover, .hp-event-copy.copied, .hp-event-collection-pill:hover) { color: #11263c; }
html[data-customer-theme="starlight_christmas_hollow"] body :is(.hp-lrq-item:not(.on-deck) .pos, .tp-lrq-row.now .pos, .tp-filter-badge, .tp-load-more, .tp-card-tier.unicorn) {
  background: #f2c77b;
  color: #11263c;
}
html[data-customer-theme="starlight_christmas_hollow"] body .tp-card-tier.unicorn .pip { background: #11263c; }
html[data-customer-theme="starlight_christmas_hollow"] body :is(.tp-empty-reset, .tp-card-close) {
  background: #132e4b;
  color: #f2c77b;
  border-color: #50617a;
}
html[data-customer-theme="starlight_christmas_hollow"] body .tp-sheet-receipt input {
  background: #132e4b;
  color: #fff7e9;
  border-color: #50617a;
}
html[data-customer-theme="starlight_christmas_hollow"] body :is(.hp-signup-input, .tp-board-search input, .tp-sheet-field input, .tp-sheet-field textarea)::placeholder {
  color: #c5d5e5;
  opacity: 1;
