/* Gobble & Fizz: approved seasonal palette and hero. Shared Amethyst layout remains locked. */
html:has(body.bg-gobble-and-fizz) {
  background: #291522;
  --bg: #291522;
  --bg-elevated: #392330;
}
body.bg-gobble-and-fizz {
  color-scheme: dark;
  --fg: #fff2df;
