  --hp-preview-bg: #392330;
  --hp-preview-fg: #fff2df;
  --hp-preview-muted: #e5cbbb;
  --hp-preview-border: #805442;
  --hp-card-fg: #fff2df;
  --hp-card-muted: #e5cbbb;
  --hp-card-accent: #efb36c;
  --hp-form-panel-bg: #392330;
  --hp-form-panel-fg: #fff2df;
  --hp-field-bg: #392330;
  --hp-field-fg: #fff2df;
  --hp-final-fg: #fff2df;
