pearl-rose.css:
/* RG-03 Pearl Rose: palette and decorative hero only. Shared Amethyst
 * fonts, spacing, header, tickers and Live Lineup geometry stay untouched. */
html:has(body.bg-pearl-rose) {
  background: #faf5ef;
  --bg: #faf5ef;
  --bg-elevated: #fffefa;
}
body.bg-pearl-rose {
  color-scheme: light;
  --fg: #4d2931;
  --fg-muted: #785963;
  --border: #dcc4b7;
  --hp-bg: #faf5ef;
  --hp-bg-elevated: #fffefa;
  --bg-deep: #f2e5dc;
  --hp-preview-bg: #fffefa;
  --hp-preview-fg: #4d2931;
  --hp-preview-muted: #785963;
  --hp-preview-border: #dcc4b7;
  --hp-card-fg: #4d2931;
  --hp-card-muted: #785963;
  --hp-card-accent: #954354;
  --hp-form-panel-bg: #fffefa;
  --hp-form-panel-fg: #4d2931;
  --hp-field-bg: #fffefa;
  --hp-field-fg: #4d2931;
  --hp-final-fg: #4d2931;
  --hp-final-muted: #785963;
  --hp-final-icon-fg: #fff9f2;
